_NOWFY_LANG_OVERRIDE = None
SUPPORTED_LANGS = ("en", "pt", "ru")


def _lang_from_index(idx, default="en"):
    try:
        codes = ["en", "pt", "ru"]
        i = int(idx)
        if 0 <= i < len(codes):
            return codes[i]
    except Exception:
        pass
    return default


def _universal_plugin_lang():
    try:
        host = globals().get("_NOWFY_HOST_PLUGIN")
        if host and hasattr(host, "get_setting"):
            lang = _lang_from_index(host.get_setting("plugin_lang", 0), "")
            if lang:
                return lang
    except Exception:
        pass
    try:
        runtime = globals().get("_NOWFY_CORE_RUNTIME")
        host = getattr(runtime, "host", None) if runtime is not None else None
        if host and hasattr(host, "get_setting"):
            lang = _lang_from_index(host.get_setting("plugin_lang", 0), "")
            if lang:
                return lang
    except Exception:
        pass
    try:
        controller = PluginsController.getInstance()
        if controller:
            p_nowfy = controller.plugins.get("nowfy")
            if p_nowfy and hasattr(p_nowfy, "get_setting"):
                lang = _lang_from_index(p_nowfy.get_setting("plugin_lang", 0), "")
                if lang:
                    return lang
            p_core = controller.plugins.get("nowfycore")
            if p_core and hasattr(p_core, "get_setting"):
                lang = _lang_from_index(p_core.get_setting("plugin_lang", 0), "")
                if lang:
                    return lang
    except Exception:
        pass
    try:
        if _NOWFY_LANG_OVERRIDE:
            return str(_NOWFY_LANG_OVERRIDE)
    except Exception:
        pass
    try:
        lang = str(Locale.getDefault().getLanguage() or "").lower()
        if lang in ("pt", "en", "ru"):
            return lang
    except Exception:
        pass
    return "en"


def tr(key):
    lang = _universal_plugin_lang()
    entry = TRANSLATIONS.get(key, {})
    return entry.get(lang) or entry.get("en") or key


def _find_method_exact(cls, name, *param_types):
    try:
        return cls.getDeclaredMethod(name, *param_types)
    except Exception:
        pass
    try:
        return cls.getMethod(name, *param_types)
    except Exception:
        pass
    try:
        sup = cls.getSuperclass()
        while sup:
            try:
                return sup.getDeclaredMethod(name, *param_types)
            except Exception:
                try:
                    return sup.getMethod(name, *param_types)
                except Exception:
                    pass
            sup = sup.getSuperclass()
    except Exception:
        pass
    return None
try:
    _ORIGINAL_LOG = log
except Exception:
    _ORIGINAL_LOG = None
try:
    _ORIGINAL_PRINT = print
except Exception:
    _ORIGINAL_PRINT = None
_NOWFY_LOGS_MUTED = True
_NOWFY_PRINT_MUTED = True
_NOWFY_ERROR_LOGS = []


def _capture_error_log(msg):
    try:
        text = str(msg)
        low = text.lower()
        if "nowfy" not in low:
            return
        # Keep all explicit Nowfy runtime lines for .report debugging, not only errors.
        is_nowfy_runtime_line = ("[nowfy]" in low) or ("[nowfy][" in low)
        keys = ["error", "erro", "exception", "traceback", "failed", "falha", "timeout", "401", "403", "429", "500"]
        if is_nowfy_runtime_line or any(k in low for k in keys):
            _NOWFY_ERROR_LOGS.append(text.strip())
            if len(_NOWFY_ERROR_LOGS) > 120:
                _NOWFY_ERROR_LOGS[:] = _NOWFY_ERROR_LOGS[-120:]
    except Exception:
        pass


def _set_log_muted(muted):
    global _NOWFY_LOGS_MUTED
    _NOWFY_LOGS_MUTED = bool(muted)


def _set_print_muted(muted):
    global _NOWFY_PRINT_MUTED
    _NOWFY_PRINT_MUTED = bool(muted)


def _log_wrapper(*args, **kwargs):
    try:
        if _NOWFY_LOGS_MUTED:
            return
        try:
            if args:
                _capture_error_log(" ".join([str(a) for a in args]))
        except Exception:
            pass
        if _ORIGINAL_LOG:
            _ORIGINAL_LOG(*args, **kwargs)
    except Exception:
        pass


def _print_wrapper(*args, **kwargs):
    try:
        if _NOWFY_PRINT_MUTED:
            return
        try:
            if args:
                _capture_error_log(" ".join([str(a) for a in args]))
        except Exception:
            pass
        if _ORIGINAL_PRINT:
            _ORIGINAL_PRINT(*args, **kwargs)
    except Exception:
        pass


def _apply_log_wrapper(enabled=True):
    global log
    if _ORIGINAL_LOG:
        log = _log_wrapper
        try:
            import android_utils as _au
            _au.log = _log_wrapper
        except Exception:
            pass


def _apply_print_wrapper(enabled=True):
    global print
    if _ORIGINAL_PRINT:
        print = _print_wrapper
        try:
            _py_builtins.print = _print_wrapper
        except Exception:
            pass
    else:
        try:
            _py_builtins.print = _ORIGINAL_PRINT
        except Exception:
            pass
_apply_log_wrapper(True)
_apply_print_wrapper(True)
