class NowfyFontPickerHook(MethodHook):

    def __init__(self, plugin):
        self.plugin = plugin

    def before_hooked_method(self, param):
        try:
            font_active = bool(getattr(self.plugin, "_font_picker_active", False))
            backup_active = bool(getattr(self.plugin, "_backup_picker_active", False))
            cover_active = bool(getattr(self.plugin, "_custom_cover_picker_active", False))
            crop_active = bool(getattr(self.plugin, "_custom_cover_crop_active", False))
            if not font_active and not backup_active and not cover_active and not crop_active:
                return
            req_code, res_code, data = param.args
            try:
                self.plugin._fonts_trace(f"onActivityResult received req={req_code} res={res_code} target={getattr(param, 'thisObject', None)}")
            except Exception:
                pass
            if backup_active and req_code == getattr(self.plugin, "_backup_picker_request", -1):
                param.setResult(None)
                self.plugin._handle_backup_picker_result(res_code, data)
                return
            if cover_active and req_code == getattr(self.plugin, "_custom_cover_picker_request", -1):
                param.setResult(None)
                self.plugin._handle_custom_cover_picker_result(res_code, data)
                return
            if crop_active and req_code == getattr(self.plugin, "_custom_cover_crop_request", -1):
                param.setResult(None)
                self.plugin._handle_custom_cover_crop_result(res_code, data)
                return
            if font_active and req_code == getattr(self.plugin, "_font_picker_request", -1):
                param.setResult(None)
                self.plugin._handle_font_picker_result(res_code, data)
        except Exception:
            pass


class NowfyCoreBackendMixin:

    def _log_throttled(self, key, message, cooldown_sec=300):
        try:
            k = str(key or "").strip()
            if not k:
                return
            now = int(time.time())
            store = getattr(self, "_nowfy_log_throttle", None)
            if not isinstance(store, dict):
                store = {}
                self._nowfy_log_throttle = store
            last = int(store.get(k, 0) or 0)
            if (now - last) < int(max(1, cooldown_sec)):
                return
            store[k] = now
        except Exception:
            pass

    def _get_statsfm_current_track(self, username):
        try:
            url = f"https://api.stats.fm/api/v1/users/{username}/streams/current"
            headers = {
                "Accept": "application/json",
                "User-Agent": "NowfyPlugin/1.0"
            }
            resp = requests.get(url, headers=headers, timeout=5)
            if resp.status_code == 200:
                data = resp.json()
                item = data.get("item")
                if not isinstance(item, dict):
                    return None
                is_playing = item.get("isPlaying")
                if is_playing is None:
                    is_playing = data.get("isPlaying")
                if is_playing is False:
                    return None
                track_info = item.get("track") if isinstance(item.get("track"), dict) else {}
                if not track_info:
                    return None
                self._set_tab_feedback_progress(40)
                artists = [artist.get("name", "") for artist in (track_info.get("artists") or []) if isinstance(artist, dict)]
                albums = track_info.get("albums") if isinstance(track_info.get("albums"), list) else []
                album = albums[0] if albums and isinstance(albums[0], dict) else {}
                image_url = str(album.get("image", "") or "").strip()
                if image_url.startswith("//"):
                    image_url = "https:" + image_url
                elif image_url.startswith("http://"):
                    image_url = "https://" + image_url[7:]
                return {
                    'title': track_info.get("name", ""),
                    'artist': ", ".join([a for a in artists if a]),
                    'album': album.get("name", ""),
                    'image_url': image_url,
                    'duration_ms': track_info.get("durationMs", 0),
                    'progress_ms': item.get("progressMs", 0)
                }
            return None
        except Exception as e:
            self._log_throttled(
                "nowcast_statsfm_current_error",
                f"[NowCast] Stats.fm error: {str(e)}",
                cooldown_sec=300
            )
            return None

    def _get_lastfm_current_track(self, username, api_key):
        try:
            url = "https://ws.audioscrobbler.com/2.0/"
            params = {
                'method': 'user.getrecenttracks',
                'user': username,
                'api_key': api_key,
                'format': 'json',
                'limit': 1
            }
            resp = requests.get(url, params=params, timeout=5)
            if resp.status_code == 200:
                data = resp.json()
                tracks = data.get('recenttracks', {}).get('track', [])
                if tracks and isinstance(tracks, list) and len(tracks) > 0:
                    track = tracks[0]
                    if True:
                        artist = track.get('artist', {}).get('#text', '') if isinstance(track.get('artist'), dict) else str(track.get('artist', ''))
                        album = track.get('album', {}).get('#text', '') if isinstance(track.get('album'), dict) else str(track.get('album', ''))
                        images = track.get('image', [])
                        image_url = ''
                        if images:
                            size_priority = ['mega', 'extralarge', 'large']
                            size_map = {img.get('size'): img.get('#text', '') for img in images if img.get('#text')}
                            for s in size_priority:
                                if size_map.get(s):
                                    image_url = size_map[s]
                                    break
                            if not image_url:
                                for img in reversed(images):
                                    if img.get('#text'):
                                        image_url = img.get('#text', '')
                                        break
                        if isinstance(image_url, str) and image_url.startswith("http://"):
                            image_url = "https://" + image_url[7:]
                        return {
                            'title': self._normalize_lastfm_track_title(track),
                            'artist': artist,
                            'album': album,
                            'image_url': image_url,
                            'url': str(track.get('url') or '').strip(),
                            'duration_ms': 0,
                            'progress_ms': 0
                        }
            return None
        except Exception as e:
            return None

    def _track_hub_get_backend_base(self):
        try:
            base = ""
            try:
                base = str(self._get_quick_spotify_backend_base() or "").strip()
            except Exception:
                base = str(self.get_setting("quick_spotify_backend_base", "") or "").strip()
            if not base:
                base = "https://nowfy.meyankut.workers.dev"
            if base.endswith("/"):
                base = base[:-1]
            return base
        except Exception:
            return "https://nowfy.meyankut.workers.dev"

    def _track_hub_get_current_uid(self):
        try:
            acct = UserConfig.selectedAccount
            uc = UserConfig.getInstance(acct)
            user = uc.getCurrentUser()
            if user and getattr(user, "id", 0):
                return int(user.id)
        except Exception:
            pass
        return 0

    def _track_hub_get_source_options(self):
        sources = []
        labels = []
        try:
            if self._has_spotify_credentials():
                sources.append("spotify")
                labels.append("Spotify")
        except Exception:
            pass
        try:
            lastfm_user = str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", "")) or "").strip()
            lastfm_key = str(self.get_setting("lastfm_api_key", "") or "").strip()
            if lastfm_user and lastfm_key:
                sources.append("lastfm")
                labels.append("Last.fm")
        except Exception:
            pass
        try:
            stats_user = str(self.get_setting("statsfm_username", "") or "").strip()
            if stats_user:
                sources.append("statsfm")
                labels.append("Stats.fm")
        except Exception:
            pass
        if not sources:
            sources = ["spotify"]
            labels = ["Spotify"]
        return sources, labels

    def _track_hub_resolve_source(self):
        try:
            sources, _labels = self._track_hub_get_source_options()
            if len(sources) <= 1:
                return sources[0], sources, True
            idx = int(self.get_setting("track_hub_source_idx", 0) or 0)
            if idx < 0 or idx >= len(sources):
                idx = 0
            return sources[idx], sources, False
        except Exception:
            return "spotify", ["spotify"], True

    def _track_hub_get_source_profile_link(self, source_key):
        try:
            source = str(source_key or "").strip().lower()
            if source == "lastfm":
                user = str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", "")) or "").strip()
                if user:
                    return f"https://www.last.fm/user/{quote(user, safe='')}", "Last.fm"
            if source == "statsfm":
                user = str(self.get_setting("statsfm_username", "") or "").strip().lstrip("@")
                if user:
                    return f"https://stats.fm/{quote(user, safe='')}", "Stats.fm"
            if source == "spotify":
                try:
                    profile = self._get_spotify_user_profile() or {}
                    sid = str(profile.get("id", "") or "").strip()
                    if sid:
                        return f"https://open.spotify.com/user/{quote(sid, safe='')}", "Spotify"
                except Exception:
                    pass
            return "", ""
        except Exception:
            return "", ""

    def _track_hub_build_track_links(self, source_key, title, artist, track_id=""):
        try:
            source = str(source_key or "").strip().lower()
            spotify_url = ""
            try:
                tid = str(track_id or "").strip()
                if source == "spotify" and tid:
                    spotify_url = f"https://open.spotify.com/track/{quote(tid, safe='')}"
            except Exception:
                spotify_url = ""
            if not spotify_url and str(title or "").strip():
                try:
                    spotify_url = str(self._search_spotify_url(str(title or ""), str(artist or "")) or "").strip()
                except Exception:
                    spotify_url = ""
            song_link_url = ""
            if spotify_url:
                try:
                    song_link_url = str(self._get_song_link(spotify_url) or "").strip()
                except Exception:
                    song_link_url = ""
            source_link, source_label = self._track_hub_get_source_profile_link(source)
            return {
                "spotify_url": spotify_url,
                "song_link_url": song_link_url,
                "source_url": source_link,
                "source_label": source_label or "Source",
            }
        except Exception:
            return {
                "spotify_url": "",
                "song_link_url": "",
                "source_url": "",
                "source_label": "Source",
            }

    def _track_hub_compact_artist(self, artist_text, max_len=42):
        try:
            txt = str(artist_text or "").strip()
            if not txt:
                return "Powered by Nowfy"
            lowered = txt.lower()
            for sep in [" feat. ", " feat ", " ft. ", " ft ", ","]:
                pos = lowered.find(sep)
                if pos > 0:
                    txt = txt[:pos].strip()
                    break
            if len(txt) > int(max_len):
                txt = txt[:int(max_len) - 1].rstrip() + "…"
            return txt or "Powered by Nowfy"
        except Exception:
            return "Powered by Nowfy"

    def _track_hub_get_player_label(self, source_key):
        try:
            source = str(source_key or "").strip().lower()
            if source == "spotify":
                return "Spotify"
            if source == "statsfm":
                try:
                    idx = int(self.get_setting("statsfm_source_player", 0) or 0)
                except Exception:
                    idx = 0
                return "Apple Music" if idx == 1 else "Spotify"
            if source == "lastfm":
                try:
                    player = str(self._detect_current_player() or "").strip()
                except Exception:
                    player = ""
                if not player or player == "FM":
                    return "Last.fm"
                return player
            return "Spotify"
        except Exception:
            return "Spotify"

    def _track_hub_build_payload(self, source_key=None):
        try:
            source = str(source_key or "").strip().lower()
            if not source:
                source, _srcs, _auto = self._track_hub_resolve_source()
            payload = {
                "title": "",
                "artist": "",
                "cover_url": "",
                "source": source,
                "link_url": "",
                "link_label": "",
                "player": self._track_hub_get_player_label(source),
                "playing": False,
                "ts": int(time.time())
            }
            track_id = ""
            if source == "spotify":
                trk = self._get_spotify_current_track_simple()
                if trk:
                    payload["title"] = str(trk.get("name", "") or "").strip()
                    payload["artist"] = self._track_hub_compact_artist(str(trk.get("artist", "") or "").strip())
                    payload["cover_url"] = str(trk.get("cover_url", "") or "").strip()
                    track_id = str(trk.get("id", "") or "").strip()
                    payload["playing"] = bool(payload["title"])
            elif source == "lastfm":
                user = str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", "")) or "").strip()
                key = str(self.get_setting("lastfm_api_key", "") or "").strip()
                if user and key:
                    trk = self._get_lastfm_current_track(user, key)
                    if trk:
                        payload["title"] = str(trk.get("title", "") or "").strip()
                        payload["artist"] = self._track_hub_compact_artist(str(trk.get("artist", "") or "").strip())
                        payload["cover_url"] = str(trk.get("image_url", "") or "").strip()
                        payload["playing"] = bool(payload["title"])
            elif source == "statsfm":
                user = str(self.get_setting("statsfm_username", "") or "").strip().lstrip("@")
                if user:
                    trk = self._get_statsfm_current_track(user)
                    if trk:
                        payload["title"] = str(trk.get("title", "") or "").strip()
                        payload["artist"] = self._track_hub_compact_artist(str(trk.get("artist", "") or "").strip())
                        payload["cover_url"] = str(trk.get("image_url", "") or "").strip()
                        payload["playing"] = bool(payload["title"])
            payload["link_url"] = ""
            payload["link_label"] = ""
            if not payload["title"]:
                payload["title"] = tr("track_hub_empty_title")
                payload["artist"] = "Powered by Nowfy"
                payload["cover_url"] = "https://assets.nowfy/nowfy.png"
                payload["link_url"] = ""
                payload["link_label"] = ""
                payload["player"] = self._track_hub_get_player_label(source)
                payload["playing"] = False
            return payload
        except Exception:
            return {
                "title": tr("track_hub_empty_title"),
                "artist": "Powered by Nowfy",
                "cover_url": "https://assets.nowfy/nowfy.png",
                "source": str(source_key or "spotify"),
                "link_url": "",
                "link_label": "",
                "player": self._track_hub_get_player_label(source_key or "spotify"),
                "playing": False,
                "ts": int(time.time())
            }

    def _track_hub_publish_payload(self, payload=None):
        try:
            uid = int(self._track_hub_get_current_uid() or 0)
            if uid == 0:
                try:
                    pass
                except Exception:
                    pass
                return False
            data = payload if isinstance(payload, dict) else self._track_hub_build_payload()
            try:
                log(
                    "[Nowfy][TrackHub] payload: "
                    f"source={str(data.get('source', ''))} "
                    f"title={str(data.get('title', ''))[:80]} "
                    f"artist={str(data.get('artist', ''))[:80]}"
                )
            except Exception:
                pass
            try:
                self.set_setting("track_hub_last_payload", json.dumps(data, ensure_ascii=False))
                self.set_setting("track_hub_last_payload_ts", str(int(time.time())))
            except Exception:
                pass
            base = self._track_hub_get_backend_base()
            resp = requests.post(
                f"{base}/trackhub/publish",
                json={"id": str(uid), "payload": data},
                timeout=7
            )
            try:
                pass
            except Exception:
                pass
            return bool(resp.status_code == 200)
        except Exception:
            try:
                pass
            except Exception:
                pass
            return False

    def _track_hub_fetch_public_payload(self, profile_id):
        try:
            pid = int(profile_id or 0)
            if pid == 0:
                return None
            base = self._track_hub_get_backend_base()
            resp = requests.get(
                f"{base}/trackhub/get",
                params={"id": str(pid)},
                timeout=7
            )
            if resp.status_code != 200 or not resp.content:
                return None
            data = resp.json()
            if not isinstance(data, dict):
                return None
            payload = data.get("payload")
            if not isinstance(payload, dict):
                return None
            return payload
        except Exception:
            return None

    def _track_hub_get_local_payload(self):
        try:
            raw = str(self.get_setting("track_hub_last_payload", "") or "").strip()
            if not raw:
                return None
            data = json.loads(raw)
            return data if isinstance(data, dict) else None
        except Exception:
            return None

    def _track_hub_get_profile_payload(self, profile_id, force_refresh=False):
        try:
            pid = int(profile_id or 0)
            me = int(self._track_hub_get_current_uid() or 0)
            if pid != 0 and me != 0 and pid == me:
                cache_ts = 0
                try:
                    cache_ts = int(self.get_setting("track_hub_last_payload_ts", "0") or 0)
                except Exception:
                    cache_ts = 0
                if (not force_refresh) and cache_ts and (int(time.time()) - cache_ts) <= 15:
                    cached = self._track_hub_get_local_payload()
                    if isinstance(cached, dict):
                        return cached
                payload = self._track_hub_build_payload()
                try:
                    self._track_hub_publish_payload(payload)
                except Exception:
                    pass
                return payload
            public_payload = self._track_hub_fetch_public_payload(pid)
            if isinstance(public_payload, dict):
                return public_payload
            return {
                "title": tr("track_hub_empty_title"),
                "artist": "Powered by Nowfy",
                "cover_url": "https://assets.nowfy/nowfy.png",
                "source": "none",
                "link_url": "",
                "link_label": "",
                "playing": False,
                "ts": int(time.time())
            }
        except Exception:
            return {
                "title": tr("track_hub_empty_title"),
                "artist": "Powered by Nowfy",
                "cover_url": "https://assets.nowfy/nowfy.png",
                "source": "none",
                "link_url": "",
                "link_label": "",
                "playing": False,
                "ts": int(time.time())
            }

    def _sanitize_track_title(self, title: str) -> str:
        try:
            t = str(title or "")
            t = re.sub(r"\([^\)]*\)", "", t)
            t = re.sub(r"\b(feat(:uring)|ft)\b\.\s*.*$", "", t, flags=re.IGNORECASE)
            t = re.sub(r"[\-–|•\/]+\s*$", "", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t
        except Exception:
            return str(title or "")

