    def _show_nowplaying_pill(self, info):
        try:
            fragment = get_last_fragment()
            if not fragment:
                return
            context = fragment.getParentActivity()
            if not context:
                return
            title = str(info.get("name", "") or info.get("title", "") or "").strip()
            artist = str(info.get("artist", "") or "").strip()
            if not title:
                return
            try:
                style_idx = int(self.get_setting("nowplaying_pill_style", 0) or 0)
            except Exception:
                style_idx = 0
            in_chat = False
            try:
                in_chat = isinstance(fragment, ChatActivity)
            except Exception:
                in_chat = False
            if not in_chat:
                try:
                    cname = str(fragment.getClass().getName() or "")
                    in_chat = ("ChatActivity" in cname)
                except Exception:
                    in_chat = False
            if style_idx == 1 and in_chat:
                try:
                    self._show_nowplaying_applefy_in_chat(fragment, context, title, artist, info)
                except Exception as e:
                    try:
                        pass
                    except Exception:
                        pass
                return
            container = LinearLayout(context)
            container.setOrientation(0)
            container.setGravity(Gravity.CENTER_VERTICAL)
            bg = GradientDrawable()
            bg.setCornerRadius(AndroidUtilities.dp(24))
            bg.setColor(Theme.getColor(Theme.key_undo_background))
            container.setBackground(bg)
            container.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(8), AndroidUtilities.dp(16), AndroidUtilities.dp(8))
            text_layout = LinearLayout(context)
            text_layout.setOrientation(1)
            title_view = TextView(context)
            title_view.setText(tr("nowfy_pill_prefix") if "nowfy_pill_prefix" in TRANSLATIONS else "Now Playing")
            title_view.setTextColor(Theme.getColor(Theme.key_undo_infoColor))
            title_view.setTextSize(1, 14.0)
            try:
                title_view.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
            except Exception:
                pass
            text_layout.addView(title_view)
            subtitle = TextView(context)
            subtitle.setText(title if not artist else f"{title} — {artist}")
            subtitle.setTextColor(Theme.getColor(Theme.key_undo_cancelColor))
            subtitle.setTextSize(1, 12.0)
            text_layout.addView(subtitle)
            container.addView(text_layout, LayoutHelper.createLinear(-2, -2))
            parent_view = None
            try:
                parent_view = fragment.getFragmentView()
                if parent_view and not isinstance(parent_view, FrameLayout):
                    parent = parent_view.getParent()
                    if isinstance(parent, FrameLayout):
                        parent_view = parent
            except Exception:
                parent_view = None
            if not parent_view:
                parent_view = context.getWindow().getDecorView()
            if parent_view and isinstance(parent_view, FrameLayout):
                params = LayoutHelper.createFrame(-2, -2, Gravity.TOP | Gravity.LEFT, 16, 40, 0, 0)
                container.setLayoutParams(params)
                container.setOnClickListener(OnClickListener(lambda v: AndroidUtilities.removeFromParent(container)))
                parent_view.addView(container)
                def _remove():
                    try:
                        if container.getParent():
                            AndroidUtilities.removeFromParent(container)
                    except Exception:
                        pass
                try:
                    from java.lang import Runnable
                    class _NowfyRemoveRunnable(dynamic_proxy(Runnable)):
                        def run(self):
                            try:
                                _remove()
                            except Exception:
                                pass
                    container.postDelayed(_NowfyRemoveRunnable(), 3000)
                except Exception:
                    try:
                        AndroidUtilities.runOnUIThread(_remove, 3000)
                    except Exception:
                        pass
        except Exception:
            pass

