    def _start_header_cover_worker(self):
        try:
            if getattr(self, "_header_cover_thread", None):
                if getattr(self._header_cover_thread, "is_alive", lambda: False)():
                    return
            stop_event = threading.Event()
            self._header_cover_stop_event = stop_event
            def _loop():
                last_key = getattr(self, "_header_cover_last_key", "")
                last_cover = getattr(self, "_header_cover_last_url", "")
                while self._header_cover_stop_event and not self._header_cover_stop_event.is_set():
                    try:
                        allow_dynamic = True
                        enabled = True
                        try:
                            enabled = bool(self.get_setting("header_cover_enabled", True))
                            show_mode = int(self.get_setting("header_cover_show_mode", 0))
                            allow_dynamic = (show_mode == 0)
                        except Exception:
                            allow_dynamic = True
                        bg_cover = getattr(self, "_header_cover_view", None)
                        if not bg_cover:
                            time.sleep(4)
                            continue
                        try:
                            custom_selected = int(self.get_setting("custom_cover_selection", 0)) == 1
                        except Exception:
                            custom_selected = False
                        try:
                            force_nowfy = bool(self.get_setting("custom_cover_force_nowfy", False))
                        except Exception:
                            force_nowfy = False
                        if force_nowfy:
                            allow_dynamic = False
                        if not enabled:
                            try:
                                if bg_cover:
                                    def _hide():
                                        try:
                                            bg_cover.setImageBitmap(None)
                                        except Exception:
                                            pass
                                        try:
                                            gif_view = getattr(self, "_header_cover_gif_view", None)
                                            if gif_view:
                                                gif_view.setImageDrawable(None)
                                                gif_view.setVisibility(View.GONE)
                                        except Exception:
                                            pass
                                        try:
                                            self._set_header_cover_shadow_visible(False)
                                        except Exception:
                                            pass
                                        try:
                                            bg_cover.setImageDrawable(None)
                                        except Exception:
                                            pass
                                        try:
                                            bg_cover.setVisibility(View.GONE)
                                        except Exception:
                                            pass
                                    run_on_ui_thread(_hide)
                            except Exception:
                                pass
                            time.sleep(6)
                            continue
                        if custom_selected:
                            custom_path = self._get_custom_cover_path()
                            if not custom_path:
                                try:
                                    self.set_setting("custom_cover_selection", 0)
                                except Exception:
                                    pass
                                custom_selected = False
                            if custom_selected and custom_path:
                                try:
                                    mtime = 0
                                    try:
                                        mtime = int(os.path.getmtime(custom_path))
                                    except Exception:
                                        mtime = 0
                                    key = f"custom|{custom_path}|{mtime}"
                                except Exception:
                                    key = f"custom|{custom_path}"
                                if key != last_key:
                                    last_key = key
                                    last_cover = custom_path
                                    try:
                                        self._header_cover_last_key = last_key
                                        self._header_cover_last_url = last_cover
                                    except Exception:
                                        pass
                                    threading.Thread(
                                        target=lambda: self._apply_header_cover_local_file(bg_cover, custom_path),
                                        daemon=True
                                    ).start()
                                time.sleep(6)
                                continue
                        cover_url = None
                        key = ""
                        if allow_dynamic:
                            info = self._get_current_track_info()
                            cover_url = info.get("cover_url") if info else None
                            if info:
                                key = info.get("unique_key") or f"{info.get('source')}|{info.get('name') or info.get('title')}|{info.get('artist')}"
                            if not cover_url:
                                try:
                                    t = self._get_spotify_current_track_simple()
                                    if t:
                                        cover_url = t.get("cover_url")
                                        key = key or t.get("unique_key") or f"spotify|{t.get('name') or t.get('title')}|{t.get('artist')}"
                                except Exception:
                                    pass
                            if not cover_url:
                                try:
                                    cover_url = getattr(self, "_di_last_cover_url", None)
                                except Exception:
                                    cover_url = None
                        if not cover_url:
                            try:
                                refresh_fallback = False
                                try:
                                    refresh_fallback = bool(getattr(self, "_header_fallback_refresh", False))
                                except Exception:
                                    refresh_fallback = False
                                if refresh_fallback:
                                    cover_url = self._get_header_fallback_url()
                                    try:
                                        self._header_fallback_refresh = False
                                    except Exception:
                                        pass
                                else:
                                    cover_url = last_cover if last_cover in HEADER_FALLBACK_COVERS else None
                                    if not cover_url:
                                        cover_url = self._get_header_fallback_url()
                                if cover_url:
                                    key = key or f"fallback|{cover_url}"
                            except Exception:
                                cover_url = None
                        if cover_url and (cover_url != last_cover or (key and key != last_key)):
                            last_key = key or last_key
                            last_cover = cover_url
                            self._header_cover_last_key = last_key
                            self._header_cover_last_url = last_cover
                            threading.Thread(target=lambda: self._apply_header_cover_from_url(bg_cover, cover_url), daemon=True).start()
                    except Exception:
                        pass
                    try:
                        time.sleep(6)
                    except Exception:
                        break
            t = threading.Thread(target=_loop, daemon=True)
            self._header_cover_thread = t
            t.start()
        except Exception:
            pass

    def _stop_header_cover_worker(self):
        try:
            ev = getattr(self, "_header_cover_stop_event", None)
            if ev:
                ev.set()
        except Exception:
            pass
        self._header_cover_stop_event = None

    def _apply_header_cover_settings_consistency(self):
        try:
            enabled = bool(self.get_setting("header_cover_enabled", True))
            show_mode = int(self.get_setting("header_cover_show_mode", 0))
        except Exception:
            enabled = True
            show_mode = 0
        try:
            bg_cover = getattr(self, "_header_cover_view", None)
        except Exception:
            bg_cover = None
        if not enabled:
            try:
                self._stop_header_cover_worker()
            except Exception:
                pass
            try:
                self._header_cover_last_key = ""
                self._header_cover_last_url = ""
            except Exception:
                pass
            try:
                if bg_cover:
                    bg_cover.setVisibility(View.GONE)
                    try:
                        self._set_header_cover_shadow_visible(False)
                    except Exception:
                        pass
                    self._set_header_cover_text_mode(False)
            except Exception:
                pass
            try:
                if hasattr(self, "_refresh_header_action_icons"):
                    self._refresh_header_action_icons()
            except Exception:
                pass
            return
        try:
            if not getattr(self, "_header_cover_thread", None) or not getattr(self._header_cover_thread, "is_alive", lambda: False)():
                self._start_header_cover_worker()
        except Exception:
            pass
        try:
            custom_selected = int(self.get_setting("custom_cover_selection", 0)) == 1
        except Exception:
            custom_selected = False
        try:
            self._header_cover_last_key = ""
            self._header_cover_last_url = ""
        except Exception:
            pass
        try:
            if bg_cover:
                if custom_selected:
                    try:
                        path = self._get_custom_cover_path()
                    except Exception:
                        path = ""
                    if path:
                        try:
                            self._apply_header_cover_local_file(bg_cover, path)
                            return
                        except Exception:
                            pass
                fallback = None
                try:
                    fallback = self._get_header_fallback_url()
                except Exception:
                    fallback = None
                if (show_mode != 0) or True:
                    if fallback:
                        try:
                            self._apply_header_cover_from_url(bg_cover, fallback)
                        except Exception:
                            try:
                                self._set_header_cover_text_mode(True)
                            except Exception:
                                pass
                    else:
                        try:
                            self._set_header_cover_text_mode(True)
                        except Exception:
                            pass
        except Exception:
            pass
        try:
            if hasattr(self, "_refresh_header_action_icons"):
                self._refresh_header_action_icons()
        except Exception:
            pass

    def _update_hooking_hint(self, data, cell_hint=None):
        try:
            cell = cell_hint if cell_hint is not None else self._get_dialogs_hint_cell()
            if not cell:
                return
            title = tr("hooking_now_title") if "hooking_now_title" in TRANSLATIONS else "Now Playing:"
            song = str(data.get("title", "") or data.get("name", "") or "").strip()
            artist = str(data.get("artist", "") or "").strip()
            byp = tr("hooking_by_prefix") if "hooking_by_prefix" in TRANSLATIONS else "by"
            desc = f"{song}\n{byp} {artist}"
            changed = True
            try:
                stamp = f"{title}|{desc}"
                if getattr(self, "_hooking_last_text", None) == stamp:
                    changed = False
                else:
                    self._hooking_last_text = stamp
            except Exception:
                changed = True
            if changed:
                self._set_nowbox_hint_text(cell, title, desc)
            try:
                self._force_nowbox_hint_visibility(cell)
            except Exception:
                pass
            try:
                self._schedule_nowbox_hint_reapply(cell_hint=cell)
            except Exception:
                pass
            try:
                if getattr(self, "_hooking_cover_view", None):
                    self._hooking_cover_view.setVisibility(View.GONE)
            except Exception:
                pass
            try:
                playing = bool(song and artist)
                self._update_nowbox_eq_indicator(cell, playing)
            except Exception:
                pass
            try:
                if hasattr(cell, "setVisibility"):
                    cell.setVisibility(0)
                if hasattr(cell, "requestLayout"):
                    cell.requestLayout()
                if hasattr(cell, "invalidate"):
                    cell.invalidate()
            except Exception:
                pass
            try:
                self._attach_hooking_gestures(cell)
            except Exception:
                pass
        except Exception:
            pass

    def _force_nowbox_hint_visibility(self, cell):
        try:
            if not cell:
                return
            node = cell
            for _ in range(4):
                if not node:
                    break
                try:
                    if hasattr(node, "setVisibility"):
                        node.setVisibility(0)
                except Exception:
                    pass
                try:
                    if hasattr(node, "setAlpha"):
                        node.setAlpha(1.0)
                except Exception:
                    pass
                try:
                    if hasattr(node, "setTranslationY"):
                        node.setTranslationY(0.0)
                except Exception:
                    pass
                try:
                    if hasattr(node, "requestLayout"):
                        node.requestLayout()
                    if hasattr(node, "invalidate"):
                        node.invalidate()
                except Exception:
                    pass
                try:
                    node = node.getParent() if hasattr(node, "getParent") else None
                except Exception:
                    node = None
        except Exception:
            pass

    def _schedule_nowbox_hint_reapply(self, cell_hint=None):
        try:
            def _reapply():
                try:
                    cell = cell_hint if cell_hint is not None else self._get_dialogs_hint_cell()
                    if not cell:
                        return
                    self._force_nowbox_hint_visibility(cell)
                except Exception:
                    pass
            try:
                run_on_ui_thread(_reapply)
            except Exception:
                _reapply()
            try:
                run_on_ui_thread(_reapply, delay=140)
            except Exception:
                pass
            try:
                run_on_ui_thread(_reapply, delay=320)
            except Exception:
                pass
        except Exception:
            pass

    def _set_nowbox_hint_text(self, cell, title, desc):
        try:
            if hasattr(cell, "setText"):
                try:
                    cell.setText(title, desc)
                    return
                except Exception:
                    try:
                        cell.setText(title)
                        return
                    except Exception:
                        pass
            # Fallback path for UnconfirmedAuthHintCell-like views.
            tview = None
            mview = None
            for fn in ("titleView", "titleTextView"):
                try:
                    tview = get_private_field(cell, fn)
                except Exception:
                    tview = None
                if tview:
                    break
            for fn in ("messageView", "messageTextView"):
                try:
                    mview = get_private_field(cell, fn)
                except Exception:
                    mview = None
                if mview:
                    break
            if tview and hasattr(tview, "setText"):
                try:
                    tview.setText(str(title or ""))
                except Exception:
                    pass
            if mview and hasattr(mview, "setText"):
                try:
                    mview.setText(str(desc or ""))
                except Exception:
                    pass
        except Exception:
            pass

    def _start_hooking_worker(self):
        try:
            if getattr(self, "_hooking_thread", None):
                if getattr(self._hooking_thread, "is_alive", lambda: False)():
                    return
            stop_event = threading.Event()
            self._hooking_stop_event = stop_event
            try:
                self._hooking_last_active_ts = float(_t.time())
            except Exception:
                self._hooking_last_active_ts = 0.0
            def _worker():
                try:
                    if not hasattr(self, "_hooking_interval"):
                        self._hooking_interval = 2.0
                    while self.get_setting("hooking_enabled", False) and self._hooking_stop_event and not self._hooking_stop_event.is_set():
                        try:
                            if not self._is_chatlist_active():
                                _t.sleep(8)
                                continue
                            data = self._get_track_for_hooking()
                            now_ts = float(_t.time())
                            is_playing = True
                            try:
                                if isinstance(data, dict) and data.get("is_playing") is False:
                                    is_playing = False
                            except Exception:
                                pass
                            if data and is_playing and (data.get("title") or data.get("name")) and data.get("artist"):
                                try:
                                    key = "|".join([
                                        str(data.get("source", "") or "").strip(),
                                        str(data.get("unique_key", "") or "").strip(),
                                        str(data.get("id", "") or "").strip(),
                                        str(data.get("title", "") or data.get("name", "") or "").strip(),
                                        str(data.get("artist", "") or "").strip(),
                                        str(data.get("album", "") or "").strip(),
                                    ])
                                except Exception:
                                    key = ""
                                cover_key = ""
                                try:
                                    cover_key = str(data.get("cover_url", "") or "").strip()
                                except Exception:
                                    cover_key = ""
                                changed = True
                                try:
                                    last_key = getattr(self, "_hooking_last_key", "")
                                    last_cover_key = str(getattr(self, "_hooking_last_cover_key", "") or "")
                                    changed = (key != last_key) or (cover_key != last_cover_key)
                                    if changed:
                                        self._hooking_last_key = key
                                        self._hooking_last_cover_key = cover_key
                                except Exception:
                                    changed = True
                                if changed:
                                    try:
                                        run_on_ui_thread(lambda: self._update_hooking_hint(data))
                                    except Exception:
                                        self._update_hooking_hint(data)
                                    try:
                                        if bool(self.get_setting("nowbox_lyrics_enabled", False)):
                                            title = str(data.get("name", "") or data.get("title", "") or "").strip()
                                            artist = str(data.get("artist", "") or "").strip()
                                            try:
                                                last_key_pref = getattr(self, "_nowbox_prefetch_key", "")
                                                key_pref = self._lyrics_cache_key(title, artist)
                                                if key_pref and key_pref != last_key_pref:
                                                    self._nowbox_prefetch_key = key_pref
                                                    self._prefetch_lyrics_for_track(title, artist)
                                            except Exception:
                                                pass
                                    except Exception:
                                        pass
                                    try:
                                        self._hooking_interval = 2.0
                                    except Exception:
                                        pass
                                try:
                                    if bool(self.get_setting("nowbox_show_cover_actionbar", False)):
                                        cov = data.get("cover_url")
                                        if not cov:
                                            try:
                                                title = str(data.get("name", "") or data.get("title", "") or "")
                                                artist = str(data.get("artist", "") or "")
                                                yt = self._get_youtube_cover(title, artist)
                                                if yt and "icondefault.png" not in yt:
                                                    cov = yt
                                            except Exception:
                                                cov = None
                                        if cov:
                                            try:
                                                self._di_last_cover_url = cov
                                            except Exception:
                                                pass
                                        try:
                                            last_apply = float(getattr(self, "_nowbox_banner_last_apply_ts", 0.0) or 0.0)
                                        except Exception:
                                            last_apply = 0.0
                                        if changed or (now_ts - last_apply) >= 1.8:
                                            self._apply_nowbox_cover_banner()
                                            try:
                                                self._nowbox_banner_last_apply_ts = now_ts
                                            except Exception:
                                                pass
                                    else:
                                        self._restore_nowbox_banner()
                                except Exception:
                                    pass
                                self._hooking_last_active_ts = now_ts
                            else:
                                try:
                                    self._restore_nowbox_banner()
                                except Exception:
                                    pass
                                last_ts = float(getattr(self, "_hooking_last_active_ts", now_ts))
                                if (now_ts - last_ts) >= 300.0:
                                    try:
                                        cell = self._get_dialogs_hint_cell()
                                        if cell and hasattr(cell, "setVisibility"):
                                            cell.setVisibility(8)
                                    except Exception:
                                        pass
                                    try:
                                        if bool(self.get_setting("hooking_enabled", False)):
                                            self.set_setting("hooking_enabled", False)
                                        self._hooking_stop_event.set()
                                        self._hooking_stop_event = None
                                        self.reload_settings()
                                    except Exception:
                                        pass
                        except Exception:
                            pass
                        try:
                            interval = float(getattr(self, "_hooking_interval", 2.0) or 2.0)
                        except Exception:
                            interval = 2.0
                        try:
                            if not changed:
                                interval = 2.0
                                self._hooking_interval = 2.0
                        except Exception:
                            pass
                        _t.sleep(interval)
                except Exception:
                    pass
            t = threading.Thread(target=_worker, daemon=True)
            self._hooking_thread = t
            try:
                t.start()
            except Exception:
                pass
        except Exception:
            pass

    def _stop_hooking_worker(self):
        try:
            ev = getattr(self, "_hooking_stop_event", None)
            if ev:
                try:
                    ev.set()
                except Exception:
                    pass
            self._hooking_stop_event = None
            try:
                hh = list(getattr(self, "_nowbox_hint_hooks", []) or [])
                for _h in hh:
                    try:
                        self.unhook_method(_h)
                    except Exception:
                        pass
                self._nowbox_hint_hooks = []
            except Exception:
                pass
            try:
                cell = self._get_dialogs_hint_cell()
                if cell and hasattr(cell, "setVisibility"):
                    cell.setVisibility(8)
            except Exception:
                pass
        except Exception:
            pass

    def _get_update_dialogs_hint_method(self):
        try:
            DialogsActivityClass = find_class("org.telegram.ui.DialogsActivity")
            if DialogsActivityClass is None:
                return None
            try:
                m = DialogsActivityClass.getDeclaredMethod("updateDialogsHint")
                return m
            except Exception:
                pass
            try:
                for mm in DialogsActivityClass.getDeclaredMethods():
                    try:
                        if str(mm.getName()) == "updateDialogsHint":
                            return mm
                    except Exception:
                        pass
            except Exception:
                pass
            try:
                m = DialogsActivityClass.getClass().getDeclaredMethod("updateDialogsHint")
                return m
            except Exception:
                pass
            try:
                for mm in DialogsActivityClass.getClass().getDeclaredMethods():
                    try:
                        if str(mm.getName()) == "updateDialogsHint":
                            return mm
                    except Exception:
                        pass
            except Exception:
                pass
            return None
        except Exception:
            return None

    def _get_private_field(self, obj, name):
        try:
            return get_private_field(obj, name)
        except Exception:
            return None

    def _get_dialogs_hint_cell(self):
        try:
            cell = getattr(self, "_last_hint_cell", None)
            if cell:
                try:
                    if hasattr(cell, "getParent") and cell.getParent() is not None:
                        return cell
                except Exception:
                    pass
            fragment = get_last_fragment()
            if fragment and "DialogsActivity" in fragment.getClass().getName():
                c = None
                fallback_hidden = None
                for fname in (
                    "authHintCell",
                    "dialogsHintCell",
                    "dialogsHintCellContainer",
                    "hintCell",
                    "hintView",
                    "dialogsHintView",
                ):
                    try:
                        c = get_private_field(fragment, fname)
                    except Exception:
                        c = None
                    if c:
                        try:
                            if hasattr(c, "getVisibility") and int(c.getVisibility()) != 0:
                                if fallback_hidden is None:
                                    fallback_hidden = c
                                continue
                        except Exception:
                            pass
                        break
                if c is None:
                    c = fallback_hidden
                if c:
                    try:
                        self._last_hint_cell = c
                    except Exception:
                        pass
                    return c
        except Exception:
            pass
        return None

    def _is_chatlist_active(self):
        try:
            fragment = get_last_fragment()
            if fragment:
                cname = str(fragment.getClass().getName() or "")
                if ("DialogsActivity" in cname) or ("Dialogs" in cname):
                    return True
                for fname in ("dialogsHintCell", "dialogsHintCellContainer", "dialogsAdapter", "listView"):
                    try:
                        v = get_private_field(fragment, fname)
                    except Exception:
                        v = None
                    if v is not None:
                        return True
                try:
                    if hasattr(fragment, "getActionBar") and fragment.getActionBar() is not None and ("ChatActivity" not in cname):
                        return True
                except Exception:
                    pass
        except Exception:
            pass
        return False

    def _resolve_nowbox_actionbar_target(self, fragment_hint=None):
        try:
            def _is_valid_target(frag):
                if not frag:
                    return False
                try:
                    name = str(frag.getClass().getName() or "")
                except Exception:
                    name = ""
                if "DialogsActivity" in name:
                    return True
                try:
                    if hasattr(frag, "dialogsHintCell"):
                        return True
                except Exception:
                    pass
                return False

            def _try_extract_from_container(frag):
                if not frag:
                    return None
                for getter in ("getDialogsActivity", "getDialogsFragment", "getPrimaryFragment", "getFragment"):
                    try:
                        if hasattr(frag, getter):
                            sub = getattr(frag, getter)()
                            if _is_valid_target(sub):
                                return sub
                    except Exception:
                        pass
                for fname in ("dialogsActivity", "dialogsFragment", "dialogs", "currentDialogsActivity"):
                    try:
                        sub = get_private_field(frag, fname)
                    except Exception:
                        sub = None
                    if _is_valid_target(sub):
                        return sub
                return None

            if _is_valid_target(fragment_hint):
                return fragment_hint

            cand = _try_extract_from_container(fragment_hint)
            if cand:
                return cand

            try:
                cached = getattr(self, "_nowbox_dialogs_fragment", None)
            except Exception:
                cached = None
            if _is_valid_target(cached):
                return cached

            frag = get_last_fragment()
            if _is_valid_target(frag):
                return frag

            cand = _try_extract_from_container(frag)
            if cand:
                return cand

            return None
        except Exception:
            return None

    def _update_hooking_cover(self, cell, cover_url):
        try:
            from org.telegram.ui.Components import LayoutHelper, BackupImageView
            try:
                if not hasattr(self, "_hooking_cover_view") or self._hooking_cover_view is None:
                    self._hooking_cover_view = None
                    self._hooking_cover_parent = None
                    self._hooking_cover_pad = None
            except Exception:
                pass
            if not cover_url:
                try:
                    if self._hooking_cover_view:
                        self._hooking_cover_view.setVisibility(View.GONE)
                except Exception:
                    pass
                return
            if self._hooking_cover_view is None or self._hooking_cover_parent != cell:
                cover = BackupImageView(cell.getContext())
                cover.setRoundRadius(AndroidUtilities.dp(8))
                try:
                    from android.widget import ImageView
                    st = getattr(ImageView, "ScaleType", None)
                    if st and getattr(st, "CENTER_CROP", None):
                        cover.setScaleType(st.CENTER_CROP)
                except Exception:
                    pass
                try:
                    cover_size = AndroidUtilities.dp(14)
                    cell.addView(
                        cover,
                        LayoutHelper.createFrame(cover_size, cover_size, Gravity.LEFT | Gravity.CENTER_VERTICAL, -44, 0, 0, 0)
                    )
                except Exception:
                    pass
                try:
                    if self._hooking_cover_pad is None:
                        self._hooking_cover_pad = (cell.getPaddingLeft(), cell.getPaddingTop(), cell.getPaddingRight(), cell.getPaddingBottom())
                    pad_l, pad_t, pad_r, pad_b = self._hooking_cover_pad
                    cell.setPadding(pad_l + AndroidUtilities.dp(56), pad_t, pad_r, pad_b)
                except Exception:
                    pass
                try:
                    if hasattr(cell, "setClipToPadding"):
                        cell.setClipToPadding(False)
                    if hasattr(cell, "setClipChildren"):
                        cell.setClipChildren(False)
                except Exception:
                    pass
                self._hooking_cover_view = cover
                self._hooking_cover_parent = cell
            def _load():
                try:
                    if getattr(self, "_hooking_cover_loading", False):
                        return
                    self._hooking_cover_loading = True
                    data = self._get_cached_image_enhanced(cover_url, cache_key=f"hooking_cover_{hash(cover_url)}")
                    if not data:
                        return
                    bmp = BitmapFactory.decodeByteArray(data, 0, len(data))
                    if not bmp:
                        return
                    def _apply():
                        try:
                            if self._hooking_cover_view:
                                self._hooking_cover_view.setImageBitmap(bmp)
                                self._hooking_cover_view.setVisibility(View.VISIBLE)
                                try:
                                    self._hooking_cover_view.bringToFront()
                                except Exception:
                                    pass
                        except Exception:
                            pass
                    try:
                        run_on_ui_thread(_apply)
                    except Exception:
                        _apply()
                except Exception:
                    pass
                finally:
                    try:
                        self._hooking_cover_loading = False
                    except Exception:
                        pass
            threading.Thread(target=_load, daemon=True).start()
        except Exception:
            pass

    def _update_nowbox_eq_indicator(self, cell, playing):
        try:
            if int(self.get_setting("nowbox_eq_mode", 0)) != 1:
                try:
                    v = cell.findViewWithTag("nowbox_eq_indicator")
                    if v:
                        v.setVisibility(View.GONE)
                except Exception:
                    pass
                try:
                    self._stop_nowbox_eq_anim()
                except Exception:
                    pass
                return
            try:
                if hasattr(cell, "getVisibility"):
                    vis = cell.getVisibility()
                    if int(vis) != 0:
                        self._stop_nowbox_eq_anim()
                        return
            except Exception:
                pass
            from android.widget import FrameLayout
            from android.view import View, Gravity
            cont = cell.findViewWithTag("nowbox_eq_indicator")
            if cont is None:
                cont = FrameLayout(cell.getContext())
                cont.setTag("nowbox_eq_indicator")
                try:
                    cont.setClipChildren(False)
                    cont.setClipToPadding(False)
                except Exception:
                    pass
                w = AndroidUtilities.dp(36)
                h = AndroidUtilities.dp(14)
                try:
                    cell.addView(cont, LayoutHelper.createFrame(w, h, Gravity.RIGHT | Gravity.CENTER_VERTICAL, 0, 0, AndroidUtilities.dp(-9), 0))
                except Exception:
                    return
                try:
                    from android.widget import ViewSwitcher
                except Exception:
                    pass
                try:
                    bars = []
                    for i in range(3):
                        v = View(cell.getContext())
                        try:
                            hex_color = str(self.get_setting("nowbox_eq_color", "#00C897"))
                            v.setBackgroundColor(Color.parseColor(hex_color))
                        except Exception:
                            v.setBackgroundColor(Theme.getColor(Theme.key_switchTrackChecked))
                        v.setAlpha(0.9)
                        bw = AndroidUtilities.dp(3)
                        bh = AndroidUtilities.dp(12)
                        lm = LayoutHelper.createFrame(bw, bh, Gravity.CENTER_VERTICAL)
                        cont.addView(v, lm)
                        try:
                            left = AndroidUtilities.dp(i * 8)
                            v.setTranslationX(left)
                        except Exception:
                            pass
                        bars.append(v)
                    self._nowbox_eq_bars = bars
                except Exception:
                    pass
            cont.setVisibility(View.VISIBLE)
            if playing:
                self._start_nowbox_eq_anim()
            else:
                self._stop_nowbox_eq_anim()
        except Exception:
            pass

    def _start_nowbox_eq_anim(self):
        try:
            if getattr(self, "_nowbox_eq_anim_running", False):
                return
            self._nowbox_eq_anim_running = True
            def _anim():
                import random, time, math
                try:
                    while getattr(self, "_nowbox_eq_anim_running", False):
                        bars = getattr(self, "_nowbox_eq_bars", [])
                        t = time.time()
                        phases = [0.0, 0.8, 1.6]
                        vals = []
                        for idx in range(len(bars or [])):
                            phase = phases[idx % len(phases)]
                            base = 0.6 + 0.4 * abs(math.sin(t * 3.0 + phase))
                            jitter = (random.random() * 0.08) - 0.04
                            vals.append(max(0.3, min(1.2, base + jitter)))
                        def _apply():
                            try:
                                for i, b in enumerate(bars or []):
                                    b.setScaleY(vals[i])
                            except Exception:
                                pass
                        try:
                            run_on_ui_thread(_apply)
                        except Exception:
                            _apply()
                        time.sleep(0.16)
                except Exception:
                    pass
            threading.Thread(target=_anim, daemon=True).start()
        except Exception:
            pass

    def _stop_nowbox_eq_anim(self):
        try:
            self._nowbox_eq_anim_running = False
        except Exception:
            pass

    def _get_report_device_name(self):
        try:
            manufacturer = str(getattr(Build, "MANUFACTURER", "") or "").strip()
            model = str(getattr(Build, "MODEL", "") or "").strip()
            if manufacturer and model and manufacturer.lower() not in model.lower():
                return f"{manufacturer} {model}"
            return model or manufacturer or "Unknown"
        except Exception:
            return "Unknown"

    def _get_report_android_version(self):
        try:
            return str(getattr(Build.VERSION, "RELEASE", "") or getattr(Build.VERSION, "SDK_INT", ""))
        except Exception:
            return "Unknown"

    def _get_report_app_name(self):
        try:
            pkg = ApplicationLoader.applicationContext.getPackageName()
            low = str(pkg).lower()
            if "exteragram" in low:
                return "exteraGram"
            if "ayugram" in low:
                return "AyuGram"
            return str(pkg)
        except Exception:
            return "Unknown"

    def _collect_error_logs(self, limit=6):
        try:
            logs = []
            for l in _NOWFY_ERROR_LOGS:
                low = str(l).lower()
                if "[nowfy]" in low or "[nowfy " in low:
                    logs.append(l)
            logs = list(logs[-limit:])
            return logs
        except Exception:
            return []

    def _build_report_notes(self, logs):
        notes = []
        try:
            joined = " ".join(logs).lower()
        except Exception:
            joined = ""
        if not logs:
            return [tr("report_note_clean")]
        if any(k in joined for k in ["token", "refresh token", "unauthorized", "401", "auth"]):
            notes.append(tr("report_hint_token"))
        if any(k in joined for k in ["timeout", "connect", "connection", "network", "dns", "ssl"]):
            notes.append(tr("report_hint_connect"))
        if "429" in joined or "rate" in joined:
            notes.append(tr("report_hint_rate"))
        if "numpy" in joined:
            notes.append(tr("report_hint_numpy"))
        if "integer" in joined and "not defined" in joined:
            notes.append(tr("report_hint_integer"))
        if any(k in joined for k in ["getaccount", "_get_account", "get_account"]):
            notes.append(tr("report_hint_getaccount"))
        if "lastfm" in joined and any(k in joined for k in ["username", "user", "api key", "apikey", "invalid", "not found"]):
            notes.append(tr("report_hint_lastfm"))
        if "statsfm" in joined:
            notes.append(tr("report_hint_statsfm"))
        if not notes:
            notes.append(tr("report_hint_update"))
        return notes

    def _build_report_text(self):
        title = tr("report_title").format(version=__version__)
        header = tr("report_header")
        def _bold_label(text):
            try:
                parts = text.split(":", 1)
                if len(parts) == 2:
                    return f"*{parts[0].strip()}*: {parts[1].strip()}"
                return text
            except Exception:
                return text
        device = _bold_label(tr("report_device").format(device=self._get_report_device_name()))
        android_v = _bold_label(tr("report_android").format(android=self._get_report_android_version()))
        app = _bold_label(tr("report_app").format(app=self._get_report_app_name()))
        logs = self._collect_error_logs()
        if logs:
            log_lines = [f"- {l}" for l in logs]
        else:
            log_lines = [f"- {tr('report_no_logs')}"]
        sync_lines = []
        try:
            raw_sync = str(self.get_setting("nowfy_sync_log_tail", "") or "")
            if raw_sync:
                rows = json.loads(raw_sync)
                if isinstance(rows, list):
                    rows = [str(x) for x in rows if str(x).strip()]
                    rows = rows[-6:]
                    if rows:
                        sync_lines = [f"- {r}" for r in rows]
        except Exception:
            sync_lines = []
        notes = self._build_report_notes(logs)
        note_lines = [f"- {n}" for n in notes]
        body_lines = [device, android_v, app, "", f"*{tr('report_logs')}*"] + log_lines
        if sync_lines:
            body_lines += ["", "*Sync*", ""] + sync_lines
        body_lines += ["", f"*{tr('report_note')}*", ""] + note_lines
        body = "\n".join(body_lines)
        text = f"{title}\n{header}\n\n{body}"
        return text

    def _build_report_entities(self, text):
        try:
            from org.telegram.tgnet import TLRPC
        except Exception:
            return []
        def u16_len(s):
            try:
                return len(str(s).encode("utf-16-le")) // 2
            except Exception:
                return len(str(s))
        try:
            marker = tr("report_device").split(":")[0] + ":"
            idx = text.find(marker)
            if idx < 0:
                return []
            ent = TLRPC.TL_messageEntityBlockquote()
            ent.offset = u16_len(text[:idx])
            ent.length = u16_len(text[idx:])
            return [ent]
        except Exception:
            return []

    def _attach_hooking_gestures(self, cell):
        try:
            if not bool(self.get_setting("hooking_enabled", False)):
                return
            if hasattr(cell, "setClickable"):
                try:
                    cell.setClickable(True)
                except Exception:
                    pass
            if hasattr(cell, "setEnabled"):
                try:
                    cell.setEnabled(True)
                except Exception:
                    pass
            if not hasattr(cell, "setOnClickListener"):
                return
            try:
                from android_utils import OnClickListener as _OnClickListener
                if bool(self.get_setting("nowbox_lyrics_enabled", False)):
                    try:
                        old_click = getattr(cell, "_nowfy_old_click", None)
                    except Exception:
                        old_click = None
                    if old_click is None:
                        try:
                            old_click = get_private_field(cell, "onClickListener")
                        except Exception:
                            old_click = None
                        try:
                            setattr(cell, "_nowfy_old_click", old_click)
                        except Exception:
                            pass
                    cell.setOnClickListener(_OnClickListener(lambda v: self._open_nowbox_lyrics()))
                else:
                    cell.setOnClickListener(_OnClickListener(lambda v: None))
                return
            except Exception:
                pass
            try:
                ViewOnClickListener = find_class("android.view.View$OnClickListener")
            except Exception:
                ViewOnClickListener = None
            if ViewOnClickListener is not None:
                try:
                    class _NoOpClick(dynamic_proxy(ViewOnClickListener)):
                        def __init__(self, fn=None):
                            self._fn = fn
                        def onClick(self, v):
                            try:
                                if self._fn:
                                    self._fn(v)
                            except Exception:
                                pass
                    if bool(self.get_setting("nowbox_lyrics_enabled", False)):
                        cell.setOnClickListener(_NoOpClick(lambda v: self._open_nowbox_lyrics()))
                    else:
                        cell.setOnClickListener(_NoOpClick(lambda v: None))
                except Exception:
                    try:
                        cell.setOnClickListener(None)
                    except Exception:
                        pass
        except Exception:
            pass

