    def _open_nowtab_embed(self):
        try:
            try:
                pass
            except Exception:
                pass
            fragment = get_last_fragment()
            if not fragment:
                return
            context = fragment.getParentActivity()
            if not context:
                return
            from android.webkit import WebView as Wv, WebViewClient as Wvc
            from android.widget import LinearLayout
            from urllib.parse import quote as _quote
            from android.view import View
            theme_idx = int(self.get_setting("apple_skin", 0))
            theme = "light" if theme_idx == 0 else "dark"
            info = None
            try:
                info = self._get_tab_selected_track_for_lyrics()
            except Exception:
                info = None
            if not isinstance(info, dict):
                try:
                    info = self._get_track_for_hooking()
                except Exception:
                    info = None
            if not isinstance(info, dict):
                try:
                    info = self._get_current_track_info()
                except Exception:
                    info = None
            spotify_url = str((info or {}).get("spotify_url", "") or "").strip()
            tid = str((info or {}).get("id", "") or "").strip()
            if (not spotify_url) and tid:
                spotify_url = f"https://open.spotify.com/track/{tid}"
            if not spotify_url:
                try:
                    title = str((info or {}).get("name") or (info or {}).get("title") or "").strip()
                    artist_raw = (info or {}).get("artist")
                    if isinstance(artist_raw, dict):
                        artist = str(artist_raw.get("#text") or artist_raw.get("name") or "").strip()
                    else:
                        artist = str(artist_raw or "").strip()
                    if not artist:
                        try:
                            artists = (info or {}).get("artists", [])
                            if isinstance(artists, list) and artists:
                                parts = []
                                for a in artists:
                                    if isinstance(a, dict):
                                        n = str(a.get("name") or a.get("#text") or "").strip()
                                    else:
                                        n = str(a or "").strip()
                                    if n:
                                        parts.append(n)
                                artist = ", ".join(parts).strip()
                        except Exception:
                            artist = ""
                    if title:
                        spotify_url = str(self._search_spotify_url(title, artist) or "").strip()
                        if not spotify_url:
                            spotify_url = str(self._search_spotify_url_public(title, artist) or "").strip()
                except Exception:
                    spotify_url = ""
            base = ""
            song_link_url = ""
            if spotify_url:
                try:
                    song_link_url = str(self._get_song_link(spotify_url) or "").strip()
                    if not song_link_url:
                        song_link_url = f"https://song.link/{_quote(spotify_url, safe='')}"
                except Exception:
                    song_link_url = ""
            base = song_link_url
            if not base:
                BulletinHelper.show_info(tr("no_track_playing_generic"))
                return
            method = int(self.get_setting("nowfy_songlink_method", 0))
            if method == 0:
                self._open_url(base)
                return
            self._open_url(base)
            return
        except Exception as e:
            pass

    def _fetch_nowbox_lyrics(self, fragment_hint=None, activity_hint=None):
        try:
            self._lyrics_log("fetch begin")
            fragment = fragment_hint
            if not fragment:
                try:
                    fragment = get_last_fragment() or getattr(self, "_chat_fab_fragment", None) or getattr(self, "_preview_fragment_hint", None)
                except Exception:
                    fragment = None
            activity = None
            try:
                activity = fragment.getParentActivity() if fragment else None
            except Exception:
                activity = None
            if not activity:
                try:
                    activity = activity_hint
                except Exception:
                    activity = None
            if not activity:
                try:
                    f2 = get_last_fragment()
                    activity = f2.getParentActivity() if f2 else None
                except Exception:
                    activity = None
            if not activity:
                self._lyrics_log("abort: no valid activity context")
                try:
                    run_on_ui_thread(lambda: self._show_pulse_notice(tr("nowbox_lyrics_title"), tr("nowbox_lyrics_error")))
                except Exception:
                    pass
                return
            info = self._get_track_for_hooking()
            title = str(info.get("name", "") or info.get("title", "") or "").strip() if info else ""
            artist = str(info.get("artist", "") or "").strip() if info else ""
            if not title:
                alt = self._get_tab_selected_track_for_lyrics()
                if alt:
                    title = str(alt.get("name", "") or alt.get("title", "") or "").strip()
                    artist = str(alt.get("artist", "") or "").strip()
                if not title:
                    self._lyrics_log("abort: no active track")
                    try:
                        BulletinHelper.show_info(tr("no_track_playing_generic"))
                    except Exception:
                        pass
                    return
            ct, ca = self._clean_track_for_lyrics(title, artist)
            self._lyrics_log(f"track resolved: title='{ct[:80]}' artist='{ca[:80]}'")
            cached = self._get_cached_lyrics(ct, ca)
            if cached:
                self._lyrics_log("cache hit -> showing sheet")
                run_on_ui_thread(lambda: self._show_lyrics_sheet(activity, ct, ca, cached))
                return
            self._lyrics_log("cache miss -> fetching providers")
            lyrics_text = self._fetch_genius_lyrics(ct, ca)
            if not lyrics_text:
                self._lyrics_log("genius miss -> trying lrclib")
                lyrics_text = self._fetch_lrclib_lyrics(ct, ca)
            if not lyrics_text:
                self._lyrics_log("lyrics not found")
                try:
                    run_on_ui_thread(lambda: self._show_pulse_notice(tr("nowbox_lyrics_title"), tr("nowbox_lyrics_not_found")))
                except Exception:
                    pass
                return
            self._store_lyrics_cache(ct, ca, lyrics_text)
            self._lyrics_log(f"lyrics fetched ok (len={len(str(lyrics_text))})")
            run_on_ui_thread(lambda: self._show_lyrics_sheet(activity, ct, ca, lyrics_text))
        except Exception as e:
            self._lyrics_log(f"fetch exception: {e}")
            try:
                run_on_ui_thread(lambda: self._show_pulse_notice(tr("nowbox_lyrics_title"), tr("nowbox_lyrics_error")))
            except Exception:
                pass
        finally:
            try:
                self._lyrics_fetching = False
                self._lyrics_log("fetch end")
            except Exception:
                pass

    def _lyrics_cache_key(self, title, artist):
        try:
            t = re.sub(r'[^a-z0-9]+', '', str(title or '').lower())
            a = re.sub(r'[^a-z0-9]+', '', str(artist or '').lower())
            return f"{t}:{a}"
        except Exception:
            return f"{title}:{artist}"

    def _get_cached_lyrics(self, title, artist):
        try:
            cache = getattr(self, "_lyrics_cache", {})
            key = self._lyrics_cache_key(title, artist)
            item = cache.get(key)
            if not item:
                return ""
            ts = float(item.get("ts", 0))
            if ts and (time.time() - ts) > 21600:
                try:
                    del cache[key]
                except Exception:
                    pass
                return ""
            return item.get("lyrics", "") or ""
        except Exception:
            return ""

    def _store_lyrics_cache(self, title, artist, lyrics_text):
        try:
            if not lyrics_text:
                return
            if not hasattr(self, "_lyrics_cache"):
                self._lyrics_cache = {}
            key = self._lyrics_cache_key(title, artist)
            self._lyrics_cache[key] = {"lyrics": str(lyrics_text), "ts": time.time()}
        except Exception:
            pass

    def _prefetch_lyrics_for_track(self, title, artist):
        try:
            if not title:
                return
            key = self._lyrics_cache_key(title, artist)
            try:
                now_ts = time.time()
                last_key = getattr(self, "_lyrics_prefetch_last_key", "")
                last_ts = float(getattr(self, "_lyrics_prefetch_last_ts", 0.0) or 0.0)
                if key == last_key and (now_ts - last_ts) < 30.0:
                    return
                self._lyrics_prefetch_last_key = key
                self._lyrics_prefetch_last_ts = now_ts
            except Exception:
                pass
            if not hasattr(self, "_lyrics_prefetch_inflight"):
                self._lyrics_prefetch_inflight = set()
            if key in self._lyrics_prefetch_inflight:
                return
            if self._get_cached_lyrics(title, artist):
                return
            self._lyrics_prefetch_inflight.add(key)
            def _work():
                try:
                    lyrics_text = self._fetch_lrclib_lyrics(title, artist)
                    if lyrics_text:
                        self._store_lyrics_cache(title, artist, lyrics_text)
                finally:
                    try:
                        self._lyrics_prefetch_inflight.discard(key)
                    except Exception:
                        pass
            threading.Thread(target=_work, daemon=True).start()
        except Exception:
            pass

    def _clean_track_for_lyrics(self, title, artist, album=None, duration_ms=0):
        try:
            t = str(title or '').strip()
            a = str(artist or '').strip()
            al = str(album or '').strip()
            t = re.sub(r'\s*\([^)]*\)|\[[^]]*\]', '', t)
            t = re.sub(r'(?i)\s*-\s*(live|remaster(?:ed)?|version|edit|acoustic|radio\s+edit)\b.*$', '', t)
            t = re.sub(r'(?i)\s*\bfeat[.]?\s*.+$', '', t)
            a = re.sub(r'\s*\([^)]*\)|\[[^]]*\]', '', a)
            a = re.sub(r'(?i)\s*\bfeat[.]?\s*.+$', '', a)
            t = ' '.join(t.split())
            a = ' '.join(a.split())
            al = ' '.join(al.split()) if al else ''
            return t, a
        except Exception:
            return str(title or '').strip(), str(artist or '').strip()

    def _fetch_lrclib_lyrics(self, title, artist):
        try:
            title = str(title or '').strip()
            artist = str(artist or '').strip()
            if not title:
                return ""
            try:
                info = self._get_track_for_hooking()
            except Exception:
                info = None
            album = str((info or {}).get("album", "") or "").strip()
            dur_ms = int((info or {}).get("duration_ms", 0) or 0)
            dur_s = max(0, dur_ms // 1000)
            if title and artist:
                try:
                    resp = requests.get(
                        'https://lrclib.net/api/get',
                        params={
                            'artist_name': artist,
                            'track_name': title,
                            'album_name': album or '',
                            'duration': dur_s or 0
                        },
                        timeout=5
                    )
                    if resp.status_code == 200 and resp.content:
                        data = resp.json()
                        lyrics = data.get('syncedLyrics') or data.get('plainLyrics') or ''
                        if lyrics:
                            try:
                                lyrics = _html.unescape(str(lyrics))
                            except Exception:
                                lyrics = str(lyrics)
                            lyrics = re.sub(r'\[\d{1,2}:\d{2}(?:\.\d+)?\]', '', lyrics)
                            lyrics = lyrics.replace('\r', '')
                            lyrics = re.sub(r'\n{3,}', '\n\n', lyrics).strip()
                            if len(lyrics) >= 20 and not str(data.get('instrumental', False)).lower() == 'true':
                                return lyrics
                except Exception:
                    pass
            queries = []
            if artist:
                queries.append({'track_name': title, 'artist_name': artist, 'duration': dur_s})
            queries.append({'track_name': title, 'artist_name': '', 'duration': dur_s})
            if artist:
                queries.append({'track_name': '', 'artist_name': artist, 'duration': dur_s})
            def _norm(s):
                s = str(s or '').lower()
                s = re.sub(r'[^a-z0-9]+', ' ', s)
                return re.sub(r'\s+', ' ', s).strip()
            def _score(t, a, wt, wa):
                nt = _norm(t)
                na = _norm(a)
                wt = _norm(wt)
                wa = _norm(wa)
                sc = 0
                if wt and wt in nt:
                    sc += 2
                if wa and wa in na:
                    sc += 1
                return sc
            for params in queries:
                try:
                    resp = requests.get('https://lrclib.net/api/search', params=params, timeout=5)
                    if resp.status_code != 200:
                        continue
                    results = resp.json()
                    if not isinstance(results, list) or not results:
                        continue
                    best = None
                    best_score = -1
                    for res in results[:20]:
                        t = res.get('trackName', '')
                        a = res.get('artistName', '')
                        sc = _score(t, a, title, artist)
                        if sc > best_score:
                            best_score = sc
                            best = res
                    if not best:
                        continue
                    lyrics = best.get('syncedLyrics') or best.get('plainLyrics')
                    if not lyrics or len(str(lyrics).strip()) < 50:
                        song_id = best.get('id')
                        if song_id:
                            try:
                                full = requests.get(f'https://lrclib.net/api/get/{song_id}', timeout=5)
                                if full.status_code == 200:
                                    data = full.json()
                                    lyrics = data.get('syncedLyrics') or data.get('plainLyrics')
                            except Exception:
                                pass
                    if not lyrics:
                        continue
                    try:
                        lyrics = _html.unescape(str(lyrics))
                    except Exception:
                        lyrics = str(lyrics)
                    lyrics = re.sub(r'\[\d{1,2}:\d{2}(?:\.\d+)?\]', '', lyrics)
                    lyrics = lyrics.replace('\r', '')
                    lyrics = re.sub(r'\n{3,}', '\n\n', lyrics).strip()
                    if len(lyrics) < 20:
                        continue
                    return lyrics
                except Exception:
                    continue
            return ""
        except Exception:
            return ""

    def _fetch_genius_lyrics(self, title, artist):
        try:
            token = str(self.get_setting("genius_token", "") or "").strip()
            if not token:
                return ""
            def _norm(s):
                s = str(s or "").lower()
                s = re.sub(r"[^a-z0-9]+", " ", s)
                s = re.sub(r"\s+", " ", s).strip()
                return s
            def _score(hit_title, hit_artist, want_title, want_artist):
                ht = _norm(hit_title)
                ha = _norm(hit_artist)
                wt = _norm(want_title)
                wa = _norm(want_artist)
                score = 0
                if wt and wt in ht:
                    score += 3
                if wa and wa in ha:
                    score += 2
                return score
            query = f"{title} {artist}".strip()
            resp = requests.get(
                "https://api.genius.com/search",
                params={"q": query},
                timeout=6,
                headers={"Authorization": f"Bearer {token}", "User-Agent": "Nowfy/1.1.1"}
            )
            if resp.status_code != 200 or not resp.content:
                return ""
            data = resp.json()
            hits = data.get("response", {}).get("hits", []) if isinstance(data, dict) else []
            if not hits:
                return ""
            best = None
            best_score = -1
            for h in hits[:6]:
                res = h.get("result", {}) if isinstance(h, dict) else {}
                ht = res.get("title", "")
                ha = res.get("primary_artist", {}).get("name", "") if isinstance(res.get("primary_artist"), dict) else ""
                sc = _score(ht, ha, title, artist)
                if sc > best_score:
                    best_score = sc
                    best = res
            hit = best or (hits[0].get("result", {}) if isinstance(hits[0], dict) else {})
            url = hit.get("url")
            if not url:
                return ""
            page = requests.get(
                url,
                timeout=6,
                headers={
                    "User-Agent": "Mozilla/5.0 (Android) Nowfy/1.1.1",
                    "Accept-Language": "en-US,en;q=0.9"
                }
            )
            if page.status_code != 200 or not page.text:
                return ""
            html = page.text
            try:
                from bs4 import BeautifulSoup
                html_content = html.replace('<br>', '\n').replace('<br/>', '\n').replace('<br />', '\n')
                soup = BeautifulSoup(html_content, 'html.parser')
                for tag in soup(['script', 'style', 'iframe', 'nav', 'footer', 'header']):
                    tag.decompose()
                lyrics_sections = []
                containers = soup.select("div[class*='Lyrics__Container'], div[class*='lyrics'], div[data-lyrics-container]")
                for container in containers:
                    for br in container.find_all('br'):
                        br.replace_with('\n')
                    text = container.get_text(separator='\n', strip=True)
                    if text and len(text) > 50:
                        lyrics_sections.append(text)
                if lyrics_sections:
                    return '\n\n'.join(lyrics_sections)
            except Exception:
                pass
            html = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.S | re.I)
            html = re.sub(r'<style[^>]*>.*?</style>', '', html, flags=re.S | re.I)
            blocks = []
            primary = re.findall(r'data-lyrics-container=\"true\"[^>]*>(.*?)</div>', html, flags=re.S | re.I)
            candidates = primary
            if not candidates:
                patterns = [
                    r'class=\"Lyrics__Container[^\\"]*\"[^>]*>(.*?)</div>',
                    r'class=\"lyrics\"[^>]*>(.*?)</div>',
                ]
                for pat in patterns:
                    candidates += re.findall(pat, html, flags=re.S | re.I)
            for blk in candidates:
                clean = re.sub(r'<br\s*/?>', '\n', blk)
                clean = re.sub(r'</p>\s*<p>', '\n\n', clean, flags=re.I)
                clean = re.sub(r'<[^>]+>', '', clean)
                clean = re.sub(r'\n{3,}', '\n\n', clean).strip()
                if not clean or len(clean) <= 20:
                    continue
                low = clean.lower()
                if 'translations' in low or 'you may also like' in low or 'verified' in low:
                    continue
                if 'fragmentid' in low or '\"tag\"' in clean:
                    continue
                blocks.append(clean)
            if blocks:
                return "\n\n".join(blocks)
            return ""
        except Exception:
            return ""

    def _show_lyrics_sheet(self, ctx, title, artist, lyrics_text):
        try:
            self._lyrics_log("render sheet begin")
            try:
                auto_scroll_enabled = bool(self.get_setting("nowfy_lyrics_autoscroll_enabled", False))
            except Exception:
                auto_scroll_enabled = False
            try:
                auto_scroll_speed = int(self.get_setting("nowfy_lyrics_autoscroll_speed", 0) or 0)
            except Exception:
                auto_scroll_speed = 0
            if auto_scroll_speed < 0 or auto_scroll_speed > 2:
                auto_scroll_speed = 0
            sheet = BottomSheet(ctx, True)
            container = LinearLayout(ctx)
            container.setOrientation(LinearLayout.VERTICAL)
            container.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(20), AndroidUtilities.dp(20), AndroidUtilities.dp(16))
            header_row = LinearLayout(ctx)
            header_row.setOrientation(LinearLayout.HORIZONTAL)
            header_row.setGravity(Gravity.CENTER_VERTICAL)
            title_wrap = LinearLayout(ctx)
            title_wrap.setOrientation(LinearLayout.VERTICAL)
            title_view = TextView(ctx)
            title_view.setText(title)
            title_view.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            title_view.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            try:
                title_view.setTypeface(AndroidUtilities.getTypeface(AndroidUtilities.TYPEFACE_ROBOTO_MEDIUM))
            except Exception:
                pass
            title_wrap.addView(title_view)
            subtitle = TextView(ctx)
            subtitle.setText(artist)
            subtitle.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            title_wrap.addView(subtitle)
            header_row.addView(title_wrap, LayoutHelper.createLinear(0, -2, 1.0))
            close_view = ImageView(ctx)
            try:
                close_view.setScaleType(ImageView.ScaleType.CENTER_INSIDE)
                close_view.setAdjustViewBounds(False)
                close_view.setPadding(AndroidUtilities.dp(1), AndroidUtilities.dp(1), AndroidUtilities.dp(1), AndroidUtilities.dp(1))
            except Exception:
                pass
            try:
                bgc = int(Theme.getColor(Theme.key_windowBackgroundWhite))
                r = (bgc >> 16) & 0xFF
                g = (bgc >> 8) & 0xFF
                b = bgc & 0xFF
                is_dark_theme = (((r * 299 + g * 587 + b * 114) / 1000.0) < 150)
            except Exception:
                is_dark_theme = True
            try:
                close_name = "close_white.png" if is_dark_theme else "close_black.png"
                close_candidates = [
                    os.path.join(os.path.dirname(__file__), "assets", "png", close_name),
                    os.path.join(os.path.dirname(__file__), "nowfy", "assets", "png", close_name),
                ]
                close_bmp = None
                for cp in close_candidates:
                    try:
                        if cp and os.path.isfile(cp):
                            close_bmp = BitmapFactory.decodeFile(cp)
                            if close_bmp:
                                break
                    except Exception:
                        pass
                if close_bmp:
                    close_view.setImageBitmap(close_bmp)
                else:
                    close_view.setImageResource(R.drawable.msg_close)
                    close_view.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                try:
                    close_view.setImageResource(R.drawable.msg_close)
                    close_view.setColorFilter(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                except Exception:
                    pass
            try:
                close_view.setOnClickListener(OnClickListener(lambda v: sheet.dismiss()))
            except Exception:
                pass
            try:
                lp_close = LinearLayout.LayoutParams(AndroidUtilities.dp(24), AndroidUtilities.dp(24))
                lp_close.gravity = Gravity.CENTER_VERTICAL
                lp_close.rightMargin = AndroidUtilities.dp(4)
                header_row.addView(close_view, lp_close)
            except Exception:
                header_row.addView(close_view, LayoutHelper.createLinear(AndroidUtilities.dp(18), AndroidUtilities.dp(18), Gravity.CENTER_VERTICAL, 0, 0, 4, 0))
            container.addView(header_row, LayoutHelper.createLinear(-1, -2, Gravity.START, 0, 0, 0, 12))
            try:
                lyrics_text = lyrics_text.replace("\\n", "\n")
            except Exception:
                pass
            try:
                lyrics_text = _html.unescape(lyrics_text)
            except Exception:
                pass
            try:
                lines = []
                lyrics_text = re.sub(r'\[[^\]]+\]', '\n\n', lyrics_text)
                lyrics_text = re.sub(r'([a-z])([A-Z])', r'\1 \2', lyrics_text)
                lyrics_text = re.sub(r'([.!?])\s*([A-Z])', r'\1\n\2', lyrics_text)
                lyrics_text = re.sub(r'[ \t]{2,}', ' ', lyrics_text)
                for raw in lyrics_text.split("\n"):
                    line = str(raw or "")
                    if re.match(r'^\s*\[[^\]]+\]\s*$', line):
                        lines.append("")
                        continue
                    line = re.sub(r'\s*\[[^\]]+\]\s*', ' ', line)
                    if re.match(r'^\s*(chorus|verse|bridge|intro|outro|pre-chorus|prechorus|post-chorus|postchorus|hook|refrain|refrao|verso|ponte|introducao|saida)\b', line, flags=re.I):
                        lines.append("")
                        continue
                    line = re.sub(r'^\s*(chorus|verse|bridge|intro|outro|pre-chorus|prechorus|post-chorus|postchorus|hook|refrain|refrao|verso|ponte|introducao|saida)\s*\d*\s*[:\-]*\s*', '', line, flags=re.I)
                    lines.append(line)
                lyrics_text = "\n".join(lines)
                lyrics_text = re.sub(r'\n{3,}', '\n\n', lyrics_text).strip()
            except Exception:
                pass
            rendered = False
            try:
                web = WebView(ctx)
                try:
                    web.setBackgroundColor(0x00000000)
                except Exception:
                    pass
                try:
                    ws = web.getSettings()
                    if ws is not None:
                        ws.setJavaScriptEnabled(True)
                        ws.setDomStorageEnabled(True)
                except Exception:
                    pass
                try:
                    safe_text = lyrics_text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                    paras = [p for p in safe_text.split("\\n\\n") if p.strip()]
                    html_body = "".join([f"<p>{p.replace(chr(10), '<br>')}</p>" for p in paras])
                except Exception:
                    html_body = f"<p>{lyrics_text}</p>"
                try:
                    try:
                        bg_color = Theme.getColor(Theme.key_dialogBackground)
                    except Exception:
                        bg_color = Theme.getColor(Theme.key_windowBackgroundWhite)
                    text_color = Theme.getColor(Theme.key_windowBackgroundWhiteBlackText)
                    def _hex(c):
                        return '#%02x%02x%02x' % ((c >> 16) & 255, (c >> 8) & 255, c & 255)
                    html_bg = _hex(bg_color)
                    html_text = _hex(text_color)
                except Exception:
                    html_bg = '#111'
                    html_text = '#f7f7f7'
                html = (
                    f"<html><head><style>"
                    f"body{{ background:{html_bg};color:{html_text};font-family:'Google Sans','Product Sans','Roboto','Noto Sans',sans-serif;padding:0;margin:0;}} "
                    f".wrap{{ padding:18px 18px 22px 18px;}} "
                    f".ly{{ line-height:2.1;font-size:34px;color:{html_text};font-weight:800;letter-spacing:0.2px;}} "
                    f".ly p{{ margin:0 0 22px 0;}} "
                    f"</style></head><body>"
                    f"<div class='wrap'><div class='ly'>{html_body}</div></div>"
                    f"</body></html>"
                )
                if auto_scroll_enabled:
                    speed_map = [0.50, 1.10, 1.75]
                    try:
                        speed_px = float(speed_map[int(auto_scroll_speed)])
                    except Exception:
                        speed_px = 0.50
                    auto_script = (
                        "<script>"
                        "(function(){"
                        "var speed=" + str(speed_px) + ";"
                        "var resumeDelay=5000;"
                        "var userUntil=0;"
                        "var carry=0.0;"
                        "var touching=false;"
                        "var doc=function(){return document.scrollingElement||document.documentElement||document.body;};"
                        "var markUser=function(){userUntil=Date.now()+resumeDelay;};"
                        "window.addEventListener('touchstart', function(){touching=true; markUser();}, {passive:true});"
                        "window.addEventListener('touchmove', function(){markUser();}, {passive:true});"
                        "window.addEventListener('touchend', function(){touching=false; markUser();}, {passive:true});"
                        "window.addEventListener('mousedown', function(){touching=true; markUser();}, {passive:true});"
                        "window.addEventListener('mouseup', function(){touching=false; markUser();}, {passive:true});"
                        "window.addEventListener('wheel', function(){markUser();}, {passive:true});"
                        "window.addEventListener('scroll', function(){if(touching){markUser();}}, {passive:true});"
                        "var tick=function(){"
                        "try{"
                        "var d=doc();"
                        "if(!d){requestAnimationFrame(tick);return;}"
                        "var max=Math.max(0, d.scrollHeight-window.innerHeight);"
                        "if(Date.now()>=userUntil && d.scrollTop < max-1){"
                        "carry += speed;"
                        "var dy=Math.floor(carry);"
                        "if(dy>=1){"
                        "d.scrollTop = Math.min(max, d.scrollTop + dy);"
                        "carry -= dy;"
                        "}"
                        "}"
                        "}catch(e){}"
                        "requestAnimationFrame(tick);"
                        "};"
                        "setTimeout(function(){requestAnimationFrame(tick);}, 3000);"
                        "})();"
                        "</script>"
                    )
                    html = html.replace("</body></html>", auto_script + "</body></html>")
                web.loadDataWithBaseURL(None, html, "text/html", "utf-8", None)
                try:
                    Listener = find_class("android.view.View$OnTouchListener")
                except Exception:
                    Listener = None
                if Listener is not None:
                    try:
                        class _Touch(dynamic_proxy(Listener)):
                            def onTouch(self, v, event):
                                try:
                                    action = event.getAction()
                                    if action == 0 or action == 2:
                                        parent = v.getParent()
                                        if parent:
                                            parent.requestDisallowInterceptTouchEvent(True)
                                except Exception:
                                    pass
                                return False
                        web.setOnTouchListener(_Touch())
                    except Exception:
                        pass
                container.addView(web, LayoutHelper.createLinear(-1, AndroidUtilities.dp(420)))
                rendered = True
            except Exception as e:
                self._lyrics_log(f"webview render fallback: {e}")
            if not rendered:
                from android.widget import ScrollView as _ScrollView
                fallback_scroll = _ScrollView(ctx)
                fallback_text = TextView(ctx)
                fallback_text.setText(str(lyrics_text or ""))
                fallback_text.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
                try:
                    fallback_text.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                except Exception:
                    pass
                try:
                    fallback_text.setLineSpacing(0.0, 1.25)
                except Exception:
                    pass
                try:
                    fallback_text.setPadding(AndroidUtilities.dp(4), AndroidUtilities.dp(2), AndroidUtilities.dp(4), AndroidUtilities.dp(8))
                except Exception:
                    pass
                fallback_scroll.addView(fallback_text, LayoutHelper.createFrame(-1, -2))
                container.addView(fallback_scroll, LayoutHelper.createLinear(-1, AndroidUtilities.dp(420)))
            sheet.setCustomView(container)
            sheet.show()
            self._lyrics_log("render sheet shown")
        except Exception as e:
            self._lyrics_log(f"render sheet exception: {e}")
            try:
                run_on_ui_thread(lambda: self._show_pulse_notice(tr("nowbox_lyrics_title"), tr("nowbox_lyrics_error")))
            except Exception:
                pass

    def _apply_hooking_hint_hook(self):
        try:
            try:
                if getattr(self, "_nowbox_hint_hooks", None):
                    return
            except Exception:
                pass
            hooks = []
            class _HookingHintHook(MethodHook):
                def __init__(self, p):
                    self.p = p
                def after_hooked_method(self, param):
                    try:
                        if not bool(self.p.get_setting("hooking_enabled", False)):
                            return
                        instance = getattr(param, 'thisObject', None)
                        if instance is None:
                            return
                        try:
                            cname = str(instance.getClass().getName() or "")
                            if "DialogsActivity" in cname:
                                self.p._nowbox_dialogs_fragment = instance
                        except Exception:
                            pass
                        cell = None
                        for fname in ("authHintCell", "dialogsHintCell", "dialogsHintCellContainer", "hintCell", "hintView", "dialogsHintView"):
                            try:
                                cell = self.p._get_private_field(instance, fname)
                            except Exception:
                                cell = None
                            if cell:
                                break
                        if not cell:
                            return
                        try:
                            self.p._attach_hooking_gestures(cell)
                        except Exception:
                            pass
                        try:
                            self.p._force_nowbox_hint_visibility(cell)
                        except Exception:
                            pass
                        try:
                            self.p._schedule_nowbox_hint_reapply(cell_hint=cell)
                        except Exception:
                            pass
                        data = self.p._get_track_for_hooking()
                        if data and (data.get("title") or data.get("name")) and data.get("artist"):
                            try:
                                cov = str(data.get("cover_url", "") or "").strip()
                                if cov:
                                    self.p._di_last_cover_url = cov
                            except Exception:
                                pass
                            self.p._update_hooking_hint(data, cell_hint=cell)
                            try:
                                if bool(self.p.get_setting("nowbox_show_cover_actionbar", False)):
                                    self.p._apply_nowbox_cover_banner(fragment_hint=instance)
                            except Exception:
                                pass
                        else:
                            try:
                                if hasattr(cell, "setVisibility"):
                                    cell.setVisibility(8)
                            except Exception:
                                pass
                            try:
                                self.p._restore_nowbox_banner(fragment_hint=instance)
                            except Exception:
                                pass
                    except Exception:
                        pass
            cls = find_class("org.telegram.ui.DialogsActivity")
            if cls:
                names = {
                    "updateDialogsHint",
                    "updateDialogsBirthdayHint",
                    "checkUnconfirmedAuthHintCellVisibility",
                    "checkActiveGiftAuctionsHintCellVisibility",
                    "updateVisibleRows",
                    "updateRows",
                    "onResume",
                }
                try:
                    methods = list(cls.getDeclaredMethods() or [])
                except Exception:
                    methods = []
                for mm in methods:
                    try:
                        n = str(mm.getName() or "")
                    except Exception:
                        n = ""
                    if not n:
                        continue
                    try:
                        pcount = int(mm.getParameterTypes().length)
                    except Exception:
                        pcount = -1
                    if (n in names) or (("Hint" in n or "hint" in n) and pcount == 0):
                        try:
                            mm.setAccessible(True)
                        except Exception:
                            pass
                        try:
                            h = self.hook_method(mm, _HookingHintHook(self))
                            if h:
                                hooks.append(h)
                        except Exception:
                            pass
            if hooks:
                try:
                    self._nowbox_hint_hooks = hooks
                except Exception:
                    pass
                return
            m = self._get_update_dialogs_hint_method()
            if not m:
                return
            try:
                m.setAccessible(True)
            except Exception:
                pass
            h = self.hook_method(m, _HookingHintHook(self))
            try:
                if h:
                    self._nowbox_hint_hooks = [h]
            except Exception:
                pass
        except Exception:
            pass

    def _apply_nowbox_cover_banner(self, fragment_hint=None, _retry=0):
        try:
            if not self.get_setting("hooking_enabled", False):
                return
            if not self.get_setting("nowbox_show_cover_actionbar", False):
                return
            fragment = self._resolve_nowbox_actionbar_target(fragment_hint)
            if not fragment:
                return
            frag_name = ""
            try:
                frag_name = str(fragment.getClass().getName() or "")
            except Exception:
                frag_name = ""
            if "DialogsActivity" not in frag_name:
                return
            action_bar = None
            try:
                action_bar = fragment.getActionBar()
            except Exception:
                action_bar = None
            if not action_bar:
                try:
                    action_bar = get_private_field(fragment, "actionBar")
                except Exception:
                    action_bar = None
            if not action_bar:
                return
            try:
                if not hasattr(self, "_nowbox_original_actionbar_drawable") or self._nowbox_original_actionbar_drawable is None:
                    self._nowbox_original_actionbar_drawable = action_bar.getBackground()
            except Exception:
                pass
            try:
                if not hasattr(self, "_nowbox_original_actionbar_color") or self._nowbox_original_actionbar_color is None:
                    try:
                        self._nowbox_original_actionbar_color = Theme.getColor(Theme.key_actionBarDefault)
                    except Exception:
                        self._nowbox_original_actionbar_color = getattr(Color, "TRANSPARENT", 0)
            except Exception:
                pass
            image_url = None
            try:
                image_url = getattr(self, "_di_last_cover_url", None)
            except Exception:
                image_url = None
            if not image_url:
                return
            data = None
            try:
                data = self._get_cached_image_enhanced(image_url, cache_key=f"nowbox_banner_{hash(image_url)}")
            except Exception:
                data = None
            if not data:
                return
            bmp = None
            try:
                BitmapFactory = find_class("android.graphics.BitmapFactory")
                if BitmapFactory is not None:
                    bmp = BitmapFactory.decodeByteArray(data, 0, len(data))
            except Exception:
                bmp = None
            if not bmp:
                return
            try:
                ab_w = int(action_bar.getWidth())
                ab_h = int(action_bar.getHeight())
            except Exception:
                ab_w, ab_h = 0, 0
            if (ab_w <= 0 or ab_h <= 0) and int(_retry or 0) < 4:
                run_on_ui_thread(lambda f=fragment, r=int(_retry or 0) + 1: self._apply_nowbox_cover_banner(fragment_hint=f, _retry=r), delay=120)
                return
            cropped_drawable = None
            try:
                Bitmap = find_class("android.graphics.Bitmap")
                Canvas = find_class("android.graphics.Canvas")
                Paint = find_class("android.graphics.Paint")
                Matrix = find_class("android.graphics.Matrix")
                if bmp and Bitmap and Canvas and Paint and Matrix and ab_w > 0 and ab_h > 0:
                    ARGB_8888 = getattr(getattr(Bitmap, "Config", None), "ARGB_8888", None)
                    target_bitmap = Bitmap.createBitmap(ab_w, ab_h, ARGB_8888 or bmp.getConfig())
                    canvas = Canvas(target_bitmap)
                    paint = Paint()
                    try:
                        paint.setFilterBitmap(True)
                        paint.setAntiAlias(True)
                    except Exception:
                        pass
                    bw = int(bmp.getWidth())
                    bh = int(bmp.getHeight())
                    sx = float(ab_w) / float(bw) if bw > 0 else 1.0
                    sy = float(ab_h) / float(bh) if bh > 0 else 1.0
                    s = sx if sx > sy else sy
                    scaled_bw = float(bw) * s
                    scaled_bh = float(bh) * s
                    dx = (float(ab_w) - scaled_bw) / 2.0
                    top_bias_ratio = 0.18
                    excess_h = scaled_bh - float(ab_h)
                    if excess_h > 0:
                        dy = -(excess_h * top_bias_ratio)
                    else:
                        dy = (float(ab_h) - scaled_bh) / 2.0
                    matrix = Matrix()
                    matrix.setScale(s, s)
                    matrix.postTranslate(dx, dy)
                    try:
                        canvas.drawBitmap(bmp, matrix, paint)
                    except Exception:
                        pass
                    BitmapDrawable = find_class("android.graphics.drawable.BitmapDrawable")
                    Gravity = find_class("android.view.Gravity")
                    parent_activity = fragment.getParentActivity()
                    if BitmapDrawable and parent_activity:
                        resources = parent_activity.getResources()
                        cropped_drawable = BitmapDrawable(resources, target_bitmap)
                        try:
                            if Gravity and hasattr(cropped_drawable, "setGravity"):
                                cropped_drawable.setGravity(getattr(Gravity, "FILL", None) or 119)
                        except Exception:
                            pass
            except Exception:
                cropped_drawable = None
            if not cropped_drawable:
                try:
                    BitmapDrawable = find_class("android.graphics.drawable.BitmapDrawable")
                    Gravity = find_class("android.view.Gravity")
                    parent_activity = fragment.getParentActivity()
                    if BitmapDrawable and parent_activity:
                        resources = parent_activity.getResources()
                        cropped_drawable = BitmapDrawable(resources, bmp)
                        try:
                            if Gravity and hasattr(cropped_drawable, "setGravity"):
                                cropped_drawable.setGravity(getattr(Gravity, "FILL", None) or 119)
                        except Exception:
                            pass
                except Exception:
                    cropped_drawable = None
            if not cropped_drawable:
                return
            try:
                Color = find_class("android.graphics.Color")
                GradientDrawable = find_class("android.graphics.drawable.GradientDrawable")
                ColorDrawable = find_class("android.graphics.drawable.ColorDrawable")
                LayerDrawable = find_class("android.graphics.drawable.LayerDrawable")
                scrim_color = 0x33000000
                scrim_drawable = ColorDrawable(scrim_color) if ColorDrawable else None
                gradient = None
                try:
                    if GradientDrawable and Color:
                        colors = [
                            getattr(Color, "TRANSPARENT", 0),
                            int(getattr(self, "_nowbox_original_actionbar_color", 0) or 0)
                        ]
                        orientation = None
                        try:
                            orientation = getattr(getattr(GradientDrawable, "Orientation", None), "TOP_BOTTOM", None)
                        except Exception:
                            orientation = None
                        gradient = GradientDrawable(orientation, colors)
                except Exception:
                    gradient = None
                try:
                    layers = [cropped_drawable]
                    if scrim_drawable:
                        layers.append(scrim_drawable)
                    if gradient:
                        layers.append(gradient)
                    if LayerDrawable:
                        custom_drawable = LayerDrawable(layers)
                    else:
                        custom_drawable = cropped_drawable
                except Exception:
                    custom_drawable = cropped_drawable
                def apply_background_task():
                    try:
                        try:
                            if Color and hasattr(Color, "TRANSPARENT"):
                                action_bar.setBackgroundColor(Color.TRANSPARENT)
                        except Exception:
                            pass
                        action_bar.setBackgroundDrawable(custom_drawable)
                        try:
                            action_bar.invalidate()
                            action_bar.requestLayout()
                        except Exception:
                            pass
                    except Exception:
                        pass
                run_on_ui_thread(apply_background_task, delay=40)
            except Exception:
                pass
        except Exception as e:
            try:
                if not bool(self.get_setting("disable_logs", False)):
                    pass
            except Exception:
                pass

    def _restore_nowbox_banner(self, fragment_hint=None):
        try:
            fragment = self._resolve_nowbox_actionbar_target(fragment_hint)
            if not fragment:
                return
            frag_name = ""
            try:
                frag_name = str(fragment.getClass().getName() or "")
            except Exception:
                frag_name = ""
            if "DialogsActivity" not in frag_name:
                return
            action_bar = None
            try:
                action_bar = fragment.getActionBar()
            except Exception:
                action_bar = None
            if not action_bar:
                try:
                    action_bar = get_private_field(fragment, "actionBar")
                except Exception:
                    action_bar = None
            if not action_bar:
                return
            orig_drawable = getattr(self, "_nowbox_original_actionbar_drawable", None)
            orig_color = getattr(self, "_nowbox_original_actionbar_color", None)
            def restore():
                try:
                    if orig_drawable:
                        action_bar.setBackgroundDrawable(orig_drawable)
                    if orig_color is not None:
                        action_bar.setBackgroundColor(orig_color)
                    else:
                        try:
                            action_bar.setBackgroundColor(Theme.getColor(Theme.key_actionBarDefault))
                        except Exception:
                            pass
                except Exception:
                    pass
            run_on_ui_thread(restore)
        except Exception as e:
            try:
                if not bool(self.get_setting("disable_logs", False)):
                    pass
            except Exception:
                pass

    def _get_spotify_current_track_simple(self):
        try:
            token = self._get_access_token(show_error_bulletin=False)
            if not token:
                return None
            headers = {"Authorization": f"Bearer {token}"}
            try:
                resp = requests.get(
                    "https://api.spotify.com/v1/me/player/currently-playing",
                    headers=headers,
                    timeout=5
                )
                if resp.status_code == 200 and resp.content:
                    data = resp.json()
                    track = data.get("item")
                    if track:
                        name = track.get("name", "")
                        artists = ", ".join([a.get("name", "") for a in track.get("artists", [])])
                        tid = track.get("id", "")
                        cover_url = None
                        try:
                            album = track.get("album") or {}
                            images = album.get("images") or []
                            cover_url = next((img.get("url") for img in images if img and img.get("url")), None)
                        except Exception:
                            cover_url = None
                        return {"id": tid, "name": name, "artist": artists, "source": "spotify", "unique_key": f"spotify_{tid}_{name}_{artists}", "cover_url": cover_url}
            except Exception:
                pass
            try:
                resp2 = requests.get(
                    "https://api.spotify.com/v1/me/player",
                    headers=headers,
                    timeout=5
                )
                if resp2.status_code == 200 and resp2.text:
                    data2 = resp2.json()
                    if not bool(data2.get("is_playing", False)):
                        return None
                    track2 = data2.get("item")
                    if track2:
                        name2 = track2.get("name", "")
                        artists2 = ", ".join([a.get("name", "") for a in track2.get("artists", [])])
                        tid2 = track2.get("id", "")
                        cover_url2 = None
                        try:
                            album2 = track2.get("album") or {}
                            images2 = album2.get("images") or []
                            cover_url2 = next((img.get("url") for img in images2 if img and img.get("url")), None)
                        except Exception:
                            cover_url2 = None
                        return {"id": tid2, "name": name2, "artist": artists2, "source": "spotify", "unique_key": f"spotify_{tid2}_{name2}_{artists2}", "cover_url": cover_url2}
            except Exception:
                pass
            return None
        except Exception:
            return None

    def _get_song_link(self, spotify_url):
        try:
            if not spotify_url:
                return None
            url = str(spotify_url).strip()
            if not url:
                return None
            base = url.split("?", 1)[0].rstrip("/")
            if "/" not in base:
                return None
            track_id = base.split("/")[-1].strip()
            if not track_id:
                return None
            return f"https://song.link/s/{track_id}"
        except Exception as e:
            return None

    def _capture_original_bio(self):
        try:
            if self.get_setting("original_bio_captured", False):
                return
            user_full = get_messages_controller().getUserFull(get_user_config().getClientUserId())
            if user_full and user_full.about:
                self.set_setting("original_bio", user_full.about)
                self.set_setting("original_bio_captured", True)
                current_restore_text = self.get_setting("restore_bio_text", "").strip()
                if not current_restore_text:
                    self.set_setting("restore_bio_text", user_full.about)
        except Exception as e:
            pass

    def _update_bio(self, text, show_bulletin=False, is_restore=False):
        try:
            user_full = get_messages_controller().getUserFull(get_user_config().getClientUserId())
            max_len = 140 if get_user_config().isPremium() else 70
            req = TL_account.updateProfile()
            req.flags = 4
            req.about = text[:max_len]
            send_request(req, (lambda _res: None))
            if show_bulletin:
                BulletinHelper.show_success(tr("bio_restored"))
            elif self.get_setting("show_bio_notification", True) and self.get_setting("enable_auto_bio_update", True):
                if is_restore:
                    pass
                else:
                    BulletinHelper.show_info(tr("bio_updated_short"))
        except Exception as e:
            if show_bulletin or self.get_setting("show_bio_notification", True):
                BulletinHelper.show_with_button(tr("bio_error"), R.raw.error, "OK", None)

    def _get_cache_ttl_seconds(self):
        try:
            raw = self.get_setting("cache_ttl", "5")
            ttl_minutes = float(str(raw).strip().replace(",", "."))
            ttl_seconds = int(ttl_minutes * 60)
        except Exception:
            ttl_seconds = 300
        return max(30, min(3600, ttl_seconds))

    def _on_cache_ttl_changed(self, value):
        try:
            if NOWFY_CORE_API:
                NOWFY_CORE_API.on_cache_ttl_changed(self)
                return
        except Exception:
            pass
        try:
            self._cache_ttl = self._get_cache_ttl_seconds()
        except Exception:
            pass

    def _upgrade_cover_url_quality(self, url):
        try:
            u = str(url or "").strip()
            if not u or u.startswith("https://assets.nowfy/"):
                return u
            out = u
            if "i.scdn.co/image/" in out:
                out = out.replace("ab67616d00004851", "ab67616d0000b273")
                out = out.replace("ab67616d00001e02", "ab67616d0000b273")
            if "deezer.com" in out:
                out = out.replace("cover_small", "cover_xl")
                out = out.replace("cover_medium", "cover_xl")
                out = out.replace("cover_big", "cover_xl")
            if "itunes.apple.com" in out:
                out = re.sub(r"/\d+x\d+bb", "/1200x1200bb", out)
                out = out.replace("100x100", "1200x1200")
            if ("last.fm" in out) or ("lastfm" in out):
                out = out.replace("/34s/", "/600x600/")
                out = out.replace("/64s/", "/600x600/")
                out = out.replace("/174s/", "/600x600/")
                out = out.replace("/300x300/", "/600x600/")
            return out
        except Exception:
            return str(url or "")

    def _pick_best_album_image_url(self, images):
        try:
            if not isinstance(images, list) or not images:
                return None
            size_map = {
                "small": 64,
                "medium": 174,
                "large": 300,
                "extralarge": 600,
                "mega": 1200,
            }
            best_url = None
            best_score = -1
            for item in images:
                if not isinstance(item, dict):
                    continue
                u = item.get("url") or item.get("#text")
                if not u:
                    continue
                try:
                    if self._is_lastfm_placeholder_image(u):
                        continue
                except Exception:
                    pass
                w = item.get("width", 0)
                try:
                    w = int(w or 0)
                except Exception:
                    w = 0
                if w <= 0:
                    s = str(item.get("size", "") or "").strip().lower()
                    w = int(size_map.get(s, 0))
                if w > best_score:
                    best_score = w
                    best_url = u
            if not best_url:
                return None
            return self._upgrade_cover_url_quality(best_url)
        except Exception:
            return None

    def _download_image_uncached(self, url, force_size=None):
        try:
            performance_mode = self.get_setting("performance_mode", 1)
            timeout = 5 if performance_mode == 0 else (10 if performance_mode == 1 else 15)
            download_url = self._upgrade_cover_url_quality(url)
            response = requests.get(download_url, timeout=timeout)
            if response.status_code != 200 and download_url != url:
                response = requests.get(url, timeout=timeout)
            if response.status_code != 200:
                return None
            image_data = response.content
            if self.get_setting("enable_compression", False) and force_size and not self._is_theme_base_image(url):
                image_data = self._optimize_image(image_data, force_size)
            return image_data
        except Exception as e:
            host = ""
            try:
                host = str(url or "").split("://", 1)[-1].split("/", 1)[0].strip().lower()
            except Exception:
                host = ""
            self._log_throttled(
                f"image_download_error_{host or 'unknown'}",
                f"[Nowfy] Error downloading image {url}: {e}",
                cooldown_sec=300
            )
            return None

    def _start_cache_system(self):
        self._cache_enabled = self._setting_bool("enable_cache", False)
        self._preload_enabled = self._setting_bool("enable_preload", False)
        self._cache_ttl = self._get_cache_ttl_seconds()
        should_run = self._cache_enabled or self._preload_enabled or bool(getattr(self, "_precard_enabled", True))
        if should_run and not self._cache_running:
            self._cache_running = True
            self._cache_thread = threading.Thread(target=self._cache_worker, daemon=True)
            self._cache_thread.start()
        elif not should_run:
            self._cache_running = False

    def _setting_bool(self, key, default=False):
        try:
            val = self.get_setting(key, default)
        except Exception:
            return bool(default)
        if isinstance(val, bool):
            return val
        if isinstance(val, (int, float)):
            return int(val) != 0
        if isinstance(val, str):
            s = val.strip().lower()
            if s in ("1", "true", "on", "yes", "enabled"):
                return True
            if s in ("0", "false", "off", "no", "disabled", ""):
                return False
        return bool(val)

    def _toggle_cache_system(self, enabled):
        try:
            if NOWFY_CORE_API:
                NOWFY_CORE_API.toggle_cache_system(self, enabled)
                return
        except Exception:
            pass
        self.set_setting("enable_cache", bool(enabled))
        self._cache_enabled = bool(enabled)
        self._cache_ttl = self._get_cache_ttl_seconds()
        if not self._cache_enabled:
            try:
                self.set_setting("enable_preload", False)
            except Exception:
                pass
            self._preload_enabled = False
        if self._cache_enabled:
            self._start_cache_system()
        else:
            self._cache_running = False
            with self._cache_lock:
                self._image_cache.clear()
                self._enhanced_image_cache.clear()
                if hasattr(self, "_youtube_thumbnail_cache"):
                    self._youtube_thumbnail_cache.clear()

    def _toggle_preload_system(self, enabled):
        try:
            if NOWFY_CORE_API:
                NOWFY_CORE_API.toggle_preload_system(self, enabled)
                return
        except Exception:
            pass
        self.set_setting("enable_preload", bool(enabled))
        self._preload_enabled = bool(enabled)
        cache_enabled = self._setting_bool("enable_cache", False)
        if self._preload_enabled or cache_enabled:
            self._start_cache_system()
        else:
            self._cache_running = False

    def _cache_worker(self):
        while self._cache_running:
            try:
                cache_enabled = self._setting_bool("enable_cache", False)
                preload_enabled = self._setting_bool("enable_preload", False)
                self._cache_enabled = cache_enabled
                self._preload_enabled = preload_enabled
                self._cache_ttl = self._get_cache_ttl_seconds()
                precard_enabled = bool(getattr(self, "_precard_enabled", True))
                if not cache_enabled and not preload_enabled and not precard_enabled:
                    time.sleep(2)
                    continue
                performance_mode = self.get_setting("performance_mode", 1)
                sleep_interval = 2 if performance_mode == 0 else (3 if performance_mode == 1 else 4)
                if not cache_enabled and not preload_enabled and precard_enabled:
                    sleep_interval = max(4, sleep_interval)
                snapshot = self._get_now_playing_snapshot(preferred_source=None, allow_cached=False)
                if snapshot and snapshot.get("track"):
                    track = snapshot.get("track")
                    source = snapshot.get("source")
                    track_key = self._make_track_key(source, track)
                    if track_key and track_key != self._last_track_id:
                        self._last_track_id = track_key
                        self._update_current_track_id(track.get("id") or track_key)
                        self._pre_render_current_track(track, source=source, progress_ms=snapshot.get("progress_ms", 0))
                        if preload_enabled and source == "spotify":
                            self._preload_next_track_cover()
                        self._cleanup_preload_cache()
                        self._cleanup_precard_cache()
                time.sleep(sleep_interval)
            except Exception:
                time.sleep(5)

    def _pre_render_current_track(self, track, source="spotify", progress_ms=0):
        try:
            snapshot = {
                "source": source,
                "track": track,
                "progress_ms": progress_ms
            }
            self._maybe_build_precard(snapshot)
        except Exception:
            pass

    def _bio_update_worker(self):
        self._nlog("[Nowfy] Bio update worker started")
        self._last_no_track_time = None
        self._restore_done = False
        while not self._stop_bio_update:
            try:
                if self.get_setting("enable_auto_bio_update", False):
                    self._nlog("[Nowfy] Auto bio update is enabled")
                    userFull = get_messages_controller().getUserFull(get_user_config().getClientUserId())
                    if not userFull:
                        self._nlog("[Nowfy] Failed to get userFull")
                        time.sleep(5)
                        continue
                    max_len = 140 if get_user_config().isPremium() else 70
                    services = []
                    has_spotify = (
                        (bool(self.get_setting("client_id", "")) and bool(self.get_setting("client_secret", "")) and bool(self.get_setting("refresh_token", "")))
                        or (bool(self.get_setting("quick_spotify_auth_enabled", False)) and bool(str(self.get_setting("quick_refresh_token", "") or "").strip()))
                    )
                    has_statsfm = bool(str(self.get_setting("statsfm_username", "") or "").strip())
                    has_lastfm = (
                        bool(str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", "")) or "").strip())
                        and bool(str(self.get_setting("lastfm_api_key", "") or "").strip())
                    )
                    if has_spotify: services.append("spotify")
                    if has_statsfm: services.append("statsfm")
                    if has_lastfm: services.append("lastfm")
                    if not services:
                        time.sleep(5)
                        continue
                    sel_idx = int(self.get_setting("bio_feature_service_idx", 0) or 0)
                    if sel_idx < 0 or sel_idx >= len(services):
                        sel_idx = 0
                    selected = services[sel_idx]
                    track_title = None
                    track_artists = None
                    track_id = None
                    progress_ms = 0
                    if selected == "spotify":
                        token = self._get_access_token(show_error_bulletin=False)
                        if token:
                            self._nlog("[Nowfy] Fetching current track (Spotify) for bio update")
                            resp = requests.get(
                                "https://api.spotify.com/v1/me/player/currently-playing",
                                headers={"Authorization": f"Bearer {token}"},
                                timeout=5
                            )
                            if resp.status_code == 200 and resp.content:
                                data = resp.json()
                                track = data.get("item")
                                if track:
                                    track_title = track.get("name")
                                    track_artists = ", ".join([a["name"] for a in track.get("artists", [])])
                                    track_id = track.get("id")
                                    progress_ms = data.get("progress_ms", 0)
                    elif selected == "statsfm":
                        username = str(self.get_setting("statsfm_username", "") or "").strip()
                        if username:
                            self._nlog("[Nowfy] Fetching current track (Statsfm) for bio update")
                            info = self._get_statsfm_current_track(username)
                            if info:
                                track_title = info.get("title")
                                artists = info.get("artists") or []
                                track_artists = ", ".join([a for a in artists]) if isinstance(artists, list) else str(artists or "")
                                track_id = info.get("id")
                                progress_ms = info.get("progress_ms", 0)
                    else:
                        user = str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", "")) or "").strip()
                        api_key = str(self.get_setting("lastfm_api_key", "") or "").strip()
                        if user and api_key:
                            self._nlog("[Nowfy] Fetching current track (Lastfm) for bio update")
                            info = self._get_lastfm_current_track(user, api_key)
                            if info:
                                track_title = info.get("title")
                                track_artists = info.get("artist")
                                track_id = None
                                progress_ms = info.get("progress_ms", 0)
                    if track_title and (track_artists is not None):
                        self._nlog(f"[Nowfy] Found track for bio update: {track_title}")
                        if track_id:
                            try:
                                self._update_current_track_id(track_id)
                            except Exception:
                                pass
                        autobio_text = self.get_setting("autobio_text", "Now Playing: {track} by {artist}")
                        bio = autobio_text.format(track=track_title, artist=track_artists or "")
                        if userFull.about != bio[:max_len]:
                            try:
                                req = TL_account.updateProfile()
                                req.flags = 4
                                req.about = bio[:max_len]
                                send_request(req, (lambda _res: None))
                                self._nlog("[Nowfy] Successfully updated bio automatically")
                            except Exception as e:
                                time.sleep(5)
                        self._last_no_track_time = None
                        self._restore_done = False
                    else:
                        self._nlog("[Nowfy] No track playing for bio update")
                        if self._last_no_track_time is None:
                            self._last_no_track_time = time.time()
                            self._restore_done = False
                        elif not self._restore_done and time.time() - self._last_no_track_time >= 600:
                            try:
                                current_bio = userFull.about if userFull else ""
                                restore_bio_text = self.get_setting("restore_bio_text", "").strip()
                                if current_bio and current_bio.strip():
                                    default_bio = current_bio
                                elif restore_bio_text:
                                    default_bio = restore_bio_text
                                else:
                                    default_bio = "I'm using nowFy!"
                            except:
                                restore_bio_text = self.get_setting("restore_bio_text", "").strip()
                                if restore_bio_text:
                                    default_bio = restore_bio_text
                                else:
                                    default_bio = "I'm using nowFy!"
                            if userFull.about != default_bio[:max_len]:
                                try:
                                    req = TL_account.updateProfile()
                                    req.flags = 4
                                    req.about = default_bio[:max_len]
                                    send_request(req, (lambda _res: None))
                                    self._nlog("[Nowfy] Restored bio after inactivity")
                                except Exception as e:
                                    pass
                            self._restore_done = True
                    time.sleep(120)
                else:
                    time.sleep(5)
            except Exception as e:
                self._nlog(f"[Nowfy] Bio update worker error: {e}")
                time.sleep(10)

    def _clear_cache(self):
        try:
            if NOWFY_CORE_API:
                NOWFY_CORE_API.clear_cache_data(self)
            else:
                with self._cache_lock:
                    self._image_cache.clear()
                    self._cache_timestamps.clear()
                    if hasattr(self, '_enhanced_image_cache'):
                        self._enhanced_image_cache.clear()
                    if hasattr(self, '_base_theme_cache'):
                        self._base_theme_cache.clear()
                    if hasattr(self, '_apple_cache'):
                        self._apple_cache.clear()
        except Exception:
            pass
        BulletinHelper.show_success(tr("cache_cleared"))

    def _get_cached_image_enhanced(self, url, cache_key=None, force_size=None):
        download_url = self._upgrade_cover_url_quality(url)
        if not bool(self.get_setting("enable_cache", False)):
            return self._download_image_uncached(download_url, force_size=force_size)
        if not self.get_setting("enhanced_cache", True):
            return self._get_cached_image_original(download_url)
        if not cache_key:
            cache_key = download_url
        try:
            asset_sig = _nowfy_get_local_asset_signature(download_url) or _nowfy_get_local_asset_signature(url)
            if asset_sig:
                cache_key = f"{cache_key}|asset:{asset_sig}"
        except Exception:
            pass
        with self._cache_lock:
            if cache_key in self._enhanced_image_cache:
                cached_data = self._enhanced_image_cache[cache_key]
                if time.time() - cached_data['timestamp'] < self._cache_ttl:
                    return cached_data['image']
                else:
                    del self._enhanced_image_cache[cache_key]
        try:
            stable_key = hashlib.md5(str(cache_key).encode("utf-8")).hexdigest()
        except Exception:
            stable_key = hashlib.md5(str(cache_key).encode()).hexdigest()
        disk_cache_file = File(self._disk_cache_dir, f"{stable_key}.cache")
        if disk_cache_file.exists():
            try:
                with open(disk_cache_file.getAbsolutePath(), 'rb') as f:
                    cached_image = f.read()
                    with self._cache_lock:
                        self._enhanced_image_cache[cache_key] = {
                            'image': cached_image,
                            'timestamp': time.time()
                        }
                    return cached_image
            except Exception:
                pass
        try:
            performance_mode = self.get_setting("performance_mode", 1)
            timeout = 5 if performance_mode == 0 else (10 if performance_mode == 1 else 15)
            response = requests.get(download_url, timeout=timeout)
            if response.status_code != 200 and download_url != url:
                response = requests.get(url, timeout=timeout)
            if response.status_code == 200:
                image_data = response.content
                if self.get_setting("enable_compression", False) and not self._is_theme_base_image(url):
                    if force_size:
                        image_data = self._optimize_image(image_data, force_size)
                    else:
                        pass
                with self._cache_lock:
                    self._enhanced_image_cache[cache_key] = {
                        'image': image_data,
                        'timestamp': time.time()
                    }
                    if len(self._enhanced_image_cache) > self._cache_max_size:
                        oldest_key = min(self._enhanced_image_cache.keys(),
                                        key=lambda k: self._enhanced_image_cache[k]['timestamp'])
                        del self._enhanced_image_cache[oldest_key]
                try:
                    with open(disk_cache_file.getAbsolutePath(), 'wb') as f:
                        f.write(image_data)
                except Exception:
                    pass
                return image_data
        except Exception as e:
            host = ""
            try:
                host = str(url or "").split("://", 1)[-1].split("/", 1)[0].strip().lower()
            except Exception:
                host = ""
            self._log_throttled(
                f"image_download_error_{host or 'unknown'}",
                f"[Nowfy] Error downloading image {url}: {e}",
                cooldown_sec=300
            )
        return None

    def _is_theme_base_image(self, url):
        theme_base_urls = [
            "https://assets.nowfy/applelight.png",
            "https://assets.nowfy/appledark.png",
            "https://assets.nowfy/applered.png",
            "https://assets.nowfy/applelightsoundcloud.png",
            "https://assets.nowfy/appledarksoundcloud.png",
            "https://assets.nowfy/appleredyoutubelight.png",
            "https://assets.nowfy/appleredyoutubedark.png",
            "https://assets.nowfy/applelightytmusic.png",
            "https://assets.nowfy/appledarkytmusic.png",
            "https://assets.nowfy/etglight.png",
            "https://assets.nowfy/etgdark.png",
            "https://assets.nowfy/ayulight.png",
            "https://assets.nowfy/ayudark.png",
            "https://assets.nowfy/ayured.png",
            "https://assets.nowfy/applelightapplelight.png",
            "https://assets.nowfy/appledarkapple.png",
            "https://assets.nowfy/appleredapple.png"
        ]
        return url in theme_base_urls

    def _optimize_image(self, image_data, target_size=None):
        try:
            img = Image.open(io.BytesIO(image_data))
            if target_size and img.size != target_size:
                img = ImageOps.fit(img, target_size, method=Image.LANCZOS, centering=(0.5, 0.5))
            performance_mode = self.get_setting("performance_mode", 1)
            compress_level = 1 if performance_mode == 0 else (2 if performance_mode == 1 else 3)
            output = io.BytesIO()
            img.save(output, format='PNG', optimize=True, compress_level=compress_level)
            return output.getvalue()
        except Exception as e:
            return image_data

    def _maybe_compact_card_image(self, temp_path):
        try:
            if not self.get_setting("compact_card_images", False):
                return temp_path
            img = Image.open(temp_path)
            if img.mode in ("RGBA", "LA", "P"):
                bg = Image.new("RGB", img.size, (0, 0, 0))
                bg.paste(img, mask=img.split()[-1] if img.mode in ("RGBA", "LA") else None)
                img = bg
            else:
                img = img.convert("RGB")
            performance_mode = self.get_setting("performance_mode", 1)
            quality = 78 if performance_mode == 0 else (82 if performance_mode == 1 else 88)
            compact_path = os.path.splitext(temp_path)[0] + ".jpg"
            img.save(compact_path, format="JPEG", quality=quality, optimize=True)
            return compact_path
        except Exception:
            return temp_path

    def _get_settings_version(self):
        try:
            return int(getattr(self, "_settings_version", 0))
        except Exception:
            return 0

    def _track_artist_string(self, track):
        try:
            artists = track.get("artists", [])
            if isinstance(artists, list):
                return ", ".join([a.get("name", "") for a in artists if isinstance(a, dict) and a.get("name")])
            return str(artists or "")
        except Exception:
            return ""

    def _make_track_key(self, source, track):
        try:
            if not track:
                return None
            tid = track.get("id") or ""
            title = str(track.get("name") or track.get("title") or "").strip()
            artist = self._track_artist_string(track)
            if not tid and not title:
                return None
            return f"{source}|{tid}|{title}|{artist}"
        except Exception:
            return None

    def _get_cached_nowplaying_snapshot(self, source):
        try:
            if not source:
                return None
            entry = self._nowplaying_cache.get(source)
            if not entry:
                return None
            if time.time() - float(entry.get("ts", 0.0)) > float(self._nowplaying_cache_ttl or 0):
                return None
            return entry
        except Exception:
            return None

    def _store_nowplaying_snapshot(self, source, snapshot):
        try:
            if not source or not snapshot:
                return
            snapshot["ts"] = time.time()
            self._nowplaying_cache[source] = snapshot
        except Exception:
            pass

    def _fetch_now_playing_snapshot(self, source):
        try:
            if source == "spotify":
                token = self._get_access_token(show_error_bulletin=False)
                if not token:
                    return None
                resp = requests.get(
                    "https://api.spotify.com/v1/me/player/currently-playing",
                    headers={"Authorization": f"Bearer {token}"},
                    timeout=5
                )
                if resp.status_code == 200 and resp.content:
                    data = resp.json()
                    track = data.get("item")
                    if track:
                        return {
                            "source": "spotify",
                            "track": track,
                            "progress_ms": data.get("progress_ms", 0),
                            "is_playing": bool(data.get("is_playing", False))
                        }
                return None
            if source == "statsfm":
                try:
                    statsfm_username = str(self.get_setting("statsfm_username", "")).strip()
                except Exception:
                    statsfm_username = ""
                if not statsfm_username:
                    return None
                url = f"https://api.stats.fm/api/v1/users/{statsfm_username}/streams/current"
                headers = {"Accept": "application/json", "User-Agent": "NowfyPlugin/1.0"}
                resp = requests.get(url, headers=headers, timeout=5)
                if resp.status_code == 200:
                    data = resp.json()
                    item = data.get("item")
                    if item and item.get("isPlaying"):
                        track_info = item.get("track", {})
                        artists_list = []
                        for artist_name in track_info.get("artists", []):
                            artists_list.append({"name": artist_name["name"]})
                        album = track_info["albums"][0] if track_info.get("albums") else {}
                        album_images = []
                        if album.get("image"):
                            album_images.append({"url": album.get("image"), "width": 640, "height": 640})
                        spotify_id = None
                        if track_info.get("externalIds") and track_info["externalIds"].get("spotify"):
                            spotify_id = track_info["externalIds"]["spotify"][0]
                        track = {
                            "name": track_info.get("name", ""),
                            "artists": artists_list,
                            "album": {"name": album.get("name", ""), "images": album_images},
                            "external_urls": {
                                "spotify": f"https://open.spotify.com/track/{spotify_id}" if spotify_id else None
                            },
                            "duration_ms": track_info.get("durationMs", 0)
                        }
                        return {
                            "source": "statsfm",
                            "track": track,
                            "progress_ms": item.get("progressMs", 0),
                            "is_playing": True
                        }
                return None
            if source == "ymusic":
                try:
                    _tk = str(self.get_setting("ymusic_api_token", "") or "").strip()
                    if not _tk:
                        return None
                except Exception:
                    return None
                try:
                    ydata = self._read_ymusic_api_now_playing(self)
                except Exception:
                    ydata = None
                if isinstance(ydata, dict):
                    track_obj = ydata.get("track_obj")
                    if isinstance(track_obj, dict) and str(track_obj.get("name") or "").strip():
                        return {
                            "source": "ymusic",
                            "track": track_obj,
                            "progress_ms": int(ydata.get("position_ms", 0) or 0),
                            "is_playing": bool(ydata.get("is_playing", True))
                        }
                return None
            if source == "lastfm":
                try:
                    user = str(self.get_setting("lastfm_user", self.get_setting("lastfm_username", ""))).strip()
                    api_key = str(self.get_setting("lastfm_api_key", "")).strip()
                except Exception:
                    user, api_key = "", ""
                if not user or not api_key:
                    return None
                url = "https://ws.audioscrobbler.com/2.0/"
                params_lastfm = {
                    "method": "user.getrecenttracks",
                    "user": user,
                    "api_key": api_key,
                    "format": "json",
                    "limit": 1
                }
                resp = requests.get(url, params=params_lastfm, timeout=5)
                if resp.status_code == 200:
                    data = resp.json()
                    tracks = data.get("recenttracks", {}).get("track", [])
                    if tracks and isinstance(tracks, list):
                        track = tracks[0]
                        current_time = int(_t.time())
                        is_now_playing = track.get("@attr", {}).get("nowplaying") == "true"
                        is_recent = False
                        if not is_now_playing and "date" in track:
                            track_time = int(track["date"]["uts"])
                            is_recent = (current_time - track_time) <= 600
                        elif not is_now_playing:
                            is_recent = True
                        if is_now_playing or is_recent:
                            title = self._normalize_lastfm_track_title(track)
                            artist_name = track.get("artist", {}).get("#text", "") if isinstance(track.get("artist"), dict) else str(track.get("artist", ""))
                            album_name = track.get("album", {}).get("#text", "") if isinstance(track.get("album"), dict) else str(track.get("album", ""))
                            image_url = None
                            images = track.get("image", [])
                            if images:
                                size_order = ["mega", "extralarge", "large", "medium", "small"]
                                size_map = {}
                                for img in images:
                                    img_size = img.get("size")
                                    img_url = (img.get("#text") or "").strip()
                                    if img_size and img_url:
                                        size_map[img_size] = img_url
                                for size_name in size_order:
                                    if size_map.get(size_name):
                                        image_url = size_map[size_name]
                                        break
                                if not image_url:
                                    for img in reversed(images):
                                        img_url = (img.get("#text") or "").strip()
                                        if img_url:
                                            image_url = img_url
                                            break
                            if not image_url:
                                try:
                                    fallback_cover = self._get_spotify_cover_precise(title, artist_name, album_name)
                                except Exception:
                                    fallback_cover = None
                                if fallback_cover:
                                    image_url = fallback_cover
                                    try:
                                        self._di_last_cover_url = image_url
                                    except Exception:
                                        pass
                            track_obj = {
                                "name": title,
                                "artists": [{"name": artist_name}],
                                "album": {
                                    "name": album_name,
                                    "images": [{"url": image_url, "width": 640, "height": 640}] if image_url else []
                                },
                                "external_urls": {"spotify": None},
                                "duration_ms": 0
                            }
                            return {
                                "source": "lastfm",
                                "track": track_obj,
                                "progress_ms": 0,
                                "is_playing": bool(is_now_playing or is_recent)
                            }
                return None
        except Exception:
            return None

    def _get_now_playing_snapshot(self, preferred_source=None, allow_cached=True):
        try:
            sources = [preferred_source] if preferred_source else ["statsfm", "spotify", "lastfm", "ymusic"]
            for src in sources:
                if allow_cached:
                    cached = self._get_cached_nowplaying_snapshot(src)
                    if cached and cached.get("track"):
                        return cached
                snap = self._fetch_now_playing_snapshot(src)
                if snap and snap.get("track"):
                    self._store_nowplaying_snapshot(src, snap)
                    return snap
            return None
        except Exception:
            return None

    def _prepare_track_for_send(self, track):
        try:
            if not track:
                return track
            if "external_urls" not in track or not isinstance(track.get("external_urls"), dict):
                track["external_urls"] = {}
            return track
        except Exception:
            return track

    def _get_precard_entry(self, source):
        try:
            if not source:
                return None
            entry = self._precard_cache.get(source)
            if not entry:
                return None
            if time.time() - float(entry.get("ts", 0.0)) > float(self._precard_cache_ttl or 0):
                return None
            if int(entry.get("settings_version", 0)) != self._get_settings_version():
                return None
            return entry
        except Exception:
            return None

    def _cleanup_precard_cache(self):
        try:
            now = time.time()
            current_ver = self._get_settings_version()
            expired = []
            for src, entry in list(self._precard_cache.items()):
                if now - float(entry.get("ts", 0.0)) > float(self._precard_cache_ttl or 0):
                    expired.append(src)
                    continue
                if int(entry.get("settings_version", 0)) != current_ver:
                    expired.append(src)
            for src in expired:
                try:
                    del self._precard_cache[src]
                except Exception:
                    pass
        except Exception:
            pass

    def _maybe_build_precard(self, snapshot):
        try:
            if not snapshot or not snapshot.get("track"):
                return
            source = snapshot.get("source")
            track = snapshot.get("track")
            track_key = self._make_track_key(source, track)
            if not track_key:
                return
            now_ts = time.time()
            settings_version = self._get_settings_version()
            with self._precard_lock:
                existing = self._precard_cache.get(source)
                if existing:
                    if existing.get("track_key") == track_key and int(existing.get("settings_version", 0)) == settings_version:
                        if now_ts - float(existing.get("ts", 0.0)) <= float(self._precard_cache_ttl or 0):
                            return
            force_spotify = (source == "spotify")
            is_fm_command = (source == "lastfm")
            progress_ms = snapshot.get("progress_ms", 0)
            original_forced_player = getattr(self, "_forced_player", None)
            try:
                if source == "statsfm":
                    try:
                        stats_source = int(self.get_setting("statsfm_source_player", 0) or 0)
                    except Exception:
                        stats_source = 0
                    self._forced_player = "Apple Music" if stats_source == 1 else "Spotify"
                temp_path = self._generate_card(track, None, progress_ms, force_spotify=force_spotify, etg_cover_image=None, is_fm_command=is_fm_command)
            finally:
                if original_forced_player is not None:
                    self._forced_player = original_forced_player
                else:
                    if hasattr(self, "_forced_player"):
                        try:
                            delattr(self, "_forced_player")
                        except Exception:
                            pass
            if not temp_path:
                return
            with self._precard_lock:
                self._precard_cache[source] = {
                    "track_key": track_key,
                    "track": track,
                    "path": temp_path,
                    "progress_ms": progress_ms,
                    "ts": now_ts,
                    "settings_version": settings_version
                }
        except Exception:
            pass

    def _try_send_precard(self, params, source, force_spotify=False):
        try:
            entry = self._get_precard_entry(source)
            if not entry:
                return False
            temp_path = entry.get("path")
            track = entry.get("track")
            if not temp_path or not track:
                return False
            self._prepare_track_for_send(track)
            self._set_tab_feedback_progress(80)
            original_forced_player = getattr(self, "_forced_player", None)
            try:
                if source == "lastfm":
                    self._forced_player = "FM"
                elif source == "statsfm":
                    try:
                        stats_source = int(self.get_setting("statsfm_source_player", 0) or 0)
                    except Exception:
                        stats_source = 0
                    self._forced_player = "Apple Music" if stats_source == 1 else "Spotify"
                elif source == "spotify":
                    self._forced_player = "Spotify"
                self._send_card_with_caption(params, temp_path, track, force_spotify, skip_compact=True)
            finally:
                if original_forced_player is not None:
                    self._forced_player = original_forced_player
                else:
                    if hasattr(self, "_forced_player"):
                        try:
                            delattr(self, "_forced_player")
                        except Exception:
                            pass
            return True
        except Exception:
            return False

    def _preload_next_track_cover(self):
        if not self.get_setting("enable_preload", False):
            return
        try:
            threading.Thread(target=self._preload_worker, daemon=True).start()
        except Exception as e:
            pass

    def _preload_worker(self):
        try:
            account = self._get_account()
            if account is None:
                return
            token = self._get_spotify_token(account)
            if not token:
                return
            queue_data = self._get_spotify_queue(token)
            if not queue_data:
                return
            next_tracks = queue_data.get('queue', [])[:5]
            for i, track in enumerate(next_tracks):
                try:
                    self._preload_track_card(track, i + 1)
                    time.sleep(0.5)
                except Exception as e:
                    pass
        except Exception as e:
            pass

    def _get_spotify_queue(self, token):
        try:
            resp = requests.get(
                "https://api.spotify.com/v1/me/player/queue",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code == 200:
                return resp.json()
            resp = requests.get(
                "https://api.spotify.com/v1/me/player/recently-playedlimit=10",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code == 200:
                recent_data = resp.json()
                return {
                    'queue': [item['track'] for item in recent_data.get('items', [])]
                }
            return None
        except Exception as e:
            return None

    def _preload_track_card(self, track, position):
        try:
            if not track or not track.get('id'):
                return
            track_id = track['id']
            track_name = track.get('name', 'Unknown')
            artists = [artist['name'] for artist in track.get('artists', [])]
            artist_name = ', '.join(artists) if artists else 'Unknown'
            album_name = track.get('album', {}).get('name', 'Unknown')
            cache_key = f"preload_{track_id}_{position}"
            if hasattr(self, '_preload_cache') and cache_key in self._preload_cache:
                cached_data = self._preload_cache[cache_key]
                if time.time() - cached_data['timestamp'] < 1800:
                    return
            album_images = track.get('album', {}).get('images', [])
            image_url = ''
            if album_images:
                image_url = album_images[0]['url']
            if image_url:
                cover_cache_key = f"preload_cover_{track_id}"
                cover_data = self._get_cached_image_enhanced(
                    image_url,
                    cache_key=cover_cache_key,
                    force_size=298
                )
            theme_mode = self.get_setting("theme_mode", 0)
            card_data = None
            if theme_mode in [0, 1, 2]:
                card_data = self._prerender_apple_card(track, image_url, theme_mode)
            elif theme_mode == 3:
                card_data = self._prerender_fmcard_card(track, image_url)
            elif theme_mode == 4:
                card_data = self._prerender_default_card(track, image_url)
            if not hasattr(self, '_preload_cache'):
                self._preload_cache = {}
            self._preload_cache[cache_key] = {
                'track_data': {
                    'id': track_id,
                    'name': track_name,
                    'artist': artist_name,
                    'album': album_name,
                    'image_url': image_url
                },
                'card_data': card_data,
                'timestamp': time.time(),
                'position': position
            }
            if len(self._preload_cache) > 20:
                oldest_key = min(self._preload_cache.keys(),
                               key=lambda k: self._preload_cache[k]['timestamp'])
                del self._preload_cache[oldest_key]
        except Exception as e:
            pass

    def _prerender_apple_card(self, track, image_url, theme_mode):
        try:
            return {
                'type': 'apple',
                'theme_mode': theme_mode,
                'track': track,
                'image_url': image_url,
                'rendered': True
            }
        except Exception as e:
            return None

    def _prerender_fmcard_card(self, track, image_url):
        try:
            return {
                'type': 'fmcard',
                'track': track,
                'image_url': image_url,
                'rendered': True
            }
        except Exception as e:
            return None

    def _prerender_default_card(self, track, image_url):
        try:
            return {
                'type': 'default',
                'track': track,
                'image_url': image_url,
                'rendered': True
            }
        except Exception as e:
            return None

    def get_preloaded_track(self, track_id):
        try:
            if not hasattr(self, '_preload_cache'):
                return None
            for cache_key, cached_data in self._preload_cache.items():
                if cached_data['track_data']['id'] == track_id:
                    if time.time() - cached_data['timestamp'] < 1800:
                        return cached_data
                    else:
                        del self._preload_cache[cache_key]
                        break
            return None
        except Exception as e:
             return None

    def _is_preloaded_card_compatible(self, preloaded_card, current_theme):
        try:
            if not preloaded_card or not preloaded_card.get('type'):
                return False
            card_type = preloaded_card['type']
            external_themes, spotlight_index, vinni_index, nowv_index, fmcard_index, legacy_theme_b_index = self._get_theme_indices()
            apple_skin_setting = int(self.get_setting("apple_skin", 0) or 0)
            spotlight_skin_setting = int(self.get_setting("spotlight_skin", 0) or 0)
            if card_type == 'apple' and current_theme == 0:
                if apple_skin_setting == 2:
                    return False
                try:
                    current_skin = self._get_apple_skin_index_mapped()
                except Exception:
                    current_skin = 0
                return preloaded_card.get('theme_mode') == current_skin
            elif card_type == 'fmcard' and current_theme == fmcard_index:
                return True
            elif card_type == 'default' and current_theme == spotlight_index:
                if spotlight_skin_setting == 3:
                    return False
                return True
            return False
        except Exception as e:
            return False

    def _process_preloaded_card(self, preloaded_card, params, progress_ms, is_fm_command):
        try:
            if not preloaded_card or not preloaded_card.get('track'):
                return
            track = preloaded_card['track']
            image_url = preloaded_card.get('image_url', '')
            card_type = preloaded_card.get('type', 'default')
            if card_type == 'apple':
                theme_mode = preloaded_card.get('theme_mode', 0)
                self._process_preloaded_apple_card(track, image_url, theme_mode, params, progress_ms, is_fm_command)
            elif card_type == 'fmcard':
                self._process_preloaded_fmcard_card(track, image_url, params, progress_ms, is_fm_command)
            elif card_type == 'default':
                self._process_preloaded_default_card(track, image_url, params, progress_ms, is_fm_command)
        except Exception as e:
            pass

    def _process_preloaded_apple_card(self, track, image_url, theme_mode, params, progress_ms, is_fm_command):
        try:
            title = track.get('name', 'Unknown')
            artists = [artist['name'] for artist in track.get('artists', [])] if track.get('artists') else ['Unknown']
            artist = ', '.join(artists)
            album = track.get('album', {}).get('name', 'Unknown') if track.get('album') else 'Unknown'
            self._get_current_track_lastfm_fmcard(
                title, artist, album, image_url, params,
                progress_dialog=None, player="Spotify",
                youtube_url=None, etg_cover_image=None
            )
        except Exception as e:
            pass

    def _process_preloaded_fmcard_card(self, track, image_url, params, progress_ms, is_fm_command):
        try:
            title = track.get('name', 'Unknown')
            artists = [artist['name'] for artist in track.get('artists', [])] if track.get('artists') else ['Unknown']
            artist = ', '.join(artists)
            album = track.get('album', {}).get('name', 'Unknown') if track.get('album') else 'Unknown'
            self._get_current_track_lastfm_fmcard(
                title, artist, album, image_url, params,
                progress_dialog=None, player="Spotify",
                youtube_url=None, etg_cover_image=None
            )
        except Exception as e:
            pass

    def _process_preloaded_default_card(self, track, image_url, params, progress_ms, is_fm_command):
        try:
            title = track.get('name', 'Unknown')
            artists = [artist['name'] for artist in track.get('artists', [])] if track.get('artists') else ['Unknown']
            artist = ', '.join(artists)
            album = track.get('album', {}).get('name', 'Unknown') if track.get('album') else 'Unknown'
            self._get_current_track_lastfm_default(
                title, artist, album, image_url, params,
                progress_dialog=None, player="Spotify",
                youtube_url=None, etg_cover_image=None
            )
        except Exception as e:
            pass

    def _cleanup_preload_cache(self):
        try:
            if not hasattr(self, '_preload_cache'):
                return
            current_time = time.time()
            cache_ttl = self._get_cache_ttl_seconds()
            expired_keys = []
            for track_id, data in self._preload_cache.items():
                if current_time - data.get('timestamp', 0) > cache_ttl:
                    expired_keys.append(track_id)
            for key in expired_keys:
                del self._preload_cache[key]
            if len(self._preload_cache) > 10:
                sorted_items = sorted(self._preload_cache.items(),
                                    key=lambda x: x[1].get('timestamp', 0))
                for track_id, _ in sorted_items[:-10]:
                    del self._preload_cache[track_id]
        except Exception as e:
            pass

    def _is_track_currently_playing(self, track_id):
        try:
            if not hasattr(self, '_current_track_id'):
                return False
            return self._current_track_id == track_id
        except Exception as e:
            return False

    def _update_current_track_id(self, track_id):
        try:
            self._current_track_id = track_id
        except Exception as e:
            pass

    def _get_cached_fmcard_image(self, cache_key, temp_dir):
        try:
            cache_file = File(temp_dir, f"fmcard_{cache_key}.png")
            if cache_file.exists():
                file_time = cache_file.lastModified()
                current_time = int(time.time() * 1000)
                if (current_time - file_time) < 3600000:
                    return cache_file.getAbsolutePath()
                else:
                    cache_file.delete()
            return None
        except Exception as e:
            return None

    def _get_cached_image_original(self, url):
        if not bool(self.get_setting("enable_cache", False)):
            return self._download_image_uncached(self._upgrade_cover_url_quality(url))
        download_url = self._upgrade_cover_url_quality(url)
        cache_key = download_url
        try:
            asset_sig = _nowfy_get_local_asset_signature(download_url) or _nowfy_get_local_asset_signature(url)
            if asset_sig:
                cache_key = f"{cache_key}|asset:{asset_sig}"
        except Exception:
            pass
        current_time = time.time()
        with self._cache_lock:
            if cache_key in self._image_cache:
                if current_time - self._cache_timestamps.get(cache_key, 0) < self._cache_ttl:
                    return self._image_cache[cache_key]
                else:
                    del self._image_cache[cache_key]
                    if cache_key in self._cache_timestamps:
                        del self._cache_timestamps[cache_key]
        try:
            response = requests.get(download_url, timeout=10)
            if response.status_code != 200 and download_url != url:
                response = requests.get(url, timeout=10)
            if response.status_code == 200:
                image_data = response.content
                with self._cache_lock:
                    self._image_cache[cache_key] = image_data
                    self._cache_timestamps[cache_key] = current_time
                return image_data
        except Exception as e:
            host = ""
            try:
                host = str(url or "").split("://", 1)[-1].split("/", 1)[0].strip().lower()
            except Exception:
                host = ""
            self._log_throttled(
                f"image_download_error_{host or 'unknown'}",
                f"[Nowfy] Error downloading image {url}: {e}",
                cooldown_sec=300
            )
        return None

    def _get_youtube_thumbnail_cached(self, video_id, quality='maxresdefault'):
        if not self.get_setting("enable_youtube_thumbnail_cache", False):
            return self._get_youtube_thumbnail_direct(video_id, quality)
        cache_key = f"yt_thumb_{video_id}_{quality}"
        with self._cache_lock:
            if hasattr(self, '_youtube_thumbnail_cache') and cache_key in self._youtube_thumbnail_cache:
                cached_data = self._youtube_thumbnail_cache[cache_key]
                if time.time() - cached_data['timestamp'] < self._cache_ttl:
                    return cached_data['data']
                else:
                    del self._youtube_thumbnail_cache[cache_key]
        if not hasattr(self, '_youtube_thumbnail_cache'):
            self._youtube_thumbnail_cache = {}
        thumbnail_data = self._get_youtube_thumbnail_direct(video_id, quality)
        if thumbnail_data:
            with self._cache_lock:
                self._youtube_thumbnail_cache[cache_key] = {
                    'data': thumbnail_data,
                    'timestamp': time.time()
                }
                if len(self._youtube_thumbnail_cache) > 50:
                    oldest_key = min(self._youtube_thumbnail_cache.keys(),
                                    key=lambda k: self._youtube_thumbnail_cache[k]['timestamp'])
                    del self._youtube_thumbnail_cache[oldest_key]
        return thumbnail_data

    def _get_youtube_thumbnail_direct(self, video_id, quality='maxresdefault'):
        qualities = ['maxresdefault', 'hq720', 'sddefault', 'hqdefault', 'mqdefault', 'default']
        if self.get_setting("enable_quality_fallback", True):
            if quality in qualities:
                start_index = qualities.index(quality)
                qualities = qualities[start_index:] + qualities[:start_index]
        else:
            qualities = [quality]
        bases = ["https://img.youtube.com", "https://i.ytimg.com"]
        for q in qualities:
            for base in bases:
                try:
                    thumb_url = f"{base}/vi/{video_id}/{q}.jpg"
                    response = requests.get(thumb_url, timeout=10)
                    if response.status_code == 200 and self._is_high_quality_thumbnail(response.content):
                        return response.content
                except Exception as e:
                    continue
        return None

    def _is_high_quality_thumbnail(self, response_content):
        try:
            if not response_content or len(response_content) < 8000:
                return False
            if not (b'JFIF' in response_content[:64] or b'\xff\xd8\xff' in response_content[:10]):
                return False
            img = Image.open(BytesIO(response_content))
            w, h = img.size
            if w >= 640 and h >= 360:
                return True
            return w >= 480 and h >= 270
        except Exception:
            return False

    def _get_soundcloud_thumbnail_cached(self, track_url):
        if not self.get_setting("enable_soundcloud_thumbnail_cache", False):
            return self._get_soundcloud_thumbnail_direct(track_url)
        cache_key = f"sc_thumb_{hash(track_url)}"
        with self._cache_lock:
            if hasattr(self, '_soundcloud_thumbnail_cache') and cache_key in self._soundcloud_thumbnail_cache:
                cached_data = self._soundcloud_thumbnail_cache[cache_key]
                if time.time() - cached_data['timestamp'] < self._cache_ttl:
                    return cached_data['data']
                else:
                    del self._soundcloud_thumbnail_cache[cache_key]
        if not hasattr(self, '_soundcloud_thumbnail_cache'):
            self._soundcloud_thumbnail_cache = {}
        thumbnail_data = self._get_soundcloud_thumbnail_direct(track_url)
        if thumbnail_data:
            with self._cache_lock:
                self._soundcloud_thumbnail_cache[cache_key] = {
                    'data': thumbnail_data,
                    'timestamp': time.time()
                }
                if len(self._soundcloud_thumbnail_cache) > 30:
                    oldest_key = min(self._soundcloud_thumbnail_cache.keys(),
                                    key=lambda k: self._soundcloud_thumbnail_cache[k]['timestamp'])
                    del self._soundcloud_thumbnail_cache[oldest_key]
        return thumbnail_data

    def _get_soundcloud_thumbnail_direct(self, track_url):
        try:
            response = requests.get(track_url, timeout=10)
            if response.status_code == 200:
                content = response.text
                thumbnail_match = re.search(r'"artwork_url":"([^"]+)"', content)
                if thumbnail_match:
                    thumbnail_url = thumbnail_match.group(1).replace('\\/', '/')
                    thumbnail_url = thumbnail_url.replace('large.jpg', 't500x500.jpg')
                    thumb_response = requests.get(thumbnail_url, timeout=10)
                    if thumb_response.status_code == 200:
                        return thumb_response.content
        except Exception as e:
            pass
        return None

    def _get_valid_thumbnail_url_cached(self, url):
        if not self.get_setting("enable_url_cache", True):
            return self._validate_thumbnail_url_direct(url)
        cache_key = f"url_valid_{hash(url)}"
        with self._cache_lock:
            if hasattr(self, '_url_validation_cache') and cache_key in self._url_validation_cache:
                cached_data = self._url_validation_cache[cache_key]
                if time.time() - cached_data['timestamp'] < (self._cache_ttl * 2):
                    return cached_data['data']
                else:
                    del self._url_validation_cache[cache_key]
        if not hasattr(self, '_url_validation_cache'):
            self._url_validation_cache = {}
        is_valid = self._validate_thumbnail_url_direct(url)
        with self._cache_lock:
            self._url_validation_cache[cache_key] = {
                'data': is_valid,
                'timestamp': time.time()
            }
            if len(self._url_validation_cache) > 100:
                oldest_key = min(self._url_validation_cache.keys(),
                                key=lambda k: self._url_validation_cache[k]['timestamp'])
                del self._url_validation_cache[oldest_key]
        return is_valid

    def _validate_thumbnail_url_direct(self, url):
        try:
            response = requests.head(url, timeout=5)
            return response.status_code == 200 and 'image' in response.headers.get('content-type', '')
        except Exception:
            return False

