    def _normalize_lastfm_track_title(self, track):
        try:
            raw_title = str(track.get('name', '') or '').strip()
            low = raw_title.lower()
            bad_titles = {
                "neste vídeo", "este vídeo", "this video", "video", "vídeo", "watch", "assistir"
            }
            if low in bad_titles or low.startswith("neste vídeo") or low.startswith("this video"):
                url = str(track.get('url', '') or '').strip()
                if '/_/' in url:
                    try:
                        slug = url.split('/_/')[-1].strip('/').strip()
                        decoded = unquote(slug).replace('+', ' ').strip()
                        if decoded:
                            return decoded
                    except Exception:
                        pass
                album = track.get('album', {})
                album_name = album.get('#text', '') if isinstance(album, dict) else str(album or '')
                album_name = str(album_name).strip()
                if album_name and album_name.lower() not in bad_titles:
                    return album_name
            return raw_title
        except Exception:
            return str(track.get('name', '') or '').strip()

    def _handle_fm_only_lastfm(self, account, params):
        self._last_overlay_trigger_command = ".fm"
        try:
            user = self.get_setting("lastfm_user", self.get_setting("lastfm_username", ""))
            api_key = self.get_setting("lastfm_api_key", "")
            if not user or not api_key:
                BulletinHelper.show_info("Last.fm credentials not configured. Use .help for setup instructions.")
                return False
            snapshot = self._get_now_playing_snapshot(preferred_source="lastfm", allow_cached=True)
            if snapshot and snapshot.get("track"):
                track_obj = snapshot.get("track")
                try:
                    if not track_obj.get("external_urls", {}).get("spotify"):
                        title = track_obj.get("name", "")
                        artist_name = ", ".join([a.get("name", "") for a in track_obj.get("artists", [])])
                        spotify_url = self._search_spotify_url(title, artist_name)
                        if spotify_url:
                            if "external_urls" not in track_obj or not isinstance(track_obj.get("external_urls"), dict):
                                track_obj["external_urls"] = {}
                            track_obj["external_urls"]["spotify"] = spotify_url
                except Exception as e:
                    pass
                if self._try_send_precard(params, "lastfm", force_spotify=False):
                    return True
                self._generate_card(track_obj, params, 0, force_spotify=False, etg_cover_image=None, is_fm_command=True)
                return True
            else:
                BulletinHelper.show_info("No track currently playing on Last.fm")
                return True
        except Exception as e:
            BulletinHelper.show_info(f"Error: {e}")
        finally:
            if bool(self.get_setting("enable_quick_dismiss", True)):
                run_on_ui_thread(self._dismiss_loading_dialog)

    def _handle_stats_only(self, account, params):
        self._last_overlay_trigger_command = ".stats"
