    def _parse_hex_color(self, value, default=(255, 255, 255)):
        try:
            if not value:
                return default
            v = str(value).strip().lstrip("#")
            if len(v) == 8:
                v = v[2:]
            if len(v) != 6:
                return default
            r = int(v[0:2], 16)
            g = int(v[2:4], 16)
            b = int(v[4:6], 16)
            return (r, g, b)
        except Exception:
            return default

