    def _ensure_font_picker_hook(self):
        if getattr(self, "_font_picker_hook", None):
            return
        try:
            hooks = []
            target_classes = [
                "android.app.Activity",
                "com.exteragram.messenger.plugins.ui.PluginSettingsActivity",
            ]
            hook_impl = NowfyFontPickerHook(self)
            for cls_name in target_classes:
                try:
                    cls = JClass.forName(cls_name)
                    if not cls:
                        continue
                    m = _find_method_exact(cls, "onActivityResult", Integer.TYPE, Integer.TYPE, Intent)
                    if not m:
                        continue
                    h = self.hook_method(m, hook_impl)
                    if h:
                        hooks.append(h)
                        self._fonts_trace(f"hooked onActivityResult on {cls_name}")
                except Exception as e:
                    self._fonts_trace(f"hook install failed on {cls_name}: {e}")
            if hooks:
                self._font_picker_hook = hooks[0]
                self._font_picker_hooks = hooks
            else:
                self._fonts_trace("no onActivityResult hook installed")
        except Exception:
            pass

    def _open_font_upload(self):
        try:
            now_ts = time.time()
            if bool(getattr(self, "_font_picker_active", False)):
                started_at = float(getattr(self, "_font_picker_started_at", 0.0) or 0.0)
                if started_at > 0 and (now_ts - started_at) < 20.0:
                    self._fonts_trace("picker already active")
                    return
                self._fonts_trace("stale picker flag detected, resetting")
                self._font_picker_active = False
            fragment = get_last_fragment()
            if not fragment:
                self._fonts_trace("open upload: fragment not found")
                return
            activity = fragment.getParentActivity()
            if not activity:
                self._fonts_trace("open upload: activity not found")
                return
            self._font_picker_request = int(getattr(self, "_font_picker_request", 10901))
            self._font_picker_active = True
            self._font_picker_started_at = now_ts
            self._ensure_font_picker_hook()
            intent = Intent(Intent.ACTION_OPEN_DOCUMENT)
            intent.addCategory(Intent.CATEGORY_OPENABLE)
            intent.setType("*/*")
            try:
                intent.putExtra(Intent.EXTRA_MIME_TYPES, [
                    "font/ttf", "font/otf", "application/x-font-ttf", "application/x-font-otf", "application/octet-stream"
                ])
            except Exception:
                pass
            try:
                intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            except Exception:
                pass
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(
                    tr("core_opening_font_upload") if tr("core_opening_font_upload") != "core_opening_font_upload" else "Opening font picker..."
                ))
            except Exception:
                pass
            started = False
            try:
                fragment.startActivityForResult(intent, self._font_picker_request)
                started = True
                self._fonts_trace("picker started via fragment.startActivityForResult")
            except Exception as e:
                self._fonts_trace(f"fragment.startActivityForResult failed: {e}")
            if not started:
                activity.startActivityForResult(intent, self._font_picker_request)
                self._fonts_trace("picker started via activity.startActivityForResult")
        except Exception as e:
            self._fonts_trace(f"picker start failed: {e}")
            self._font_picker_active = False
            self._font_picker_started_at = 0.0
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(tr("nowfy_font_upload_error")))
            except Exception:
                pass

    def _open_font_manager(self):
        try:
            fonts = self._list_custom_fonts()
            font_labels = self._list_custom_fonts_display()
            if not fonts:
                try:
                    BulletinHelper.show_info(tr("nowfy_font_manage_empty"))
                except Exception:
                    pass
                return
            fragment = get_last_fragment()
            if not fragment:
                return
            activity = fragment.getParentActivity()
            if not activity:
                return
            try:
                from android.widget import CheckBox
                from android.content.res import ColorStateList
                from android.app import AlertDialog
                from android.widget import EditText
            except Exception:
                CheckBox = None
            layout = LinearLayout(activity)
            layout.setOrientation(1)
            layout.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(8), AndroidUtilities.dp(16), AndroidUtilities.dp(8))
            checkboxes = []
            for f, label in zip(fonts, font_labels):
                if CheckBox:
                    cb = CheckBox(activity)
                    cb.setText(label)
                    try:
                        cb.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                    except Exception:
                        pass
                    try:
                        cb.setButtonTintList(ColorStateList.valueOf(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText)))
                    except Exception:
                        pass
                    layout.addView(cb)
                    checkboxes.append(cb)
            builder = AlertDialogBuilder(activity)
            builder.set_title(tr("nowfy_font_manage_title"))
            builder.set_view(layout)
            dialog = None
            def _remove_selected():
                try:
                    selected = []
                    for cb, name in zip(checkboxes, fonts):
                        if cb.isChecked():
                            selected.append(name)
                    if not selected:
                        try:
                            BulletinHelper.show_info(tr("nowfy_font_manage_none"))
                        except Exception:
                            pass
                        return
                    fonts_dir = self._get_custom_fonts_path()
                    removed = 0
                    for name in selected:
                        try:
                            path = os.path.join(fonts_dir, name)
                            if os.path.exists(path):
                                os.remove(path)
                                removed += 1
                        except Exception:
                            pass
                    try:
                        if removed > 0:
                            BulletinHelper.show_success(tr("nowfy_font_manage_removed").format(count=removed))
                        else:
                            BulletinHelper.show_info(tr("nowfy_font_manage_none"))
                    except Exception:
                        pass
                    try:
                        dialog.dismiss()
                    except Exception:
                        pass
                except Exception:
                    pass
            def _rename_selected():
                try:
                    selected = []
                    for cb, name in zip(checkboxes, fonts):
                        if cb.isChecked():
                            selected.append(name)
                    if len(selected) != 1:
                        try:
                            BulletinHelper.show_info(tr("nowfy_font_manage_rename_one"))
                        except Exception:
                            pass
                        return
                    old_name = selected[0]
                    base_name, ext = os.path.splitext(old_name)
                    edit = EditText(activity)
                    try:
                        edit.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                    except Exception:
                        try:
                            edit.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                        except Exception:
                            pass
                    try:
                        edit.setHintTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteHintText))
                    except Exception:
                        pass
                    try:
                        edit.setText(base_name)
                    except Exception:
                        pass
                    rename_builder = AlertDialogBuilder(activity)
                    rename_builder.set_title(tr("nowfy_font_manage_rename_title"))
                    rename_builder.set_view(edit)
                    def _confirm_rename(b=None, w=None):
                        try:
                            new_base = str(edit.getText()) if edit else ""
                            new_base = new_base.strip()
                            if not new_base:
                                BulletinHelper.show_info(tr("nowfy_font_manage_rename_invalid"))
                                return
                            new_name = f"{new_base}{ext}"
                            if new_name == old_name:
                                BulletinHelper.show_info(tr("nowfy_font_manage_rename_same"))
                                return
                            fonts_dir = self._get_custom_fonts_path()
                            old_path = os.path.join(fonts_dir, old_name)
                            new_path = os.path.join(fonts_dir, new_name)
                            if os.path.exists(new_path):
                                BulletinHelper.show_info(tr("nowfy_font_manage_rename_exists"))
                                return
                            os.rename(old_path, new_path)
                            BulletinHelper.show_success(tr("nowfy_font_manage_rename_done"))
                            try:
                                dialog.dismiss()
                            except Exception:
                                pass
                        except Exception:
                            pass
                    rename_builder.set_positive_button(tr("nowfy_font_manage_rename_action"), _confirm_rename)
                    rename_builder.set_negative_button(tr("cancel"), None)
                    rename_builder.show()
                except Exception:
                    pass
            builder.set_positive_button(tr("nowfy_font_manage_remove"), lambda *args: _remove_selected())
            builder.set_neutral_button(tr("nowfy_font_manage_rename_action"), lambda *args: _rename_selected())
            builder.set_negative_button(tr("cancel"), None)
            dialog = builder.show()
            try:
                if dialog and AlertDialog:
                    rename_btn = dialog.getButton(AlertDialog.BUTTON_NEUTRAL)
                    if rename_btn:
                        rename_btn.setVisibility(8)
                        def _update_rename_btn():
                            try:
                                count = 0
                                for cb in checkboxes:
                                    if cb.isChecked():
                                        count += 1
                                rename_btn.setVisibility(0 if count == 1 else 8)
                            except Exception:
                                pass
                        for cb in checkboxes:
                            try:
                                cb.setOnCheckedChangeListener(lambda v, is_checked: _update_rename_btn())
                            except Exception:
                                pass
                        _update_rename_btn()
            except Exception:
                pass
        except Exception:
            pass

    def _handle_font_picker_result(self, res_code, data):
        try:
            self._font_picker_active = False
            self._font_picker_started_at = 0.0
            self._fonts_trace(f"picker result: code={res_code} hasData={bool(data and data.getData())}")
            if res_code == Activity.RESULT_OK and data and data.getData():
                run_on_queue(lambda: self._handle_font_uri(data.getData()))
            else:
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(
                        tr("core_font_selection_canceled") if tr("core_font_selection_canceled") != "core_font_selection_canceled" else "Font selection canceled"
                    ))
                except Exception:
                    pass
        except Exception:
            self._font_picker_active = False
            self._font_picker_started_at = 0.0

    def _handle_font_uri(self, uri: Uri):
        istream = None
        ostream = None
        try:
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            istream = resolver.openInputStream(uri)
            if not istream:
                raise IOError("stream")
            name = None
            try:
                cursor = resolver.query(uri, [OpenableColumns.DISPLAY_NAME], None, None, None)
                if cursor:
                    try:
                        if cursor.moveToFirst():
                            name = cursor.getString(0)
                    finally:
                        cursor.close()
            except Exception:
                name = None
            if not name:
                try:
                    name = uri.getLastPathSegment()
                except Exception:
                    name = None
            name = str(name or "").strip()
            if "/" in name:
                name = name.split("/")[-1]
            if ":" in name:
                name = name.split(":")[-1]
            mime = None
            try:
                mime = resolver.getType(uri)
            except Exception:
                mime = None
            if not name:
                name = f"nowfy_font_{int(time.time())}"
            lower_name = name.lower()
            if "." not in name:
                if mime and "otf" in str(mime).lower():
                    name = f"{name}.otf"
                else:
                    name = f"{name}.ttf"
                lower_name = name.lower()
            if not lower_name.endswith((".ttf", ".otf")):
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(tr("nowfy_font_upload_invalid")))
                except Exception:
                    pass
                self._fonts_trace(f"invalid extension: name={name} mime={mime}")
                return
            fonts_dir = self._get_custom_fonts_path()
            try:
                if not os.path.exists(fonts_dir):
                    os.makedirs(fonts_dir)
            except Exception:
                pass
            dest_path = os.path.join(fonts_dir, name)
            self._fonts_trace(f"saving '{name}' to '{dest_path}'")
            ostream = FileOutputStream(dest_path)
            buffer = jarray(jbyte)(8192)
            total = 0
            bytes_read = istream.read(buffer)
            while bytes_read != -1:
                ostream.write(buffer, 0, bytes_read)
                total += int(bytes_read)
                bytes_read = istream.read(buffer)
            ostream.flush()
            self._fonts_trace(f"upload completed bytes={total}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_success(tr("nowfy_font_upload_done")))
            except Exception:
                pass
            try:
                self.reload_settings()
            except Exception:
                pass
        except Exception as e:
            self._fonts_trace(f"upload failed: {e}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(f"{tr('nowfy_font_upload_error')}: {str(e)}"))
            except Exception:
                pass
        finally:
            try:
                if istream:
                    istream.close()
            except Exception:
                pass
            try:
                if ostream:
                    ostream.close()
            except Exception:
                pass
            try:
                self._font_picker_active = False
            except Exception:
                pass
            try:
                self._font_picker_started_at = 0.0
            except Exception:
                pass

