    def _handle_backup_uri(self, uri: Uri):
        istream = None
        ostream = None
        try:
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            istream = resolver.openInputStream(uri)
            if not istream:
                raise IOError("stream")
            name = None
            try:
                cursor = resolver.query(uri, [OpenableColumns.DISPLAY_NAME], None, None, None)
                if cursor:
                    try:
                        if cursor.moveToFirst():
                            name = cursor.getString(0)
                    finally:
                        cursor.close()
            except Exception:
                name = None
            if not name:
                try:
                    name = uri.getLastPathSegment()
                except Exception:
                    name = None
            name = str(name or "").strip()
            if "/" in name:
                name = name.split("/")[-1]
            if ":" in name:
                name = name.split(":")[-1]
            lower_name = name.lower()
            if not lower_name.endswith(".nowfy"):
                name = f"{name}.nowfy" if name else f"backup-{self._get_backup_filename_stamp()}.nowfy"
                lower_name = name.lower()
            backup_dir = BackupManager(self).backup_dir
            try:
                if not os.path.exists(backup_dir):
                    os.makedirs(backup_dir)
            except Exception:
                pass
            dest_path = os.path.join(backup_dir, name)
            if os.path.exists(dest_path):
                base, ext = os.path.splitext(name)
                idx = 1
                while os.path.exists(os.path.join(backup_dir, f"{base}-{idx}{ext}")):
                    idx += 1
                dest_path = os.path.join(backup_dir, f"{base}-{idx}{ext}")
            self._uploads_trace(f"backup saving to '{dest_path}'")
            ostream = FileOutputStream(dest_path)
            buffer = jarray(jbyte)(8192)
            total = 0
            bytes_read = istream.read(buffer)
            while bytes_read != -1:
                ostream.write(buffer, 0, bytes_read)
                total += int(bytes_read)
                bytes_read = istream.read(buffer)
            ostream.flush()
            self._uploads_trace(f"backup upload completed bytes={total}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_success(tr("nowfy_backup_upload_done")))
            except Exception:
                pass
            try:
                self._uploads_trace(f"backup uploaded file='{os.path.basename(dest_path)}'")
            except Exception:
                pass
            try:
                uploaded_name = os.path.basename(dest_path)
                self._uploads_trace(f"backup import: validating '{uploaded_name}'")
                ok = False
                try:
                    with open(dest_path, "r", encoding="utf-8") as bf:
                        backup_data = json.load(bf)
                    if not isinstance(backup_data, dict):
                        raise ValueError("invalid backup payload")
                    target_name = str(backup_data.get("plugin_name", "") or "").strip().lower()
                    settings = backup_data.get("settings", {})
                    core_settings = backup_data.get("core_settings", {})
                    applied_main = 0
                    applied_core = 0
                    if target_name == "nowfy" and isinstance(settings, dict) and settings:
                        target = None
                        try:
                            controller = PluginsController.getInstance()
                            if controller and hasattr(controller, "plugins"):
                                target = controller.plugins.get("nowfy")
                        except Exception as e_get:
                            self._uploads_trace(f"backup import: target resolve failed: {e_get}")
                        if target and hasattr(target, "set_setting"):
                            for k, v in settings.items():
                                try:
                                    if v is None:
                                        continue
                                    target.set_setting(str(k), v)
                                    applied_main += 1
                                except Exception:
                                    pass
                            self._uploads_trace(f"backup import: applied nowfy settings={applied_main}")
                        else:
                            self._uploads_trace("backup import: nowfy target unavailable")
                    if isinstance(core_settings, dict) and core_settings:
                        try:
                            for ck, cv in core_settings.items():
                                try:
                                    self.set_setting(str(ck), cv)
                                    applied_core += 1
                                except Exception:
                                    pass
                            self._uploads_trace(f"backup import: applied core settings={applied_core}")
                        except Exception as e_core:
                            self._uploads_trace(f"backup import: core apply failed: {e_core}")
                    if applied_main == 0 and applied_core == 0:
                        try:
                            bm = BackupManager(self)
                            if bm.validate_backup_data(backup_data):
                                bm.apply_backup_settings(backup_data)
                                applied_core = 1
                                self._uploads_trace("backup import: fallback core apply executed")
                        except Exception as e_fallback:
                            self._uploads_trace(f"backup import: fallback failed: {e_fallback}")
                    ok = (applied_main > 0) or (applied_core > 0)
                except Exception as e2:
                    self._uploads_trace(f"backup import json/apply failed: {e2}")
                    ok = False
                if ok:
                    self._uploads_trace("backup import applied successfully")
                    try:
                        run_on_ui_thread(lambda: BulletinHelper.show_success(tr("backup_imported_success")))
                    except Exception:
                        pass
                else:
                    self._uploads_trace("backup import invalid structure")
                    try:
                        run_on_ui_thread(lambda: BulletinHelper.show_info(tr("backup_invalid_file")))
                    except Exception:
                        pass
            except Exception as e3:
                self._uploads_trace(f"backup import post-upload failed: {e3}")
            try:
                self.reload_settings()
            except Exception:
                pass
        except Exception as e:
            self._uploads_trace(f"backup upload failed: {e}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(f"{tr('nowfy_backup_upload_error')}: {str(e)}"))
            except Exception:
                pass
        finally:
            try:
                if istream:
                    istream.close()
            except Exception:
                pass
            try:
                if ostream:
                    ostream.close()
            except Exception:
                pass
            try:
                self._backup_picker_active = False
                self._backup_picker_started_at = 0.0
            except Exception:
                pass

    def _open_custom_cover_upload(self):
        try:
            now_ts = time.time()
            if bool(getattr(self, "_custom_cover_picker_active", False)):
                try:
                    started_at = float(getattr(self, "_custom_cover_picker_started_at", 0.0) or 0.0)
                except Exception:
                    started_at = 0.0
                if started_at > 0 and (now_ts - started_at) > 20:
                    self._uploads_trace("custom cover picker stale flag reset")
                    self._custom_cover_picker_active = False
                else:
                    self._uploads_trace("custom cover picker already active")
                    return
            fragment = get_last_fragment()
            activity = fragment.getParentActivity() if fragment and fragment.getParentActivity() else None
            if not activity:
                activity = getattr(self, "_extended_settings_activity", None)
            if not activity:
                self._uploads_trace("custom cover picker: activity not found")
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(
                        tr("core_image_picker_unavailable") if tr("core_image_picker_unavailable") != "core_image_picker_unavailable" else "Unable to open image picker"
                    ))
                except Exception:
                    pass
                return
            self._custom_cover_picker_request = int(getattr(self, "_custom_cover_picker_request", 10903))
            self._custom_cover_picker_active = True
            self._custom_cover_picker_started_at = now_ts
            self._ensure_font_picker_hook()
            intent = Intent(Intent.ACTION_OPEN_DOCUMENT)
            intent.addCategory(Intent.CATEGORY_OPENABLE)
            intent.setType("image/*")
            try:
                intent.putExtra(Intent.EXTRA_MIME_TYPES, [
                    "image/jpeg", "image/jpg", "image/png", "image/gif"
                ])
            except Exception:
                pass
            try:
                intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            except Exception:
                pass
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(
                    tr("core_opening_custom_cover_upload") if tr("core_opening_custom_cover_upload") != "core_opening_custom_cover_upload" else "Opening image picker..."
                ))
            except Exception:
                pass
            started = False
            if fragment:
                try:
                    fragment.startActivityForResult(intent, self._custom_cover_picker_request)
                    started = True
                    self._uploads_trace("custom cover picker started via fragment")
                except Exception as e:
                    self._uploads_trace(f"custom cover picker fragment start failed: {e}")
            if not started:
                activity.startActivityForResult(intent, self._custom_cover_picker_request)
                self._uploads_trace("custom cover picker started via activity")
        except Exception as e:
            self._uploads_trace(f"custom cover picker start failed: {e}")
            self._custom_cover_picker_active = False
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(
                    tr("core_image_picker_unavailable") if tr("core_image_picker_unavailable") != "core_image_picker_unavailable" else "Unable to open image picker"
                ))
            except Exception:
                pass

    def _handle_custom_cover_picker_result(self, res_code, data):
        try:
            self._custom_cover_picker_active = False
            self._uploads_trace(f"custom cover picker result: code={res_code} hasData={bool(data and data.getData())}")
            if res_code == Activity.RESULT_OK and data and data.getData():
                uri = data.getData()
                if (not self._is_gif_uri(uri)) and self._start_custom_cover_crop(uri):
                    self._uploads_trace("custom cover crop flow started")
                    return
                run_on_queue(lambda: self._handle_custom_cover_uri(uri))
            else:
                self._custom_cover_picker_active = False
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(
                        tr("core_image_selection_canceled") if tr("core_image_selection_canceled") != "core_image_selection_canceled" else "Image selection canceled"
                    ))
                except Exception:
                    pass
        except Exception:
            self._custom_cover_picker_active = False
        finally:
            try:
                self._custom_cover_picker_started_at = 0.0
            except Exception:
                pass

    def _get_custom_cover_dirs(self):
        try:
            dirs = []
            try:
                pkg = str(ApplicationLoader.applicationContext.getPackageName() or "").lower()
            except Exception:
                pkg = ""
            ext_base = "/storage/emulated/0/Android/media/com.exteragram.messenger/cover"
            ayu_base = "/storage/emulated/0/Android/media/com.radolyn.ayugram/cover"
            if "ayugram" in pkg:
                if os.path.isdir(ayu_base):
                    dirs.append(ayu_base)
                if os.path.isdir(ext_base):
                    dirs.append(ext_base)
            else:
                if os.path.isdir(ext_base):
                    dirs.append(ext_base)
                if os.path.isdir(ayu_base):
                    dirs.append(ayu_base)
            if not dirs:
                dirs = [ext_base, ayu_base]
            return dirs
        except Exception:
            return ["/storage/emulated/0/Android/media/com.exteragram.messenger/fonts", "/storage/emulated/0/Android/media/com.radolyn.ayugram/fonts"]

    def _get_custom_cover_primary_dir(self):
        try:
            dirs = self._get_custom_cover_dirs()
            if dirs and len(dirs) > 0:
                d = str(dirs[0])
                if d:
                    try:
                        if not os.path.exists(d):
                            os.makedirs(d)
                    except Exception:
                        pass
                    return d
        except Exception:
            pass
        fallback = "/storage/emulated/0/Android/media/com.exteragram.messenger/cover"
        try:
            if not os.path.exists(fallback):
                os.makedirs(fallback)
        except Exception:
            pass
        return fallback

    def _cleanup_custom_cover_legacy_files(self):
        try:
            cleanup_dirs = []
            try:
                cleanup_dirs.extend(self._get_custom_cover_dirs())
            except Exception:
                pass
            cleanup_dirs.append("/storage/emulated/0/Download")
            for d in cleanup_dirs:
                try:
                    for name in (
                        "custom_cover_nowfy.png",
                        "custom_cover_nowfy.jpg",
                        "custom_cover_nowfy.jpeg",
                        "custom_cover_nowfy.gif",
                        "custom_cover_nowfy_crop.jpg",
                        "custom_cover_crop_tmp.jpg",
                    ):
                        p = os.path.join(d, name)
                        if os.path.exists(p):
                            try:
                                os.remove(p)
                            except Exception:
                                pass
                except Exception:
                    pass
        except Exception:
            pass

    def _get_custom_cover_path(self):
        try:
            for d in self._get_custom_cover_dirs():
                base = os.path.join(d, "custom_cover_nowfy")
                ext = str(self.get_setting("custom_cover_ext", "") or "").lower().strip(".")
                if ext:
                    path = f"{base}.{ext}"
                    if os.path.exists(path):
                        return path
                for ext in ("png", "jpg", "jpeg", "gif"):
                    path = f"{base}.{ext}"
                    if os.path.exists(path):
                        return path
        except Exception:
            pass
        return None

    def _has_custom_cover(self):
        try:
            return bool(self._get_custom_cover_path())
        except Exception:
            return False

    def _get_custom_cover_label(self):
        try:
            name = "User"
            try:
                account = getattr(UserConfig, 'selectedAccount', 0)
                mc = MessagesController.getInstance(account)
                uc = UserConfig.getInstance(account)
                if mc and uc:
                    user = mc.getUser(uc.getClientUserId())
                    if user and user.first_name:
                        name = user.first_name
            except Exception:
                pass
            if name:
                return f"{name}'s Cover"
            return "Custom Cover"
        except Exception:
            return "Custom Cover"

    def _apply_header_cover_local_file(self, bg_cover, path):
        try:
            if not bg_cover or not path or not os.path.exists(path):
                return
            try:
                gif_view = getattr(self, "_header_cover_gif_view", None)
                if gif_view:
                    def _hide_gif():
                        try:
                            gif_view.setImageDrawable(None)
                        except Exception:
                            pass
                        try:
                            gif_view.setVisibility(View.GONE)
                        except Exception:
                            pass
                        try:
                            self._set_header_cover_shadow_visible(False)
                        except Exception:
                            pass
                    run_on_ui_thread(_hide_gif)
            except Exception:
                pass
            try:
                ext = str(path).rsplit(".", 1)[-1].lower() if "." in str(path) else ""
            except Exception:
                ext = ""
            if ext == "gif":
                if self._apply_header_cover_local_gif(bg_cover, path):
                    return
            try:
                if hasattr(bg_cover, "setAspectFit"):
                    bg_cover.setAspectFit(False)
            except Exception:
                pass
            try:
                ir = bg_cover.getImageReceiver() if hasattr(bg_cover, "getImageReceiver") else None
                if ir and hasattr(ir, "setAspectFit"):
                    ir.setAspectFit(False)
            except Exception:
                pass
            data = None
            try:
                with open(path, "rb") as f:
                    data = f.read()
            except Exception:
                data = None
            if not data:
                return
            processed = self._process_header_cover_bytes(path, data)
            bmp = BitmapFactory.decodeByteArray(processed, 0, len(processed))
            if not bmp:
                return
            def _apply():
                try:
                    try:
                        self._set_header_cover_shadow_visible(False)
                    except Exception:
                        pass
                    bg_cover.setImageBitmap(bmp)
                    bg_cover.setVisibility(View.VISIBLE)
                    try:
                        bg_cover.setAlpha(0.0)
                        bg_cover.animate().alpha(0.92).setDuration(220).start()
                    except Exception:
                        try:
                            bg_cover.setAlpha(0.92)
                        except Exception:
                            pass
                    bg_cover.invalidate()
                    try:
                        self._set_header_cover_text_mode(True)
                    except Exception:
                        pass
                except Exception:
                    pass
            run_on_ui_thread(_apply)
        except Exception:
            pass

    def _prepare_blurred_gif(self, path):
        try:
            if not path or not os.path.exists(path):
                return None
            try:
                mtime = int(os.path.getmtime(path))
            except Exception:
                mtime = 0
            cache_dir = self._di_cache_dir() or ApplicationLoader.getFilesDirFixed()
            cache_dir = str(cache_dir)
            try:
                if not os.path.exists(cache_dir):
                    os.makedirs(cache_dir)
            except Exception:
                pass
            key_src = f"{path}|{mtime}|gif_blur_v1"
            key = hashlib.md5(key_src.encode("utf-8")).hexdigest()[:14]
            out_path = os.path.join(cache_dir, f"nowfy_header_gif_blur_{key}.gif")
            try:
                if os.path.exists(out_path) and os.path.getsize(out_path) > 128:
                    return out_path
            except Exception:
                pass
            img = Image.open(path)
            frames = []
            durations = []
            for frame in ImageSequence.Iterator(img):
                fr = frame.convert("RGBA").filter(ImageFilter.GaussianBlur(8))
                frames.append(fr)
                try:
                    durations.append(int(frame.info.get("duration", img.info.get("duration", 80)) or 80))
                except Exception:
                    durations.append(80)
            if not frames:
                return None
            frames[0].save(
                out_path,
                save_all=True,
                append_images=frames[1:],
                loop=0,
                duration=durations,
                optimize=False,
                disposal=2
            )
            return out_path if os.path.exists(out_path) else None
        except Exception:
            return None

    def _apply_header_cover_local_gif(self, bg_cover, path):
        try:
            if not bg_cover or not path or not os.path.exists(path):
                return False
            if Build.VERSION.SDK_INT < 28:
                return False
            use_blur = True
            try:
                use_blur = (int(self.get_setting("header_cover_blur", 1)) == 0)
            except Exception:
                use_blur = True
            src_path = path
            if use_blur:
                try:
                    p = self._prepare_blurred_gif(path)
                    if p:
                        src_path = p
                except Exception:
                    pass
            try:
                from android.graphics import ImageDecoder
                from android.graphics.drawable import AnimatedImageDrawable
            except Exception:
                return False
            src = ImageDecoder.createSource(File(src_path))
            drawable = ImageDecoder.decodeDrawable(src)
            if not drawable:
                return False
            def _apply():
                try:
                    target = getattr(self, "_header_cover_gif_view", None)
                    if target is None:
                        target = bg_cover
                    try:
                        target.setImageDrawable(drawable)
                    except Exception:
                        return
                    try:
                        if isinstance(drawable, AnimatedImageDrawable):
                            try:
                                drawable.setRepeatCount(-1)
                            except Exception:
                                pass
                            try:
                                drawable.start()
                            except Exception:
                                pass
                    except Exception:
                        pass
                    try:
                        bg_cover.setImageBitmap(None)
                    except Exception:
                        pass
                    try:
                        bg_cover.setImageDrawable(None)
                    except Exception:
                        pass
                    try:
                        bg_cover.setVisibility(View.GONE)
                    except Exception:
                        pass
                    try:
                        target.setVisibility(View.VISIBLE)
                    except Exception:
                        pass
                    try:
                        self._set_header_cover_shadow_visible(True)
                    except Exception:
                        pass
                    try:
                        target.setAlpha(0.92)
                    except Exception:
                        pass
                    try:
                        target.invalidate()
                    except Exception:
                        pass
                    try:
                        self._set_header_cover_text_mode(True)
                    except Exception:
                        pass
                except Exception:
                    pass
            run_on_ui_thread(_apply)
            return True
        except Exception:
            return False

    def _read_uri_bytes(self, uri):
        istream = None
        try:
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            istream = resolver.openInputStream(uri)
            if not istream:
                return None
            from io import BytesIO as _BytesIO
            buf = _BytesIO()
            buffer = jarray(jbyte)(8192)
            bytes_read = istream.read(buffer)
            while bytes_read != -1:
                buf.write(bytes(bytearray(buffer[:bytes_read])))
                bytes_read = istream.read(buffer)
            return buf.getvalue()
        except Exception:
            return None
        finally:
            try:
                if istream:
                    istream.close()
            except Exception:
                pass

    def _try_delete_uri(self, uri):
        try:
            if not uri:
                return
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            try:
                resolver.delete(uri, None, None)
            except Exception:
                pass
        except Exception:
            pass

    def _save_custom_cover_bytes(self, data, ext):
        try:
            if not data or ext not in ("jpg", "jpeg", "png", "gif"):
                return False
            try:
                self._cleanup_custom_cover_legacy_files()
            except Exception:
                pass
            d = self._get_custom_cover_primary_dir()
            wrote = False
            base = os.path.join(d, "custom_cover_nowfy")
            for old_ext in ("png", "jpg", "jpeg", "gif"):
                old_path = f"{base}.{old_ext}"
                if os.path.exists(old_path) and old_ext != ext:
                    try:
                        os.remove(old_path)
                    except Exception:
                        pass
            dest_path = f"{base}.{ext}"
            try:
                with open(dest_path, "wb") as f:
                    f.write(data)
                wrote = True
            except Exception:
                wrote = False
            if not wrote:
                return False
            self.set_setting("custom_cover_ext", ext)
            self.set_setting("custom_cover_selection", 1)
            self.set_setting("custom_cover_unlocked", True)
            try:
                self.set_setting("custom_cover_force_nowfy", False)
            except Exception:
                pass
            try:
                self._header_cover_last_key = ""
                self._header_cover_last_url = ""
            except Exception:
                pass
            try:
                bg_cover = getattr(self, "_header_cover_view", None)
                if bg_cover:
                    path = self._get_custom_cover_path()
                    if path:
                        self._apply_header_cover_local_file(bg_cover, path)
            except Exception:
                pass
            return True
        except Exception:
            return False

    def _handle_custom_cover_uri(self, uri: Uri):
        istream = None
        try:
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            istream = resolver.openInputStream(uri)
            if not istream:
                raise IOError("stream")
            name = None
            mime = None
            try:
                mime = resolver.getType(uri)
            except Exception:
                mime = None
            try:
                cursor = resolver.query(uri, [OpenableColumns.DISPLAY_NAME], None, None, None)
                if cursor:
                    try:
                        if cursor.moveToFirst():
                            name = cursor.getString(0)
                    finally:
                        cursor.close()
            except Exception:
                name = None
            if not name:
                try:
                    name = uri.getLastPathSegment()
                except Exception:
                    name = None
            name = str(name or "").strip()
            if "/" in name:
                name = name.split("/")[-1]
            if ":" in name:
                name = name.split(":")[-1]
            ext = ""
            if "." in name:
                ext = name.rsplit(".", 1)[-1].lower()
            if ext not in ("jpg", "jpeg", "png", "gif"):
                if mime == "image/jpeg":
                    ext = "jpg"
                elif mime == "image/png":
                    ext = "png"
                elif mime == "image/gif":
                    ext = "gif"
            if ext not in ("jpg", "jpeg", "png", "gif"):
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(tr("nowfy_custom_cover_invalid")))
                except Exception:
                    pass
                self._custom_cover_picker_active = False
                self._uploads_trace(f"custom cover invalid extension name={name} mime={mime}")
                return
            data = self._read_uri_bytes(uri)
            self._uploads_trace(f"custom cover bytes read={len(data) if data else 0} ext={ext}")
            if data and self._save_custom_cover_bytes(data, ext):
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_success(tr("nowfy_custom_cover_uploaded")))
                except Exception:
                    pass
                self._uploads_trace("custom cover upload completed")
            else:
                try:
                    run_on_ui_thread(lambda: BulletinHelper.show_info(tr("nowfy_custom_cover_invalid")))
                except Exception:
                    pass
                self._uploads_trace("custom cover upload failed (save returned false)")
            try:
                self.reload_settings()
            except Exception:
                pass
        except Exception as e:
            self._uploads_trace(f"custom cover upload exception: {e}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info(tr("nowfy_custom_cover_invalid")))
            except Exception:
                pass
        finally:
            self._custom_cover_picker_active = False
            try:
                self._custom_cover_picker_started_at = 0.0
            except Exception:
                pass
            try:
                if istream:
                    istream.close()
            except Exception:
                pass

    def _start_custom_cover_crop(self, uri):
        try:
            if self._is_gif_uri(uri):
                self._uploads_trace("custom cover crop skipped (gif)")
                return False
            fragment = get_last_fragment()
            activity = fragment.getParentActivity() if fragment and fragment.getParentActivity() else None
            if not activity:
                self._uploads_trace("custom cover crop: activity not found")
                return False
            intent = Intent("com.android.camera.action.CROP")
            intent.setDataAndType(uri, "image/*")
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            try:
                intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            except Exception:
                pass
            intent.putExtra("crop", "true")
            intent.putExtra("scale", True)
            intent.putExtra("scaleUpIfNeeded", True)
            intent.putExtra("return-data", False)
            intent.putExtra("outputFormat", "JPEG")
            try:
                intent.putExtra("aspectX", 1)
                intent.putExtra("aspectY", 1)
                intent.putExtra("outputX", 1024)
                intent.putExtra("outputY", 1024)
            except Exception:
                pass
            try:
                cache_dir = self._get_custom_cover_primary_dir() or (self._di_cache_dir() or ApplicationLoader.getFilesDirFixed())
                cache_dir = str(cache_dir)
                if not os.path.exists(cache_dir):
                    os.makedirs(cache_dir)
                tmp_path = os.path.join(cache_dir, "custom_cover_crop_tmp.jpg")
                tmp_file = File(tmp_path)
                out_uri = Uri.fromFile(tmp_file)
                self._custom_cover_crop_path = tmp_path
                self._custom_cover_crop_uri = None
                intent.putExtra(MediaStore.EXTRA_OUTPUT, out_uri)
            except Exception:
                self._custom_cover_crop_path = None
            self._custom_cover_pending_uri = uri
            self._custom_cover_crop_request = int(getattr(self, "_custom_cover_crop_request", 10904))
            self._custom_cover_crop_active = True
            self._ensure_font_picker_hook()
            activity.startActivityForResult(intent, self._custom_cover_crop_request)
            self._uploads_trace("custom cover crop started")
            return True
        except Exception as e:
            self._uploads_trace(f"custom cover crop start failed: {e}")
            try:
                run_on_ui_thread(lambda: BulletinHelper.show_info("Crop unavailable, using original image"))
            except Exception:
                pass
            self._custom_cover_crop_active = False
            return False

    def _is_gif_uri(self, uri):
        try:
            if not uri:
                return False
            resolver = ApplicationLoader.applicationContext.getContentResolver()
            mime = ""
            try:
                mime = str(resolver.getType(uri) or "").lower()
            except Exception:
                mime = ""
            if "gif" in mime:
                return True
            name = ""
            try:
                cursor = resolver.query(uri, [OpenableColumns.DISPLAY_NAME], None, None, None)
                if cursor:
                    try:
                        if cursor.moveToFirst():
                            name = str(cursor.getString(0) or "")
                    finally:
                        cursor.close()
            except Exception:
                pass
            if not name:
                try:
                    name = str(uri.getLastPathSegment() or "")
                except Exception:
                    name = ""
            return name.lower().endswith(".gif")
        except Exception:
            return False

    def _handle_custom_cover_crop_result(self, res_code, data):
        try:
            if res_code == Activity.RESULT_OK:
                try:
                    if data and data.getData():
                        uri = data.getData()
                        data_bytes = self._read_uri_bytes(uri)
                        if data_bytes and self._save_custom_cover_bytes(data_bytes, "jpg"):
                            try:
                                BulletinHelper.show_success(tr("nowfy_custom_cover_uploaded"))
                            except Exception:
                                pass
                            try:
                                self.reload_settings()
                            except Exception:
                                pass
                            try:
                                self._try_delete_uri(uri)
                            except Exception:
                                pass
                            return
                except Exception:
                    pass
                try:
                    out_uri = getattr(self, "_custom_cover_crop_uri", None)
                    if out_uri:
                        data_bytes = self._read_uri_bytes(out_uri)
                        if data_bytes and self._save_custom_cover_bytes(data_bytes, "jpg"):
                            try:
                                BulletinHelper.show_success(tr("nowfy_custom_cover_uploaded"))
                            except Exception:
                                pass
                            try:
                                self.reload_settings()
                            except Exception:
                                pass
                            try:
                                self._try_delete_uri(out_uri)
                            except Exception:
                                pass
                            return
                except Exception:
                    pass
                path = getattr(self, "_custom_cover_crop_path", None)
                if path and os.path.exists(path):
                    try:
                        with open(path, "rb") as f:
                            data_bytes = f.read()
                        if data_bytes and self._save_custom_cover_bytes(data_bytes, "jpg"):
                            try:
                                BulletinHelper.show_success(tr("nowfy_custom_cover_uploaded"))
                            except Exception:
                                pass
                            try:
                                self.reload_settings()
                            except Exception:
                                pass
                            try:
                                os.remove(path)
                            except Exception:
                                pass
                            return
                    except Exception:
                        pass
            uri = getattr(self, "_custom_cover_pending_uri", None)
            if uri:
                run_on_queue(lambda: self._handle_custom_cover_uri(uri))
        except Exception:
            pass
        finally:
            self._custom_cover_crop_active = False
            try:
                self._custom_cover_crop_uri = None
            except Exception:
                pass

