    def _on_custom_cover_select(self, v):
        try:
            idx = int(v)
        except Exception:
            idx = 0
        if idx < 0 or idx > 1:
            idx = 0
        self.set_setting("custom_cover_selection", idx)
        try:
            self.set_setting("custom_cover_force_nowfy", bool(idx == 0))
        except Exception:
            pass
        try:
            self._header_cover_last_key = ""
            self._header_cover_last_url = ""
        except Exception:
            pass
        try:
            bg_cover = getattr(self, "_header_cover_view", None)
            if idx == 1:
                path = self._get_custom_cover_path()
                if path and bg_cover:
                    self._apply_header_cover_local_file(bg_cover, path)
            else:
                self._header_fallback_refresh = True
        except Exception:
            pass
        try:
            self.reload_settings()
        except Exception:
            pass

    def _on_custom_cover_toggle(self, v):
        try:
            enabled = int(v) == 1
        except Exception:
            enabled = False
        try:
            self.set_setting("custom_cover_unlocked", bool(enabled))
        except Exception:
            pass
        if not enabled:
            try:
                self.set_setting("custom_cover_selection", 0)
            except Exception:
                pass
            try:
                self.set_setting("custom_cover_force_nowfy", True)
            except Exception:
                pass
        else:
            try:
                self.set_setting("custom_cover_force_nowfy", False)
            except Exception:
                pass
        try:
            self._refresh_extended_subfragment_ui()
            self._refresh_extended_subfragment_ui(120)
        except Exception:
            try:
                self.reload_settings()
            except Exception:
                pass

    def _unlock_custom_cover(self):
        try:
            if bool(self.get_setting("custom_cover_unlocked", False)):
                return
            try:
                self.set_setting("custom_cover_unlocked", True, reload_settings=True)
            except Exception:
                self.set_setting("custom_cover_unlocked", True)
            try:
                if bool(self.get_setting("header_cover_enabled", True)):
                    self.set_setting("header_cover_enabled", False)
                    try:
                        self._stop_header_cover_worker()
                    except Exception:
                        pass
                    try:
                        self._apply_header_cover_settings_consistency()
                    except Exception:
                        pass
            except Exception:
                pass
            try:
                BulletinHelper.show_info(tr("nowfy_custom_cover_unlocked"))
            except Exception:
                pass
            self._refresh_extended_subfragment_ui()
            try:
                self._refresh_extended_subfragment_ui(120)
            except Exception:
                pass
        except Exception:
            pass

    def _refresh_extended_subfragment_ui(self, delay_ms=0):
        try:
            activity = getattr(self, "_extended_settings_activity", None)
            if not activity:
                return
            try:
                self._set_subfragment_callback(activity, self.create_extended_subfragment)
            except Exception:
                pass
            try:
                self.reload_settings()
            except Exception:
                pass
            list_view = get_private_field(activity, "listView")
            if list_view is not None and getattr(list_view, "adapter", None) is not None:
                def _do_refresh():
                    try:
                        list_view.adapter.update(False)
                    except Exception:
                        pass
                    try:
                        list_view.adapter.update(True)
                    except Exception:
                        pass
                run_on_ui_thread(_do_refresh, delay_ms)
        except Exception:
            pass

    def _reopen_extended_subfragment(self):
        try:
            fragment = get_last_fragment()
            controller = PluginsController.getInstance()
            plugin = controller.plugins.get(self.id) if controller else None
            if not plugin:
                return
            activity = PluginSettingsActivity(plugin)
            try:
                self._set_subfragment_callback(activity, self.create_extended_subfragment)
            except Exception:
                pass
            if fragment:
                fragment.presentFragment(activity)
        except Exception:
            pass
            try:
                self._backup_picker_active = False
            except Exception:
                pass

    def _get_backup_filename_stamp(self):
        try:
            from datetime import datetime as _dt
            return _dt.now().strftime("%d%m%Y-%H%M")
        except Exception:
            return str(int(time.time()))

    def _list_backup_files_local(self):
        try:
            backup_dir = BackupManager(self).backup_dir
            if not os.path.exists(backup_dir):
                return []
            files = [f for f in os.listdir(backup_dir) if f.lower().endswith(".nowfy")]
            files.sort(key=lambda x: os.path.getmtime(os.path.join(backup_dir, x)), reverse=True)
            return files
        except Exception:
            return []

    def _open_backup_manager(self):
        try:
            files = self._list_backup_files_local()
            if not files:
                try:
                    BulletinHelper.show_info(tr("backup_no_backups_found"))
                except Exception:
                    pass
                return
            fragment = get_last_fragment()
            if not fragment:
                return
            activity = fragment.getParentActivity()
            if not activity:
                return
            try:
                from android.widget import CheckBox
                from android.content.res import ColorStateList
                from android.app import AlertDialog
                from android.widget import EditText
            except Exception:
                CheckBox = None
            layout = LinearLayout(activity)
            layout.setOrientation(1)
            layout.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(8), AndroidUtilities.dp(16), AndroidUtilities.dp(8))
            backup_dir = BackupManager(self).backup_dir
            display_labels = []
            for name in files:
                size_text = ""
                try:
                    size_bytes = os.path.getsize(os.path.join(backup_dir, name))
                    size_kb = max(1, int(size_bytes / 1024))
                    size_text = f" ({size_kb} KB)"
                except Exception:
                    size_text = ""
                display_labels.append(f"{name}{size_text}")
            checkboxes = []
            for label in display_labels:
                if CheckBox:
                    cb = CheckBox(activity)
                    cb.setText(label)
                    try:
                        cb.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                    except Exception:
                        pass
                    try:
                        cb.setButtonTintList(ColorStateList.valueOf(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText)))
                    except Exception:
                        pass
                    layout.addView(cb)
                    checkboxes.append(cb)
            builder = AlertDialogBuilder(activity)
            builder.set_title(tr("nowfy_backup_manage_title"))
            builder.set_view(layout)
            dialog = None
            def _remove_selected():
                try:
                    selected = []
                    for cb, name in zip(checkboxes, files):
                        if cb.isChecked():
                            selected.append(name)
                    if not selected:
                        try:
                            BulletinHelper.show_info(tr("nowfy_backup_manage_none"))
                        except Exception:
                            pass
                        return
                    backup_dir = BackupManager(self).backup_dir
                    removed = 0
                    for name in selected:
                        try:
                            path = os.path.join(backup_dir, name)
                            if os.path.exists(path):
                                os.remove(path)
                                removed += 1
                        except Exception:
                            pass
                    try:
                        if removed > 0:
                            BulletinHelper.show_success(tr("nowfy_backup_manage_removed").format(count=removed))
                        else:
                            BulletinHelper.show_info(tr("nowfy_backup_manage_none"))
                    except Exception:
                        pass
                    try:
                        dialog.dismiss()
                    except Exception:
                        pass
                except Exception:
                    pass
            def _rename_selected():
                try:
                    selected = []
                    for cb, name in zip(checkboxes, files):
                        if cb.isChecked():
                            selected.append(name)
                    if len(selected) != 1:
                        try:
                            BulletinHelper.show_info(tr("nowfy_backup_manage_rename_one"))
                        except Exception:
                            pass
                        return
                    old_name = selected[0]
                    base_name, _ext = os.path.splitext(old_name)
                    edit = EditText(activity)
                    try:
                        edit.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                    except Exception:
                        pass
                    try:
                        edit.setHintTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteHintText))
                    except Exception:
                        pass
                    try:
                        edit.setText(base_name)
                    except Exception:
                        pass
                    rename_builder = AlertDialogBuilder(activity)
                    rename_builder.set_title(tr("nowfy_backup_manage_rename_title"))
                    rename_builder.set_view(edit)
                    def _confirm_rename(b=None, w=None):
                        try:
                            new_base = str(edit.getText()) if edit else ""
                            new_base = new_base.strip()
                            if not new_base:
                                BulletinHelper.show_info(tr("nowfy_backup_manage_rename_invalid"))
                                return
                            new_name = f"{new_base}.nowfy"
                            if new_name == old_name:
                                BulletinHelper.show_info(tr("nowfy_backup_manage_rename_same"))
                                return
                            backup_dir = BackupManager(self).backup_dir
                            old_path = os.path.join(backup_dir, old_name)
                            new_path = os.path.join(backup_dir, new_name)
                            if os.path.exists(new_path):
                                BulletinHelper.show_info(tr("nowfy_backup_manage_rename_exists"))
                                return
                            os.rename(old_path, new_path)
                            BulletinHelper.show_success(tr("nowfy_backup_manage_rename_done"))
                            try:
                                dialog.dismiss()
                            except Exception:
                                pass
                        except Exception:
                            pass
                    rename_builder.set_positive_button(tr("nowfy_backup_manage_rename_action"), _confirm_rename)
                    rename_builder.set_negative_button(tr("cancel"), None)
                    rename_builder.show()
                except Exception:
                    pass
            builder.set_positive_button(tr("nowfy_backup_manage_remove"), lambda *args: _remove_selected())
            builder.set_neutral_button(tr("nowfy_backup_manage_rename_action"), lambda *args: _rename_selected())
            builder.set_negative_button(tr("cancel"), None)
            dialog = builder.show()
            try:
                if dialog and AlertDialog:
                    rename_btn = dialog.getButton(AlertDialog.BUTTON_NEUTRAL)
                    if rename_btn:
                        rename_btn.setVisibility(8)
                        def _update_rename_btn():
                            try:
                                count = 0
                                for cb in checkboxes:
                                    if cb.isChecked():
                                        count += 1
                                rename_btn.setVisibility(0 if count == 1 else 8)
                            except Exception:
                                pass
                        for cb in checkboxes:
                            try:
                                cb.setOnCheckedChangeListener(lambda v, is_checked: _update_rename_btn())
                            except Exception:
                                pass
                        _update_rename_btn()
            except Exception:
                pass
        except Exception:
            pass

    def _list_custom_fonts(self):
        fonts_dir = self._get_custom_fonts_path()
        custom_fonts = []
        if os.path.exists(fonts_dir):
            for file in os.listdir(fonts_dir):
                if file.lower().endswith(('.ttf', '.otf', '.ttc')):
                    custom_fonts.append(file)
        return custom_fonts

    def _get_font_display_name(self, font_path, fallback_name):
        try:
            from fontTools.ttLib import TTFont
            font = TTFont(font_path, lazy=True)
            name_table = font.get("name")
            if name_table:
                for name_id in (4, 1):
                    for record in name_table.names:
                        if record.nameID == name_id:
                            try:
                                value = record.toUnicode()
                            except Exception:
                                value = str(record)
                            if value:
                                try:
                                    font.close()
                                except Exception:
                                    pass
                                return value
            try:
                font.close()
            except Exception:
                pass
        except Exception:
            pass
        return fallback_name

    def _list_custom_fonts_display(self):
        fonts_dir = self._get_custom_fonts_path()
        names = []
        for file in self._list_custom_fonts():
            try:
                path = os.path.join(fonts_dir, file)
                label = self._get_font_display_name(path, os.path.splitext(file)[0])
                names.append(label)
            except Exception:
                names.append(os.path.splitext(file)[0])
        return names

    def _get_font_path_by_selector(self, font_selector):
        custom_fonts = self._list_custom_fonts()
        try:
            font_selector = int(font_selector or 0)
        except Exception:
            font_selector = 1
        if font_selector == 0:
            total = 3 + len(custom_fonts)
            try:
                favs = [int(v) for v in self._get_font_random_favorites() if 1 <= int(v) <= total]
                if favs:
                    font_selector = random.choice(favs)
                else:
                    font_selector = random.randint(1, total) if total > 0 else 1
            except Exception:
                font_selector = 1
        if font_selector == 1:
            return "/system/fonts/SourceSansPro-Bold.ttf"
        elif font_selector == 2:
            return self._ensure_extera_font(1)
        elif font_selector == 3:
            return "/system/fonts/NotoNaskhArabic-Bold.ttf"
        elif font_selector > 3 and custom_fonts:
            idx = font_selector - 4
            if idx < len(custom_fonts):
                return os.path.join(self._get_custom_fonts_path(), custom_fonts[idx])
        return "/system/fonts/SourceSansPro-Bold.ttf"

    def _get_font_regular_by_selector(self, font_selector):
        custom_fonts = self._list_custom_fonts()
        try:
            font_selector = int(font_selector or 0)
        except Exception:
            font_selector = 1
        if font_selector == 0:
            total = 3 + len(custom_fonts)
            try:
                favs = [int(v) for v in self._get_font_random_favorites() if 1 <= int(v) <= total]
                if favs:
                    font_selector = random.choice(favs)
                else:
                    font_selector = random.randint(1, total) if total > 0 else 1
            except Exception:
                font_selector = 1
        if font_selector == 1:
            return "/system/fonts/SourceSansPro-Regular.ttf"
        elif font_selector == 2:
            return self._ensure_extera_font(1)
        elif font_selector == 3:
            return "/system/fonts/NotoNaskhArabic-Regular.ttf"
        elif font_selector > 3 and custom_fonts:
            idx = font_selector - 4
            if idx < len(custom_fonts):
                return os.path.join(self._get_custom_fonts_path(), custom_fonts[idx])
        return "/system/fonts/SourceSansPro-Regular.ttf"

    def _get_font_for_title(self, text, selector, max_size=28, min_size=28, base_size=28, force_bold=False):
        selector = self._resolve_font_selector_for_title(selector)
        if force_bold:
            return ImageFont.truetype(self._get_font_path_by_selector(selector), max_size)
        else:
            return ImageFont.truetype(self._get_font_regular_by_selector(selector), max_size)

    def _get_font_for_artist(self, artist_text, selector, size=22, force_bold=False):
        selector = self._resolve_font_selector_for_artist(selector)
        if self._is_arabic(artist_text):
            font_path = "/system/fonts/NotoNaskhArabic-Bold.ttf" if force_bold else "/system/fonts/NotoNaskhArabic-Regular.ttf"
            return ImageFont.truetype(font_path, size)
        if force_bold:
            return ImageFont.truetype(self._get_font_path_by_selector(selector), size)
        else:
            return ImageFont.truetype(self._get_font_regular_by_selector(selector), size)

    def _get_default_font(self, size=20):
        return ImageFont.truetype("/system/fonts/SourceSansPro-Regular.ttf", size)

    def _get_font_apply_scope(self):
        try:
            raw = self.get_setting("font_apply_scope", 2)
        except Exception:
            raw = 2
        try:
            return int(raw)
        except Exception:
            pass
        try:
            s = str(raw or "").strip().lower()
        except Exception:
            return 2
        if ("music" in s) or ("musica" in s) or ("música" in s):
            return 0
        if ("artist" in s) or ("artista" in s):
            return 1
        if ("both" in s) or ("ambos" in s) or ("les deux" in s):
            return 2
        return 2

    def _resolve_font_selector_for_title(self, selector):
        scope = self._get_font_apply_scope()
        if scope == 1:
            return 1
        return selector

    def _resolve_font_selector_for_artist(self, selector):
        scope = self._get_font_apply_scope()
        if scope == 0:
            return 1
        return selector

    def draw_multiline_text(self, draw, text, position, font, fill, max_width, line_spacing=4):
        words = text.split() if " " in text else ([text] if len(text) <= 5 else list(text))
        lines, current_line = [], ""
        for word in words:
            test_line = current_line + " " + word if current_line else word
            if draw.textbbox((0, 0), test_line, font=font)[2] <= max_width:
                current_line = test_line
            else:
                lines.append(current_line)
                current_line = word
        if current_line:
            lines.append(current_line)
        x, y = position
        for line in lines:
            draw.text((x, y), line, font=font, fill=fill)
            left, top, right, bottom = font.getbbox("Ay")
            y += (bottom - top) + line_spacing
        return y

    def get_text_dimensions(self, text, font):
        try:
            left, top, right, bottom = font.getbbox(text)
            return right - left, bottom - top
        except AttributeError:
            try:
                return font.getsize(text)
            except AttributeError:
                return len(text) * 8, font.size

    def get_multiline_height(self, draw, text, font, max_width, line_spacing=4):
        words = text.split() if " " in text else ([text] if len(text) <= 5 else list(text))
        lines, current_line = [], ""
        for word in words:
            test_line = current_line + " " + word if current_line else word
            width, _ = self.get_text_dimensions(test_line, font)
            if width <= max_width:
                current_line = test_line
            else:
                lines.append(current_line)
                current_line = word
        if current_line:
            lines.append(current_line)
        _, height = self.get_text_dimensions("Ay", font)
        return (height + line_spacing) * len(lines)

