    def _skip_track(self, params):
        try:
            try:
                preload_enabled = bool(self.get_setting("enable_preload", False))
            except Exception:
                preload_enabled = False
            try:
                data_source = int(self.get_setting("pop_data_source_selector", 0) or 0)
            except Exception:
                data_source = 0
            if data_source == 1:
                try:
                    mc = MediaController.getInstance()
                    success = False
                    try:
                        for method_name in ("playNextMessage", "nextAudio", "playNext"):
                            if hasattr(mc, method_name):
                                getattr(mc, method_name)()
                                success = True
                                break
                    except Exception:
                        success = False
                    try:
                        self._show_control_notice(tr("bulletin_skipped") if success else tr("no_track_playing_generic"))
                    except Exception:
                        pass
                    return
                except Exception:
                    pass
            token = self._get_access_token()
            if not token:
                if self._should_show_error_bulletin("auth_error"):
                    self._show_control_notice(tr("error_auth"))
                return
            resp = requests.post(
                "https://api.spotify.com/v1/me/player/next",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code in (200, 202, 204):
                self._show_control_notice(tr("bulletin_skipped"))
                if preload_enabled:
                    def delayed_preload():
                        time.sleep(1)
                        self._preload_next_track_cover()
                    threading.Thread(target=delayed_preload, daemon=True).start()
            elif resp.status_code == 403:
                self._show_control_notice(tr("error_premium_required"))
            elif resp.status_code == 404:
                self._show_control_notice(tr("error_no_active_device"))
            else:
                self._show_control_notice(tr("error_unknown"))
        except Exception:
            self._show_control_notice(tr("error_unknown"))

