    def _get_spotify_volume_percent(self):
        try:
            cached_value = getattr(self, "_spotify_volume_cache_value", None)
            cached_ts = float(getattr(self, "_spotify_volume_cache_ts", 0.0) or 0.0)
            now_ts = float(time.time())
            if isinstance(cached_value, int) and (now_ts - cached_ts) <= 1.5:
                return max(0, min(100, int(cached_value)))
            token = self._get_access_token()
            if not token:
                if self._should_show_error_bulletin("auth_error"):
                    self._show_control_notice(tr("error_auth"))
                return None
            resp = requests.get(
                "https://api.spotify.com/v1/me/player",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code == 200:
                data = resp.json() if resp and resp.content else {}
                device = data.get("device") if isinstance(data, dict) else None
                vol = device.get("volume_percent") if isinstance(device, dict) else None
                if isinstance(vol, int):
                    val = max(0, min(100, int(vol)))
                    self._spotify_volume_cache_value = val
                    self._spotify_volume_cache_ts = now_ts
                    return val
                return None
            if resp.status_code == 404:
                self._show_control_notice(tr("error_no_active_device"))
                return None
            if resp.status_code == 403:
                self._show_control_notice(tr("error_premium_required"))
                return None
            self._show_control_notice(tr("error_unknown"))
            return None
        except Exception:
            self._show_control_notice(tr("error_unknown"))
            return None

    def _adjust_spotify_volume(self, delta):
        try:
            step = int(delta)
        except Exception:
            step = 0
        if step == 0:
            return
        current = self._get_spotify_volume_percent()
        if current is None:
            return
        target = max(0, min(100, int(current + step)))
        if target == current:
            self._show_control_notice(tr("bulletin_volume_set").format(value=target))
            return
        self._spotify_volume_cache_value = target
        self._spotify_volume_cache_ts = float(time.time())
        self._set_volume(None, target)

    def _set_volume(self, params, value):
        try:
            if not isinstance(value, int) or value < 0 or value > 100:
                self._show_control_notice(tr("error_invalid_volume"))
                return
            token = self._get_access_token()
            if not token:
                if self._should_show_error_bulletin("auth_error"):
                    self._show_control_notice(tr("error_auth"))
                return
            resp = requests.put(
                f"https://api.spotify.com/v1/me/player/volume?volume_percent={value}",
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code in (200, 202, 204):
                self._spotify_volume_cache_value = int(value)
                self._spotify_volume_cache_ts = float(time.time())
                self._show_control_notice(tr("bulletin_volume_set").format(value=value))
            elif resp.status_code == 403:
                self._show_control_notice(tr("error_premium_required"))
            elif resp.status_code == 404:
                self._show_control_notice(tr("error_no_active_device"))
            else:
                self._show_control_notice(tr("error_unknown"))
        except Exception as e:
            self._show_control_notice(tr("error_unknown"))

