            from PIL import Image, ImageDraw, ImageFont, ImageFilter, ImageOps
            if progress_dialog:
                run_on_ui_thread(lambda: progress_dialog.set_progress(50))
            player_name = str(player or self._detect_current_player() or "Spotify")
            send_helper = get_send_messages_helper()
            base_dir = ApplicationLoader.getFilesDirFixed()
            temp_dir = File(base_dir, "nowFy")
            if not temp_dir.exists():
                temp_dir.mkdirs()
            use_high_res = self.get_setting("fmcard_high_resolution", False)
            if use_high_res:
                card_width, card_height = 1920, 1080
            else:
                card_width, card_height = 1012, 512
            cache_key = f"fmcard_{title}_{artist}_{use_high_res}_{self.get_setting('lastfm_fmcard_background_color', '#d2d2d2')}_{self.get_setting('lastfm_fmcard_text_color', '#000000')}_{self.get_setting('lastfm_fmcard_cover_position', 0)}"
            cache_key = hashlib.md5(cache_key.encode()).hexdigest()
            cached_path = self._get_cached_fmcard_image(cache_key, temp_dir)
            if cached_path and File(cached_path).exists():
                return cached_path
            filename = f"fmcard_{cache_key}.png"
            temp_path = File(temp_dir, filename).getAbsolutePath()
            use_bg = self.get_setting("lastfm_fmcard_use_background", True)
