    def _on_vinify_bar_color_mode_change(self, value, is_bg):
        try:
            mode = int(value if value is not None else 0)
        except Exception:
            mode = 0
        if mode == 1:
            setting_key = "vinify_bar_bg_custom_color" if bool(is_bg) else "vinify_bar_custom_color"
            if not str(self.get_setting(setting_key, "") or "").strip():
                self.set_setting(setting_key, "#808080" if bool(is_bg) else "#FFFFFF")
            # Selector callbacks may run on pluginsQueue; force picker open on main thread.
            run_on_ui_thread(lambda: self._open_color_picker_for_setting(setting_key, "vinify_title_color"))

