    def _get_youtube_cover(self, song_title, artists=''):
        try:
            youtube_api_key = str(self.get_setting('youtube_api_key', '') or '').strip()
            if not youtube_api_key:
                return self._get_youtube_thumbnail_forced(song_title, artists)
            search_query = f"{song_title} {artists} official"
            api_url = "https://www.googleapis.com/youtube/v3/search"
            params = {
                "part": "snippet",
                "q": search_query,
                "type": "video",
                "maxResults": 5,
                "key": youtube_api_key,
            }
            response = requests.get(api_url, params=params, timeout=10)
            data = response.json() if response is not None else {}
            if 'error' in data:
                raise Exception(data['error'].get('message', tr('error_unknown')))
            items = data.get('items') or []
            if items:
                video_ids = [
                    item.get('id', {}).get('videoId')
                    for item in items
                    if isinstance(item, dict) and item.get('id', {}).get('videoId')
                ]
                quality_order = ['maxresdefault', 'hq720', 'sddefault', 'hqdefault', 'mqdefault', 'default']
                for quality in quality_order:
                    for video_id in video_ids:
                        for base in ["https://img.youtube.com", "https://i.ytimg.com"]:
                            thumb_url = f"{base}/vi/{video_id}/{quality}.jpg"
                            try:
                                head_resp = requests.head(thumb_url, timeout=5)
                                if head_resp.status_code != 200:
                                    get_resp = requests.get(thumb_url, timeout=8, stream=True)
                                    if get_resp.status_code != 200:
                                        continue
                                data_resp = requests.get(thumb_url, timeout=8)
                                if data_resp.status_code == 200 and self._is_high_quality_thumbnail(data_resp.content):
                                    return thumb_url
                            except Exception:
                                continue
            return self._get_youtube_thumbnail_forced(song_title, artists)
        except Exception as e:
            return self._get_youtube_thumbnail_forced(song_title, artists)

    def _get_youtube_thumbnail_forced(self, song_title, artists=''):
        try:
            from urllib.parse import quote_plus
            clean_title = self._clean_search_term(song_title)
            clean_artist = self._clean_search_term(artists) if artists else ''
            if clean_artist:
                search_query = f"{clean_artist} {clean_title} official"
            else:
                search_query = f"{clean_title} official"
            try:
                from ytmusicapi import YTMusic
                ytm = YTMusic()
                ytm_query = f"{clean_artist} {clean_title}".strip()
                ytm_results = ytm.search(ytm_query, filter="songs", limit=5) or ytm.search(ytm_query, filter="videos", limit=5)
                if ytm_results:
                    quality_order = ['maxresdefault', 'hq720', 'sddefault', 'hqdefault', 'mqdefault', 'default']
                    bases = ["https://img.youtube.com", "https://i.ytimg.com"]
                    for item in ytm_results:
                        video_id = item.get("videoId") if isinstance(item, dict) else None
                        if not video_id:
                            continue
                        for quality in quality_order:
                            for base in bases:
                                thumb_url = f"{base}/vi/{video_id}/{quality}.jpg"
                                try:
                                    head_resp = requests.head(thumb_url, timeout=5)
                                    if head_resp.status_code != 200:
                                        get_resp = requests.get(thumb_url, timeout=8, stream=True)
                                        if get_resp.status_code != 200:
                                            continue
                                    data_resp = requests.get(thumb_url, timeout=8)
                                    if data_resp.status_code == 200 and self._is_high_quality_thumbnail(data_resp.content):
                                        return thumb_url
                                except Exception:
                                    continue
            except Exception as ytm_e:
                pass
            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
            }
            try:
                search_url = f"https://www.youtube.com/results?search_query={quote_plus(search_query)}"
                response = requests.get(search_url, headers=headers, timeout=10)
                if response.status_code == 200:
                    video_ids = re.findall(r'"videoId":"([a-zA-Z0-9_-]{11})"', response.text)
                    if video_ids:
                        video_id = video_ids[0]
                        quality_order = ['maxresdefault', 'hq720', 'sddefault', 'hqdefault', 'mqdefault', 'default']
                        bases = ["https://img.youtube.com", "https://i.ytimg.com"]
                        for quality in quality_order:
                            for base in bases:
                                thumb_url = f"{base}/vi/{video_id}/{quality}.jpg"
                                try:
                                    head_resp = requests.head(thumb_url, timeout=5)
                                    if head_resp.status_code != 200:
                                        get_resp = requests.get(thumb_url, timeout=8, stream=True)
                                        if get_resp.status_code != 200:
                                            continue
                                    data_resp = requests.get(thumb_url, timeout=8)
                                    if data_resp.status_code == 200 and self._is_high_quality_thumbnail(data_resp.content):
                                        return thumb_url
                                except Exception:
                                    continue
                    if clean_artist:
                        fallback_query = f"{clean_artist} {clean_title}"
                    else:
                        fallback_query = clean_title
                    fallback_url = f"https://www.youtube.com/results?search_query={quote_plus(fallback_query)}"
                    fallback_response = requests.get(fallback_url, headers=headers, timeout=10)
                    if fallback_response.status_code == 200:
                        video_ids = re.findall(r'"videoId":"([a-zA-Z0-9_-]{11})"', fallback_response.text)
                        if video_ids:
                            video_id = video_ids[0]
                            quality_order = ['maxresdefault', 'hq720', 'sddefault', 'hqdefault', 'mqdefault', 'default']
                            bases = ["https://img.youtube.com", "https://i.ytimg.com"]
                            for quality in quality_order:
                                for base in bases:
                                    thumb_url = f"{base}/vi/{video_id}/{quality}.jpg"
                                    try:
                                        head_resp = requests.head(thumb_url, timeout=5)
                                        if head_resp.status_code != 200:
                                            get_resp = requests.get(thumb_url, timeout=8, stream=True)
                                            if get_resp.status_code != 200:
                                                continue
                                        data_resp = requests.get(thumb_url, timeout=8)
                                        if data_resp.status_code == 200 and self._is_high_quality_thumbnail(data_resp.content):
                                            return thumb_url
                                    except Exception:
                                        continue
            except Exception as e:
                pass
            return "https://assets.nowfy/icondefault.png"
        except Exception as e:
            return "https://assets.nowfy/icondefault.png"

    def _is_lastfm_placeholder_image(self, url):
        try:
            if not url:
                return True
            u = str(url).lower()
            return ("2a96c" in u) or ("noimage" in u) or ("default" in u and "last" in u)
        except Exception:
            return False

    def _find_best_youtube_match(self, matches, title, artist):
        try:
            title_lower = title.lower() if title else ''
            artist_lower = artist.lower() if artist else ''
            scored_matches = []
            for video_id, video_title in matches:
                video_title_lower = video_title.lower()
                score = 0
                if title_lower and title_lower in video_title_lower:
                    score += 50
                if artist_lower and artist_lower in video_title_lower:
                    score += 40
                if any(term in video_title_lower for term in ['official', 'oficial']):
                    score += 20
                if any(term in video_title_lower for term in ['music video', 'mv', 'clipe']):
                    score += 15
                penalty_terms = ['cover', 'remix', 'karaoke', 'instrumental', 'live', 'ao vivo', 'reaction', 'tutorial']
                for term in penalty_terms:
                    if term in video_title_lower:
                        score -= 25
                        break
                if any(term in video_title_lower for term in ['playlist', 'mix', 'compilation', 'hours', 'horas']):
                    score -= 30
                title_words = re.findall(r'\b\w+\b', title_lower)
                video_words = re.findall(r'\b\w+\b', video_title_lower)
                matching_words = len(set(title_words) & set(video_words))
                if title_words:
                    word_match_ratio = matching_words / len(title_words)
                    score += int(word_match_ratio * 30)
                scored_matches.append((video_id, video_title, score))
            scored_matches.sort(key=lambda x: x[2], reverse=True)
            if scored_matches and scored_matches[0][2] > 0:
                best_match = scored_matches[0]
                return (best_match[0], best_match[1])
            if matches:
                return matches[0]
            return None
        except Exception as e:
            return matches[0] if matches else None

    def _search_spotify_url(self, title, artist):
        try:
            token = self._get_access_token()
            if not token:
                return None
            query = f"{title} {artist}"
            resp = requests.get(
                "https://api.spotify.com/v1/search",
                params={"q": query, "type": "track", "limit": 1},
                headers={"Authorization": f"Bearer {token}"},
                timeout=5
            )
            if resp.status_code == 200:
                data = resp.json()
                items = data.get("tracks", {}).get("items", [])
                if items:
                    return items[0]["external_urls"]["spotify"]
        except Exception:
            pass
        return None

    def _search_spotify_url_public(self, title, artist):
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
            }
            query = f"site:open.spotify.com track {title} {artist}"
            url = f"https://duckduckgo.com/html/?q={quote(query)}"
            resp = requests.get(url, timeout=8, headers=headers)
            if resp.status_code == 200:
                body = resp.text
                m = re.search(r"https://open\.spotify\.com/track/[A-Za-z0-9]+", body)
                if m:
                    return m.group(0)
        except Exception as e:
            pass
        return None

    def _get_spotify_oembed_thumbnail(self, spotify_url):
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
                "Accept": "application/json,text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            }
            oembed_url = f"https://open.spotify.com/oembed?url={quote(spotify_url)}"
            r = requests.get(oembed_url, timeout=8, headers=headers)
            if r.status_code == 200:
                data = r.json()
                thumb = data.get("thumbnail_url")
                if thumb:
                    return thumb
            page = requests.get(spotify_url, timeout=8, headers=headers)
            if page.status_code == 200:
                m = re.search(r'<meta property="og:image" content="([^"]+)"', page.text)
                if m:
                    return m.group(1)
        except Exception as e:
            pass
        return None

    def _get_spotify_cover_fallback(self, title, artists):
        try:
            primary_artist = artists.split(",")[0].strip() if isinstance(artists, str) else artists
            spotify_url = self._search_spotify_url(title, primary_artist)
            if not spotify_url:
                spotify_url = self._search_spotify_url_public(title, primary_artist)
            if spotify_url:
                return self._get_spotify_oembed_thumbnail(spotify_url)
        except Exception as e:
            pass
        return None

    def _get_spotify_cover_precise(self, title, artists, album=None, duration_ms=None):
        try:
            primary_artist = artists.split(",")[0].strip() if isinstance(artists, str) else artists
            t = self._sanitize_track_title(title)
            a = str(primary_artist or "").strip()
            al = self._sanitize_track_title(album) if album else None
            token = None
            try:
                token = self._get_access_token(show_error_bulletin=False)
            except Exception:
                token = None
            if token:
                q_parts = []
                if t:
                    q_parts.append(f'track:"{t}"')
                if a:
                    q_parts.append(f'artist:"{a}"')
                if al:
                    q_parts.append(f'album:"{al}"')
                query = " ".join(q_parts) if q_parts else f"{t} {a}"
                resp = requests.get(
                    "https://api.spotify.com/v1/search",
                    params={"q": query, "type": "track", "limit": 5},
                    headers={"Authorization": f"Bearer {token}"},
                    timeout=6
                )
                if resp.status_code == 200:
                    data = resp.json()
                    items = data.get("tracks", {}).get("items", []) or []
                    def _norm(s):
                        try:
                            return re.sub(r"\s+", " ", str(s or "").lower().strip())
                        except Exception:
                            return str(s or "").lower().strip()
                    nt = _norm(t)
                    na = _norm(a)
                    nal = _norm(al) if al else None
                    best = None
                    best_score = -1
                    for it in items:
                        it_title = _norm(it.get("name"))
                        it_artists = _norm(", ".join([x.get("name", "") for x in it.get("artists", [])]))
                        it_album = _norm(it.get("album", {}).get("name"))
                        score = 0
                        if it_title == nt:
                            score += 4
                        elif nt and nt in it_title:
                            score += 2
                        if na and na in it_artists:
                            score += 3
                        if nal:
                            if it_album == nal:
                                score += 2
                            elif nal in it_album:
                                score += 1
                        if duration_ms and isinstance(it.get("duration_ms"), int):
                            try:
                                diff = abs(int(it.get("duration_ms")) - int(duration_ms))
                                if diff <= 2000:
                                    score += 1
                            except Exception:
                                pass
                        if score > best_score:
                            best_score = score
                            best = it
                    if best and isinstance(best.get("album"), dict):
                        images = best.get("album", {}).get("images", []) or []
                        if isinstance(images, list) and images:
                            try:
                                return (images[0] or {}).get("url") or None
                            except Exception:
                                try:
                                    return images[0].get("url")
                                except Exception:
                                    return None
            dd_headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
            }
            terms = [t, a]
            if al:
                terms.append(al)
            quoted = " ".join([f'"{x}"' for x in terms if x])
            query = f"site:open.spotify.com/track {quoted}"
            url = f"https://duckduckgo.com/html/?q={quote(query)}"
            r = requests.get(url, timeout=8, headers=dd_headers)
            if r.status_code == 200:
                m = re.search(r"https://open\.spotify\.com/track/[A-Za-z0-9]+", r.text)
                if m:
                    track_url = m.group(0)
                    thumb = self._get_spotify_oembed_thumbnail(track_url)
                    if thumb:
                        return thumb
        except Exception as e:
            pass
        return None

    def _normalize_local_player_metadata(self, title, artist):
        try:
            raw_title = str(title or "").strip()
            raw_artist = str(artist or "").strip()
            normalized_title = re.sub(r"\.(mp3|m4a|aac|flac|ogg|opus|wav)$", "", raw_title, flags=re.IGNORECASE)
            normalized_title = re.sub(r"[_\-\s]?\d{8,}$", "", normalized_title)
            normalized_title = normalized_title.replace("_", " ")
            normalized_title = re.sub(r"\s+", " ", normalized_title).strip(" -_.")
            artist_l = raw_artist.lower()
            invalid_artist = (not raw_artist) or artist_l in ("unknown artist", "unknown", "desconhecido", "none")
            if invalid_artist and " - " in normalized_title:
                left, right = normalized_title.split(" - ", 1)
                left = left.strip()
                right = right.strip()
                if left and right:
                    raw_artist = left
                    normalized_title = right
            if not normalized_title:
                normalized_title = "Unknown Track"
            if not raw_artist or str(raw_artist).strip().lower() in ("unknown artist", "unknown", "desconhecido", "none"):
                raw_artist = "Powered by Nowfy"
            return normalized_title, raw_artist
        except Exception:
            safe_title = str(title or "").strip() or "Unknown Track"
            safe_artist = str(artist or "").strip() or "Powered by Nowfy"
            return safe_title, safe_artist

    def get_current_track_etg(self, account):
        try:
            media_controller = MediaController.getInstance()
            playing_song = media_controller.getPlayingMessageObject()
            if playing_song is None or not playing_song.isMusic():
                return None
            title = playing_song.getMusicTitle()
            artist = playing_song.getMusicAuthor()
            title, artist = self._normalize_local_player_metadata(title, artist)
            duration = playing_song.getDuration()
            progress = media_controller.getPlayingMessageObject().audioProgressSec
            return {
                "title": title,
                "artist": artist,
                "duration": duration,
                "progress": progress,
                "is_playing": True
            }
        except Exception as e:
            return None

