    def _set_tab_feedback_progress(self, percent):
        try:
            if not bool(getattr(self, "_tab_feedback_pending", False)):
                return
            current = int(getattr(self, "_tab_feedback_progress", 0))
            target = max(0, min(100, int(percent)))
            if target < current:
                return
            self._tab_feedback_progress = target
        except Exception:
            pass

    def _finish_tab_feedback(self):
        try:
            if bool(getattr(self, "_tab_feedback_pending", False)):
                self._tab_feedback_progress = 100
                self._tab_feedback_done = True
        except Exception:
            pass

