            def _lt(key, fallback):
                try:
                    idx = int(plugin.get_setting("plugin_lang", 0) or 0) if plugin and hasattr(plugin, "get_setting") else 0
                except Exception:
                    idx = 0
                try:
                    codes = ["en", "pt", "ru"]
                    lang = codes[idx] if 0 <= idx < len(codes) else "en"
                except Exception:
                    lang = "en"
                try:
                    entry = TRANSLATIONS.get(str(key), {})
                    if isinstance(entry, dict):
                        val = str(entry.get(lang) or "").strip()
                        if val:
                            return val
                        val_en = str(entry.get("en") or "").strip()
                        if val_en:
                            return val_en
                except Exception:
                    pass
                try:
                    if plugin and hasattr(plugin, "tr"):
                        v0 = str(plugin.tr(key) or "").strip()
                        if v0 and v0 != key:
                            return v0
                except Exception:
                    pass
                try:
                    v1 = str(tr(key) or "").strip()
                    if v1 and v1 != key:
                        return v1
                except Exception:
                    pass
                return str(fallback)
            ctx = activity.getContext() if activity else None
            if not ctx:
                return None
            def _open_service_via_native_item(setting_key):
                try:
                    item_map = getattr(plugin, "_services_open_item_map", None)
                    req = str(setting_key or "").strip()
                    target_item = item_map.get(req) if isinstance(item_map, dict) else None
                    if target_item is None and isinstance(item_map, dict):
                        try:
                            if req == "nowfy_services_spotify":
                                target_item = item_map.get("spotify")
                            elif req == "nowfy_services_lastfm":
                                target_item = item_map.get("lastfm")
                            elif req == "nowfy_services_statsfm":
                                target_item = item_map.get("statsfm")
                            elif req == "nowfy_services_ymusic":
                                target_item = item_map.get("ymusic")
                        except Exception:
                            target_item = None
                    if (not target_item) and activity:
                        try:
                            cb = None
                            if req == "nowfy_services_spotify" and hasattr(plugin, "create_spotify_credentials_subfragment"):
                                cb = plugin.create_spotify_credentials_subfragment
                            elif req == "nowfy_services_lastfm" and hasattr(plugin, "create_lastfm_credentials_subfragment"):
                                cb = plugin.create_lastfm_credentials_subfragment
                            elif req == "nowfy_services_statsfm" and hasattr(plugin, "create_statsfm_credentials_subfragment"):
                                cb = plugin.create_statsfm_credentials_subfragment
                            elif req == "nowfy_services_ymusic" and hasattr(plugin, "create_ymusic_credentials_subfragment"):
                                cb = plugin.create_ymusic_credentials_subfragment
                            if cb and hasattr(plugin, "_set_subfragment_callback"):
                                run_on_ui_thread(lambda: plugin._set_subfragment_callback(activity, cb))
                                return
                        except Exception:
                            pass
                    if not target_item or not activity:
                        try:
                            BulletinHelper.show_info("Could not open this section right now.")
                        except Exception:
                            pass
                        return
                    UItemCls = find_class("org.telegram.ui.Components.UItem")
                    ViewCls = find_class("android.view.View")
                    IntType = find_class("java.lang.Integer").TYPE
                    FloatType = find_class("java.lang.Float").TYPE
                    if not UItemCls or not ViewCls or not IntType or not FloatType:
                        try:
                            BulletinHelper.show_info("Could not open this section right now.")
                        except Exception:
                            pass
                        return
                    click_method = activity.getClass().getDeclaredMethod("onClick", UItemCls, ViewCls, IntType, FloatType, FloatType)
                    click_method.setAccessible(True)
                    def _invoke():
                        try:
                            click_method.invoke(activity, target_item, None, jint(0), JFloat(0.0), JFloat(0.0))
                        except Exception:
                            try:
                                BulletinHelper.show_info("Could not open this section right now.")
                            except Exception:
                                pass
                    run_on_ui_thread(_invoke)
                    try:
                        pass
                    except Exception:
                        pass
                except Exception:
                    try:
                        pass
                    except Exception:
                        pass
                    try:
                        BulletinHelper.show_info("Could not open this section right now.")
                    except Exception:
                        pass
