    def inject_services_cards_custom(self, plugin, activity, items):
        try:
            insert_idx = -1
            remove_indices = []
            service_item_map = {}
            for i in range(items.size()):
                try:
                    it = items.get(i)
                    marker = str(getattr(it, "object2", "") or "")
                    if marker == "__services_custom_cards__":
                        remove_indices.append(i)
                        continue
                    key = plugin._get_uitem_setting_key(it)
                    si = getattr(it, "settingItem", None)
                    try:
                        txt = str(plugin._get_uitem_text(it) or "").strip().lower()
                    except Exception:
                        txt = str(getattr(si, "text", "") or "").strip().lower() if si else ""
                    if key in ("nowfy_services_spotify", "nowfy_services_lastfm", "nowfy_services_statsfm", "nowfy_services_ymusic") or txt in ("spotify", "last.fm", "stats.fm", "yandex music", "ymusic"):
                        if key:
                            service_item_map[str(key)] = it
                        t = txt.replace(" ", "").replace(".", "")
                        if "spotify" in t:
                            service_item_map["spotify"] = it
                            if "nowfy_services_spotify" not in service_item_map:
                                service_item_map["nowfy_services_spotify"] = it
                        elif "lastfm" in t:
                            service_item_map["lastfm"] = it
                            if "nowfy_services_lastfm" not in service_item_map:
                                service_item_map["nowfy_services_lastfm"] = it
                        elif "statsfm" in t:
                            service_item_map["statsfm"] = it
                            if "nowfy_services_statsfm" not in service_item_map:
                                service_item_map["nowfy_services_statsfm"] = it
                        elif ("yandexmusic" in t) or ("ymusic" in t):
                            service_item_map["ymusic"] = it
                            if "nowfy_services_ymusic" not in service_item_map:
                                service_item_map["nowfy_services_ymusic"] = it
                        remove_indices.append(i)
                        if insert_idx < 0:
                            insert_idx = i
                except Exception:
                    pass
            if insert_idx < 0:
                return
            for idx in reversed(sorted(list(set(remove_indices)))):
                try:
                    items.remove(idx)
                except Exception:
                    pass
            try:
                setattr(plugin, "_services_open_item_map", service_item_map)
                try:
                    pass
                except Exception:
                    pass
            except Exception:
                pass
            custom_item = self.build_services_list_custom_item(plugin, activity)
            if custom_item is None:
                return
            items.add(insert_idx, custom_item)
        except Exception:
            pass

