    def run_internal_sync(self, plugin):
        try:
            required = (
                "_core_remote_fetch_json",
                "_refresh_release_notice_cache",
                "_refresh_remote_translations_pack",
                "_ensure_engine_installed",
                "_ensure_nowfy_installed",
                "_parse_version_tuple",
            )
            inst = None
            try:
                inst = self._resolve_core_instance()
            except Exception:
                inst = None
            try:
                if (inst is None) or (not all(hasattr(inst, k) for k in required)):
                    attach_host_plugin(plugin)
                    inst = self._resolve_core_instance()
            except Exception:
                pass
            if inst is not None and hasattr(inst, "_run_internal_sync") and callable(getattr(inst, "_run_internal_sync", None)):
                if all(hasattr(inst, k) for k in required):
                    inst._run_internal_sync()
                    return True
            if hasattr(plugin, "_run_internal_sync") and callable(getattr(plugin, "_run_internal_sync", None)):
                if all(hasattr(plugin, k) for k in required):
                    plugin._run_internal_sync()
                    return True
        except Exception:
            pass
        return False

    def run_release_notice(self, plugin):
        try:
            required = (
                "_refresh_release_notice_cache",
                "_get_release_notice_cached",
                "_extract_release_notice_entries",
                "_show_release_notice_bottom_sheet",
            )
            inst = None
            try:
                inst = self._resolve_core_instance()
            except Exception:
                inst = None
            try:
                if (inst is None) or (not all(hasattr(inst, k) for k in required)):
                    attach_host_plugin(plugin)
                    inst = self._resolve_core_instance()
            except Exception:
                pass
            if (inst is None) or (not all(hasattr(inst, k) for k in required)):
                return False
            data = None
            try:
                data = inst._refresh_release_notice_cache()
            except Exception:
                data = None
            if not isinstance(data, dict):
                try:
                    data = inst._get_release_notice_cached()
                except Exception:
                    data = None
            if not isinstance(data, dict):
                try:
                    BulletinHelper.show_info("Notice: no remote data")
                except Exception:
                    pass
                return False
            upd, note = inst._extract_release_notice_entries(data)
            entry = note if isinstance(note, dict) else upd
            kind = "note" if isinstance(note, dict) else "update"
            if not isinstance(entry, dict):
                try:
                    BulletinHelper.show_info("Notice: no entry")
                except Exception:
                    pass
                return False
            run_on_ui_thread(lambda: inst._show_release_notice_bottom_sheet(entry, kind=kind))
            return True
        except Exception:
            try:
                BulletinHelper.show_info("Notice: failed")
            except Exception:
                pass
            return False

