    def run_backup_file_restore(self, plugin, source_path):
        try:
            src = str(source_path or "").strip()
            if not src or (not src.lower().endswith(".nowfy")) or (not os.path.isfile(src)):
                return False
            required = ("restore_from_backup",)
            inst = None
            try:
                inst = self._resolve_core_instance()
            except Exception:
                inst = None
            try:
                if (inst is None) or (not all(hasattr(inst, k) for k in required)):
                    attach_host_plugin(plugin)
                    inst = self._resolve_core_instance()
            except Exception:
                pass
            if (inst is None) or (not all(hasattr(inst, k) for k in required)):
                return False
            def _do_restore():
                try:
                    bm = BackupManager(inst)
                    backup_dir = str(bm.backup_dir or "").strip()
                    if not backup_dir:
                        BulletinHelper.show_info("Backup unavailable")
                        return
                    try:
                        if not os.path.isdir(backup_dir):
                            os.makedirs(backup_dir)
                    except Exception:
                        pass
                    name = os.path.basename(src) or f"backup-{inst._get_backup_filename_stamp()}.nowfy"
                    if not name.lower().endswith(".nowfy"):
                        name = f"{name}.nowfy"
                    dest_path = os.path.join(backup_dir, name)
                    try:
                        same_file = os.path.abspath(src) == os.path.abspath(dest_path)
                    except Exception:
                        same_file = False
                    if not same_file:
                        base, ext = os.path.splitext(name)
                        i = 1
                        while os.path.exists(dest_path):
                            dest_path = os.path.join(backup_dir, f"{base}-{i}{ext}")
                            i += 1
                        with open(src, "rb") as rf:
                            payload = rf.read()
                        with open(dest_path, "wb") as wf:
                            wf.write(payload)
                    final_name = os.path.basename(dest_path)
                    if not final_name:
                        BulletinHelper.show_info("Backup unavailable")
                        return
                    inst.restore_from_backup(final_name)
                except Exception:
                    try:
                        BulletinHelper.show_info("Backup restore failed")
                    except Exception:
                        pass
            run_on_queue(_do_restore)
            return True
        except Exception:
            return False

    def _try_runtime_pip_update_nowfy(self, target_version=""):
        try:
            target = str(target_version or "").strip()
            spec_list = [f"nowfy=={target}"] if target else []
            spec_list.extend(["nowfy", "nowfy>=0"])
            wanted = self._parse_version_tuple(target) if target else ()
            notice_sent = False
            try:
                from pip._internal.cli.main import main as _pip_main
            except Exception:
                _pip_main = None
            if callable(_pip_main):
                for spec in spec_list:
                    if not notice_sent:
                        try:
                            BulletinHelper.show_info("Sync: downloading package")
                        except Exception:
                            pass
                        try:
                            self._sync_log(f"pip start spec={spec}")
                        except Exception:
                            pass
                        notice_sent = True
                    try:
                        rc = int(_pip_main(["install", "--upgrade", "--no-cache-dir", str(spec)]))
                    except Exception:
                        rc = 1
                    if rc != 0:
                        continue
                    cur = str(self._get_runtime_nowfy_pypi_version() or "")
                    if not cur:
                        continue
                    if wanted:
                        if self._parse_version_tuple(cur) >= wanted:
                            return True, ""
                    else:
                        return True, ""
            pip_class = find_class("com.exteragram.messenger.plugins.pip.PipController")
            if pip_class is None:
                return False, "pip_unavailable"
            inst = None
            try:
                for m in pip_class.getClass().getDeclaredMethods():
                    try:
                        if str(m.getName()) == "getInstance" and int(m.getParameterCount()) == 0:
                            m.setAccessible(True)
                            inst = m.invoke(None)
                            if inst:
                                break
                    except Exception:
                        pass
            except Exception:
                pass
            if inst is None:
                return False, "pip_instance_missing"
            methods = []
            try:
                for m in inst.getClass().getDeclaredMethods():
                    try:
                        name = str(m.getName())
                        if name in ("resolveAndInstall", "installPackage"):
                            methods.append(m)
                    except Exception:
                        pass
            except Exception:
                methods = []
            if not methods:
                return False, "pip_method_missing"
            launched = False
            for spec in spec_list:
                if launched:
                    break
                for m in methods:
                    if not notice_sent:
                        try:
                            BulletinHelper.show_info("Sync: downloading package")
                        except Exception:
                            pass
                        try:
                            self._sync_log(f"pipcontroller start spec={spec}")
                        except Exception:
                            pass
                        notice_sent = True
                    try:
                        m.setAccessible(True)
                    except Exception:
                        pass
                    try:
                        argc = int(m.getParameterCount())
                    except Exception:
                        argc = -1
                    call_args = []
                    if argc == 1:
                        call_args = [spec]
                    elif argc == 2:
                        call_args = [spec, None]
                    elif argc == 3:
                        call_args = [spec, None, None]
                    elif argc == 4:
                        call_args = [spec, None, None, None]
                    else:
                        continue
                    try:
                        m.invoke(inst, *call_args)
                        launched = True
                        break
                    except Exception:
                        continue
            if not launched:
                return False, "pip_invoke_failed"
            for _ in range(24):
                try:
                    time.sleep(0.5)
                except Exception:
                    pass
                cur = str(self._get_runtime_nowfy_pypi_version() or "")
                if not cur:
                    continue
                if wanted:
                    if self._parse_version_tuple(cur) >= wanted:
                        return True, ""
                else:
                    return True, ""
            return False, "pip_pending"
        except Exception:
            return False, "pip_exception"
        try:
            app_loader = plugin._resolve_class("org.telegram.messenger.ApplicationLoader")
            file_class = plugin._resolve_class("java.io.File")
            base_dir = app_loader.getFilesDirFixed()
            if base_dir:
                icon_dir = file_class(base_dir, "NowfyTabIcons")
                if icon_dir.exists():
                    try:
                        for f in icon_dir.listFiles():
                            try:
                                f.delete()
                            except Exception:
                                pass
                    except Exception:
                        pass
                    try:
                        icon_dir.delete()
                    except Exception:
                        pass
        except Exception:
            pass
        try:
            header_dirs = []
            try:
                cd = plugin._di_cache_dir()
                if cd:
                    header_dirs.append(str(cd))
            except Exception:
                pass
            try:
                app_loader = plugin._resolve_class("org.telegram.messenger.ApplicationLoader")
                bd = app_loader.getFilesDirFixed()
                if bd:
                    header_dirs.append(str(bd))
            except Exception:
                pass
            for d in header_dirs:
                try:
                    if not d or not os.path.isdir(d):
                        continue
                    for fname in os.listdir(d):
                        if fname.startswith("nowfy_header_cover_") and fname.endswith(".png"):
                            try:
                                os.remove(os.path.join(d, fname))
                            except Exception:
                                pass
                        if fname in ("nowfy_nowtab_header.png", "nowfy_services_header.png", "nowfy_themes_header.png"):
                            try:
                                os.remove(os.path.join(d, fname))
                            except Exception:
                                pass
                except Exception:
                    pass
        except Exception:
            pass

    def normalize_backend_base(self, base, default_base="https://nowfy.meyankut.workers.dev"):
        try:
            out = str(base or "").strip()
            if not out:
                out = str(default_base or "").strip()
            if not out:
                out = "https://nowfy.meyankut.workers.dev"
            if out.endswith("/"):
                out = out[:-1]
            return out
        except Exception:
            return "https://nowfy.meyankut.workers.dev"

