    def build_track_hub_subfragment_items(self, plugin):
        try:
            enabled = bool(plugin.get_setting("track_hub_enabled", False))
            items = [
                Divider(text=tr("track_hub_intro")),
                Switch(
                    key="track_hub_enabled",
                    text=tr("track_hub_enable"),
                    subtext=tr("track_hub_enable_sub"),
                    default=enabled,
                    icon="msg_openprofile",
                    on_change=lambda v: (
                        plugin.set_setting("track_hub_enabled", bool(v)),
                        (plugin._setup_track_hub_profile_hooks() if bool(v) else None),
                        (plugin._start_track_hub_worker() if bool(v) else plugin._stop_track_hub_worker()),
                        plugin.reload_settings()
                    ),
                    link_alias="nowfy_extended_track_hub_enabled"
                )
            ]
            if enabled:
                self.append_track_hub_style_selector(plugin, items)
                items.append(Divider(text=tr("track_hub_source_section")))
                srcs, labels = plugin._track_hub_get_source_options()
                if len(labels) > 1:
                    idx = int(plugin.get_setting("track_hub_source_idx", 0) or 0)
                    if idx < 0 or idx >= len(labels):
                        idx = 0
                    items.append(
                        Selector(
                            key="track_hub_source_idx",
                            text=tr("track_hub_source_label"),
                            default=idx,
                            items=labels,
                            icon="header_goinline_solar",
                            on_change=lambda v: (
                                plugin.set_setting("track_hub_source_idx", int(v)),
                                plugin._track_hub_publish_payload(),
                                plugin.reload_settings()
                            ),
                            link_alias="nowfy_extended_track_hub_source"
                        )
                    )
                else:
                    items.append(Divider(text=tr("track_hub_source_auto")))
            return items
        except Exception:
            return []

    def inject_track_hub_source_slide(self, plugin, activity, items):
        try:
            if not bool(plugin.get_setting("track_hub_enabled", False)):
                return
            sources, labels = plugin._track_hub_get_source_options()
            if len(labels) <= 1:
                return
            insert_idx = -1
            remove_indices = []
            for i in range(items.size()):
                try:
                    it = items.get(i)
                    key = plugin._get_uitem_setting_key(it)
                    if key == "track_hub_source_idx":
                        remove_indices.append(i)
                        if insert_idx < 0:
                            insert_idx = i
                except Exception:
                    pass
            if insert_idx < 0:
                return
            for idx in reversed(remove_indices):
                try:
                    items.remove(idx)
                except Exception:
                    pass
            try:
                current = int(plugin.get_setting("track_hub_source_idx", 0) or 0)
            except Exception:
                current = 0
            current = max(0, min(len(labels) - 1, current))
            CallbackInterface = Utilities.Callback
            String = jclass("java.lang.String")
            class _TrackHubSlideCallback(dynamic_proxy(CallbackInterface)):
                def run(self, value):
                    try:
                        v = int(value)
                    except Exception:
                        v = 0
                    v = max(0, min(len(labels) - 1, v))
                    try:
                        plugin.set_setting("track_hub_source_idx", v)
                        plugin._track_hub_publish_payload()
                    except Exception:
                        pass
            slide_items = jarray(String)(labels)
            items.add(insert_idx, UItem.asSlideView(slide_items, current, _TrackHubSlideCallback()))
            try:
                items.add(insert_idx + 1, UItem.asShadow())
            except Exception:
                pass
        except Exception:
            pass

