    def inject_custom_cover_selector(self, plugin, activity, items):
        try:
            from org.telegram.ui.Components import UItem
            from android_utils import OnClickListener, run_on_ui_thread
            from android.widget import LinearLayout, TextView
            from android.view import Gravity
            from android.util import TypedValue
            from android.graphics.drawable import GradientDrawable
            from org.telegram.messenger import AndroidUtilities
            from org.telegram.ui.ActionBar import Theme
            from hook_utils import get_private_field
            insert_idx = -1
            remove_indices = []
            for i in range(items.size()):
                try:
                    it = items.get(i)
                    key = plugin._get_uitem_setting_key(it)
                    if key == "custom_cover_selection":
                        remove_indices.append(i)
                        if insert_idx < 0:
                            insert_idx = i
                except Exception:
                    pass
            if insert_idx < 0:
                return
            for idx in reversed(remove_indices):
                try:
                    items.remove(idx)
                except Exception:
                    pass
            user_label = plugin._get_custom_cover_label() if hasattr(plugin, "_get_custom_cover_label") else "User's Cover"
            labels = ["Nowfy", user_label]
            try:
                current = int(self.get_core_setting("custom_cover_selection", plugin.get_setting("custom_cover_selection", 0)) or 0)
            except Exception:
                current = 0
            current = 1 if current == 1 else 0
            ctx = activity.getContext()
            wrap = LinearLayout(ctx)
            wrap.setOrientation(LinearLayout.VERTICAL)
            try:
                wrap.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(8), AndroidUtilities.dp(16), AndroidUtilities.dp(8))
            except Exception:
                pass
            title = TextView(ctx)
            title.setText(tr("nowfy_custom_cover_selector"))
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
            try:
                title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                title.setTextColor(0xFFFFFFFF)
            wrap.addView(title)
            row = LinearLayout(ctx)
            row.setOrientation(LinearLayout.HORIZONTAL)
            try:
                lp_row = LinearLayout.LayoutParams(-1, -2)
                lp_row.topMargin = AndroidUtilities.dp(8)
                row.setLayoutParams(lp_row)
            except Exception:
                pass
            try:
                bg = int(Theme.getColor(Theme.key_windowBackgroundWhite))
                r = (bg >> 16) & 0xFF
                g = (bg >> 8) & 0xFF
                b = bg & 0xFF
                is_dark_theme = (((r * 299 + g * 587 + b * 114) / 1000.0) < 150)
            except Exception:
                is_dark_theme = True
            def _btn_bg(selected):
                gd = GradientDrawable()
                try:
                    gd.setCornerRadius(AndroidUtilities.dp(12))
                except Exception:
                    pass
                if selected:
                    sel_bg = Color.parseColor("#3B82F6")
                    gd.setColor(sel_bg)
                    try:
                        gd.setStroke(AndroidUtilities.dp(1), sel_bg)
                    except Exception:
                        pass
                else:
                    if is_dark_theme:
                        gd.setColor(Color.parseColor("#242B36"))
                        try:
                            gd.setStroke(AndroidUtilities.dp(1), Color.parseColor("#30384A"))
                        except Exception:
                            pass
                    else:
                        gd.setColor(Color.parseColor("#E9EEF5"))
                        try:
                            gd.setStroke(AndroidUtilities.dp(1), Color.parseColor("#D1D9E6"))
                        except Exception:
                            pass
                return gd
            def _make_btn(text, selected):
                tv = TextView(ctx)
                tv.setText(str(text))
                tv.setGravity(Gravity.CENTER)
                tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
                try:
                    tv.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                except Exception:
                    pass
                try:
                    tv.setBackground(_btn_bg(bool(selected)))
                except Exception:
                    pass
                try:
                    tv.setMinHeight(AndroidUtilities.dp(42))
                    tv.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(10), AndroidUtilities.dp(12), AndroidUtilities.dp(10))
                except Exception:
                    pass
                try:
                    tv.setTextColor(Color.parseColor("#FFFFFF" if selected else ("#F2F5FA" if is_dark_theme else "#1B2330")))
                except Exception:
                    pass
                return tv
            btn_nowfy = _make_btn(labels[0], current == 0)
            btn_user = _make_btn(labels[1], current == 1)
            def _paint_state(sel_idx):
                try:
                    btn_nowfy.setBackground(_btn_bg(sel_idx == 0))
                    btn_user.setBackground(_btn_bg(sel_idx == 1))
                    btn_nowfy.setTextColor(Color.parseColor("#FFFFFF" if sel_idx == 0 else ("#F2F5FA" if is_dark_theme else "#1B2330")))
                    btn_user.setTextColor(Color.parseColor("#FFFFFF" if sel_idx == 1 else ("#F2F5FA" if is_dark_theme else "#1B2330")))
                except Exception:
                    pass
            def _apply_select(v):
                try:
                    vv = 0 if int(v) <= 0 else 1
                except Exception:
                    vv = 0
                _paint_state(vv)
                try:
                    self.on_custom_cover_select(plugin, vv)
                except Exception:
                    pass
                try:
                    lv = get_private_field(activity, "listView")
                    if lv is not None and getattr(lv, "adapter", None) is not None:
                        self._queue_adapter_update(plugin, lv, channel="custom_cover_select")
                except Exception:
                    pass
            btn_nowfy.setOnClickListener(OnClickListener(lambda v: _apply_select(0)))
            btn_user.setOnClickListener(OnClickListener(lambda v: _apply_select(1)))
            _paint_state(current)
            try:
                lp_a = LinearLayout.LayoutParams(0, -2, 1.0)
                lp_b = LinearLayout.LayoutParams(0, -2, 1.0)
                lp_b.leftMargin = AndroidUtilities.dp(8)
                row.addView(btn_nowfy, lp_a)
                row.addView(btn_user, lp_b)
            except Exception:
                row.addView(btn_nowfy)
                row.addView(btn_user)
            wrap.addView(row)
            items.add(insert_idx, UItem.asCustom(wrap))
            try:
                items.add(insert_idx + 1, UItem.asShadow())
            except Exception:
                pass
        except Exception:
            pass

