    def inject_about_support_rich_header(self, plugin, activity, items):
        try:
            if activity is None or items is None:
                return
            desc_txt = ""
            try:
                desc_txt = str(plugin.tr("about_plugin_description"))
            except Exception:
                try:
                    desc_txt = str(tr("about_plugin_description"))
                except Exception:
                    desc_txt = ""
            remove_idxs = []
            for i in range(items.size()):
                try:
                    it = items.get(i)
                    txt = ""
                    try:
                        txt = str(plugin._get_uitem_text(it) or "").strip()
                    except Exception:
                        txt = ""
                    if desc_txt and txt == desc_txt:
                        remove_idxs.append(i)
                except Exception:
                    pass
            for i in reversed(remove_idxs):
                try:
                    items.remove(i)
                except Exception:
                    pass
            rich_item = self.build_support_project_rich_item(plugin, desc_txt)
            if rich_item is not None:
                try:
                    rich_item.object2 = "__about_support_rich__"
                except Exception:
                    pass
                try:
                    items.add(0, rich_item)
                except Exception:
                    items.add(rich_item)
        except Exception:
            pass

