    def apply_spotify_profile_cache(self, plugin, profile):
        try:
            if not isinstance(profile, dict):
                return False
            display = str(profile.get("display_name", "") or profile.get("id", "") or "")
            pid = str(profile.get("id", "") or "")
            followers = int(profile.get("followers", 0) or 0)
            country = str(profile.get("country", "") or "")
            product = str(profile.get("product", "") or "")
            image_url = str(profile.get("profile_image_url", "") or "")
            plugin.set_setting("spotify_cached_display_name", display)
            plugin.set_setting("spotify_cached_id", pid)
            plugin.set_setting("spotify_cached_followers", followers)
            plugin.set_setting("spotify_cached_country", country)
            plugin.set_setting("spotify_cached_product", product)
            plugin.set_setting("spotify_cached_profile_image_url", image_url)
            plugin.set_setting("spotify_cached_ts", str(int(time.time())))
            return True
        except Exception:
            return False

    def get_quick_spotify_backend_base(self, plugin):
        try:
            base = str(plugin.get_setting("quick_spotify_backend_base", "") or "").strip()
            if not base:
                try:
                    base = str(plugin._core_pack_get_value("spotify_backend_base", "") or "").strip()
                except Exception:
                    pass
            if not base:
                base = "https://nowfy.meyankut.workers.dev"
            return self.normalize_backend_base(base, "https://nowfy.meyankut.workers.dev")
        except Exception:
            return "https://nowfy.meyankut.workers.dev"

    def cache_spotify_profile_from_token(self, plugin, token):
        try:
            tk = str(token or "").strip()
            if not tk:
                return False
            resp = requests.get(
                "https://api.spotify.com/v1/me",
                headers={"Authorization": f"Bearer {tk}"},
                timeout=8
            )
            if resp.status_code != 200 or not resp.content:
                return False
            data = resp.json()
            images = data.get("images", []) if isinstance(data, dict) else []
            profile = {
                "display_name": str(data.get("display_name", "") or data.get("id", "") or ""),
                "id": str(data.get("id", "") or ""),
                "followers": int((data.get("followers") or {}).get("total", 0) or 0),
                "country": str(data.get("country", "") or ""),
                "product": str(data.get("product", "") or ""),
                "profile_image_url": str((images[0] or {}).get("url") or "") if images else "",
            }
            return self.apply_spotify_profile_cache(plugin, profile)
        except Exception:
            return False

    def exchange_code(self, plugin, code):
        code = str(code or "").strip()
        if not code:
            return False, "Código inválido"
        backend_error = None
        try:
            backend_base = self.get_quick_spotify_backend_base(plugin)
            resp = requests.post(
                f"{backend_base}/auth/spotify/exchange",
                json={"code": code},
                timeout=10
            )
            if resp.status_code == 200 and resp.content:
                data = resp.json()
                refresh_token = data.get("refresh_token", "")
                access_token = data.get("access_token", "")
                expires_in = int(data.get("expires_in", 3600))
                profile = data.get("profile") if isinstance(data, dict) else None
                if refresh_token:
                    try:
                        plugin.set_setting("quick_spotify_auth_enabled", True)
                        plugin.set_setting("quick_refresh_token", refresh_token)
                        if access_token:
                            plugin.set_setting("access_token", access_token)
                            plugin.set_setting("token_expiry", str(int(time.time()) + max(300, expires_in)))
                    except Exception:
                        pass
                    if isinstance(profile, dict):
                        self.apply_spotify_profile_cache(plugin, profile)
                    return True, None
                backend_error = "Sem refresh_token no backend"
            elif int(resp.status_code or 0) == 404:
                backend_error = "Código não encontrado ou expirado"
            else:
                backend_error = f"Erro do backend ({resp.status_code})"
        except Exception as e:
            backend_error = str(e)
        client_id = str(plugin.get_setting("client_id", "") or "").strip()
        client_secret = str(plugin.get_setting("client_secret", "") or "").strip()
        if not client_id or not client_secret:
            return False, backend_error or "Client ID/Secret ausentes"
        try:
            auth = base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()
            resp = requests.post(
                "https://accounts.spotify.com/api/token",
                data={
                    "grant_type": "authorization_code",
                    "code": code,
                    "redirect_uri": "https://example.com/callback"
                },
                headers={"Authorization": f"Basic {auth}"},
                timeout=10
            )
            if resp.status_code != 200:
                try:
                    err = resp.json() if resp.content else {}
                except Exception:
                    err = {}
                err_msg = str(err.get("error_description") or err.get("error") or f"Spotify API Error {resp.status_code}")
                if backend_error:
                    return False, f"{backend_error} | {err_msg}"
                return False, err_msg
            data = resp.json()
            refresh_token = str(data.get("refresh_token", "") or "").strip()
            access_token = str(data.get("access_token", "") or "").strip()
            expires_in = int(data.get("expires_in", 3600) or 3600)
            if not refresh_token:
                return False, "Sem refresh_token na resposta do Spotify"
            try:
                plugin.set_setting("refresh_token", refresh_token)
                if access_token:
                    plugin.set_setting("access_token", access_token)
                    plugin.set_setting("token_expiry", str(int(time.time()) + max(300, expires_in)))
            except Exception:
                pass
            if access_token:
                try:
                    self.cache_spotify_profile_from_token(plugin, access_token)
                except Exception:
                    pass
            return True, None
        except Exception as e:
            if backend_error:
                return False, f"{backend_error} | {str(e)}"
            return False, str(e)

    def get_access_token(self, plugin, show_error_bulletin=False):
        client_id = plugin.get_setting("client_id", "")
        client_secret = plugin.get_setting("client_secret", "")
        refresh_token = plugin.get_setting("refresh_token", "")
        try:
            cached = plugin.get_setting("access_token", "")
            expiry = int(plugin.get_setting("token_expiry", "0") or 0)
            now_ts = int(time.time())
            if cached and expiry and (expiry - 60) > now_ts:
                return cached
        except Exception:
            pass
        try:
            quick_refresh = str(plugin.get_setting("quick_refresh_token", "") or "").strip()
            if quick_refresh:
                backend_base = self.get_quick_spotify_backend_base(plugin)
                resp = requests.post(
                    f"{backend_base}/auth/spotify/refresh",
                    json={"refresh_token": quick_refresh},
                    timeout=6
                )
                if resp.status_code == 200 and resp.content:
                    data = resp.json()
                    access_token = data.get("access_token")
                    expires_in = int(data.get("expires_in", 3600))
                    new_refresh = data.get("refresh_token") or quick_refresh
                    profile = data.get("profile") if isinstance(data, dict) else None
                    if access_token:
                        try:
                            plugin.set_setting("quick_spotify_auth_enabled", True)
                            plugin.set_setting("access_token", access_token)
                            plugin.set_setting("token_expiry", str(int(time.time()) + max(300, expires_in)))
                            plugin.set_setting("quick_refresh_token", new_refresh)
                        except Exception:
                            pass
                        if isinstance(profile, dict):
                            self.apply_spotify_profile_cache(plugin, profile)
                        return access_token
        except Exception:
            pass
        if not str(plugin.get_setting("quick_refresh_token", "") or "").strip() and (not client_id or not client_secret or not refresh_token):
            return None
        try:
            if str(plugin.get_setting("quick_refresh_token", "") or "").strip():
                return None
            auth = base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()
            resp = requests.post(
                "https://accounts.spotify.com/api/token",
                data={"grant_type": "refresh_token", "refresh_token": refresh_token},
                headers={"Authorization": f"Basic {auth}"},
                timeout=5
            )
            if resp.status_code != 200:
                return None
            data = resp.json()
            access_token = data.get("access_token")
            if access_token:
                try:
                    expires_in = int(data.get("expires_in", 3600))
                except Exception:
                    expires_in = 3600
                try:
                    plugin.set_setting("access_token", access_token)
                    plugin.set_setting("token_expiry", str(int(time.time()) + max(300, expires_in)))
                except Exception:
                    pass
            return access_token
        except Exception:
            return None

    def get_spotify_user_profile(self, plugin):
        def _cached():
            try:
                name = str(plugin.get_setting("spotify_cached_display_name", "") or "").strip()
                pid = str(plugin.get_setting("spotify_cached_id", "") or "").strip()
                product = str(plugin.get_setting("spotify_cached_product", "") or "").strip()
                image = str(plugin.get_setting("spotify_cached_profile_image_url", "") or "").strip()
                followers = int(plugin.get_setting("spotify_cached_followers", 0) or 0)
                if not name and not pid:
                    return None
                return {
                    "display_name": name or pid,
                    "id": pid,
                    "followers": followers,
                    "country": str(plugin.get_setting("spotify_cached_country", "") or "").strip(),
                    "product": product,
                    "images": ([{"url": image}] if image else []),
                    "profile_image_url": image,
                }
            except Exception:
                return None
        try:
            token = self.get_access_token(plugin, show_error_bulletin=False)
            if not token:
                return _cached()
            resp = requests.get(
                "https://api.spotify.com/v1/me",
                headers={"Authorization": f"Bearer {token}"},
                timeout=8
            )
            if resp.status_code == 200 and resp.content:
                data = resp.json()
                images = data.get("images", []) if isinstance(data, dict) else []
                profile = {
                    "display_name": str(data.get("display_name", "") or data.get("id", "") or ""),
                    "id": str(data.get("id", "") or ""),
                    "followers": int((data.get("followers") or {}).get("total", 0) or 0),
                    "country": str(data.get("country", "") or ""),
                    "product": str(data.get("product", "") or ""),
                    "profile_image_url": str((images[0] or {}).get("url") or "") if images else "",
                }
                self.apply_spotify_profile_cache(plugin, profile)
                return {
                    "display_name": profile["display_name"],
                    "id": profile["id"],
                    "followers": profile["followers"],
                    "country": profile["country"],
                    "product": profile["product"],
                    "images": ([{"url": profile["profile_image_url"]}] if profile["profile_image_url"] else []),
                    "profile_image_url": profile["profile_image_url"],
                }
            return _cached()
        except Exception as e:
            try:
                pass
            except Exception:
                pass
            return _cached()

