    def _ymusic_format_ms(self, value):
        try:
            ms = int(value or 0)
        except Exception:
            ms = 0
        if ms < 0:
            ms = 0
        total = ms // 1000
        h = total // 3600
        m = (total % 3600) // 60
        s = total % 60
        if h > 0:
            return f"{h}:{m:02d}:{s:02d}"
        return f"{m}:{s:02d}"

    def _ymusic_diag(self, message, cooldown_sec=20):
        try:
            msg = str(message or "").strip()
            if not msg:
                return
            try:
                self._log_throttled("ymusic_diag", f"[Nowfy][YMusic] {msg}", cooldown_sec=int(cooldown_sec))
            except Exception:
                try:
                    self._nlog(f"[Nowfy][YMusic] {msg}")
                except Exception:
                    pass
            try:
                _capture_error_log(f"[Nowfy][YMusic] detection failed: {msg}")
            except Exception:
                pass
        except Exception:
            pass

    def _ymusic_get_notification_listener_component(self, ctx):
        try:
            if ctx is None:
                return None
            resolver = ctx.getContentResolver()
            if resolver is None:
                return None
            raw = Settings.Secure.getString(resolver, "enabled_notification_listeners")
            if not raw:
                return None
            pkg = str(ctx.getPackageName() or "").strip()
            if not pkg:
                return None
            for part in str(raw).split(":"):
                try:
                    flat = str(part or "").strip()
                    if not flat:
                        continue
                    comp = ComponentName.unflattenFromString(flat)
                    if comp is None:
                        continue
                    cpkg = str(comp.getPackageName() or "").strip()
                    if cpkg == pkg:
                        return comp
                except Exception:
                    pass
        except Exception:
            pass
        return None

    def _ymusic_api_get_json(self, token, path, params=None, timeout=6, cookie="", extra_headers=None):
        try:
            tk = str(token or "").strip()
            ck = self._ymusic_normalize_cookie(cookie)
            p = str(path or "").strip()
            if (not tk and not ck) or not p:
                return None
            if not p.startswith("/"):
                p = "/" + p
            url = f"https://api.music.yandex.net{p}"
            headers = {
                "Accept": "application/json",
                "User-Agent": "Nowfy/1.0",
                "X-Yandex-Music-Client": "YandexMusicAndroid/24023621",
            }
            if tk:
                headers["Authorization"] = f"OAuth {tk}"
            if ck:
                headers["Cookie"] = ck
            if isinstance(extra_headers, dict):
                for k, v in extra_headers.items():
                    ks = str(k or "").strip()
                    vs = str(v or "").strip()
                    if ks and vs:
                        headers[ks] = vs
            resp = requests.get(url, headers=headers, params=params or None, timeout=timeout)
            if resp.status_code != 200 or not resp.content:
                return None
            data = resp.json()
            if not isinstance(data, dict):
                return None
            if "result" in data and isinstance(data.get("result"), (dict, list)):
                return data.get("result")
            return data
        except Exception:
            return None

    def _ymusic_api_post_json(self, token, path, data=None, params=None, timeout=6, cookie="", extra_headers=None):
        try:
            tk = str(token or "").strip()
            ck = self._ymusic_normalize_cookie(cookie)
            p = str(path or "").strip()
            if (not tk and not ck) or not p:
                return None
            if not p.startswith("/"):
                p = "/" + p
            url = f"https://api.music.yandex.net{p}"
            headers = {
                "Accept": "application/json",
                "User-Agent": "Nowfy/1.0",
                "X-Yandex-Music-Client": "YandexMusicAndroid/24023621",
            }
            if tk:
                headers["Authorization"] = f"OAuth {tk}"
            if ck:
                headers["Cookie"] = ck
            if isinstance(extra_headers, dict):
                for k, v in extra_headers.items():
                    ks = str(k or "").strip()
                    vs = str(v or "").strip()
                    if ks and vs:
                        headers[ks] = vs
            resp = requests.post(url, headers=headers, params=params or None, data=data or None, timeout=timeout)
            if resp.status_code != 200 or not resp.content:
                return None
            payload = resp.json()
            if not isinstance(payload, dict):
                return None
            if "result" in payload and isinstance(payload.get("result"), (dict, list)):
                return payload.get("result")
            return payload
        except Exception:
            return None

    def _ymusic_device_header_value(self):
        try:
            return "os=Android; os_version=16; manufacturer=Nowfy; model=NowfyPlugin; clid=; device_id=nowfy; uuid=nowfy"
        except Exception:
            return "os=Android; device_id=nowfy"

    def _ymusic_custom_api_url(self, plugin):
        try:
            v = str(plugin.get_setting("ymusic_custom_api_url", "") or "").strip()
        except Exception:
            v = ""
        if not v:
            return "https://track.mipoh.ru"
        return v.rstrip("/")

    def _ymusic_normalize_cookie(self, cookie):
        try:
            ck = str(cookie or "").strip()
            if not ck:
                return ""
            if "=" in ck:
                return ck
            return f"Session_id={ck}"
        except Exception:
            return ""

    def _ymusic_cover_url(self, cover_uri):
        try:
            c = str(cover_uri or "").strip()
            if not c:
                return ""
            if c.startswith("http://") or c.startswith("https://"):
                return c
            c = c.replace("%%", "400x400")
            if c.startswith("//"):
                return "https:" + c
            return "https://" + c.lstrip("/")
        except Exception:
            return ""

    def _read_ymusic_custom_api_now_playing(self, plugin):
        out = {
            "has_session": False,
            "is_playing": False,
            "title": "",
            "artist": "",
            "album": "",
            "duration_ms": 0,
            "position_ms": 0,
            "player": "YMusic",
            "package_name": "com.yandex.music",
            "track_obj": None,
        }
        try:
            token = str(plugin.get_setting("ymusic_api_token", "") or "").strip()
        except Exception:
            token = ""
        if not token:
            return out
        api_url = self._ymusic_custom_api_url(plugin)
        headers = {
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json",
            "ya-token": token,
        }
        try:
            resp = requests.get(f"{api_url}/get_current_track_beta", headers=headers, timeout=10, verify=False)
            if int(resp.status_code or 0) != 200 or not resp.content:
                return out
            body = resp.json()
            if not isinstance(body, dict):
                return out
            track = body.get("track") if isinstance(body.get("track"), dict) else None
            if not isinstance(track, dict):
                return out
            title = str(track.get("title") or "").strip()
            artist_raw = track.get("artist")
            if isinstance(artist_raw, str):
                artist = ", ".join([a.strip() for a in artist_raw.split(",") if a and a.strip()])
            elif isinstance(artist_raw, list):
                artist = ", ".join([str(a).strip() for a in artist_raw if str(a).strip()])
            else:
                artist = ""
            album = str(track.get("album") or "").strip()
            cover_url = str(track.get("img") or "").strip()
            tid = str(track.get("track_id") or "").strip()
            try:
                duration_ms = int(float(track.get("duration") or 0) * 1000.0)
            except Exception:
                duration_ms = 0
            try:
                position_ms = int(body.get("progress_ms") or 0)
            except Exception:
                position_ms = 0
            track_obj = {
                "id": tid,
                "name": title,
                "artists": ([{"name": x.strip()} for x in artist.split(",")] if artist else []),
                "album": {"name": album, "images": ([{"url": cover_url}] if cover_url else [])},
                "external_urls": {"spotify": (f"https://music.yandex.ru/track/{tid}" if tid else None)},
                "duration_ms": max(0, int(duration_ms or 0)),
                "image_url": cover_url,
                "cover_url": cover_url,
            }
            out.update({
                "has_session": bool(title and artist),
                "is_playing": bool(title and artist),
                "title": title,
                "artist": artist,
                "album": album,
                "duration_ms": max(0, int(duration_ms or 0)),
                "position_ms": max(0, int(position_ms or 0)),
                "track_obj": track_obj,
            })
            return out
        except Exception:
            return out

    def _ymusic_extract_track_obj(self, track):
        try:
            if not isinstance(track, dict):
                return None
            title = str(track.get("title") or track.get("name") or "").strip()
            if not title:
                return None
            artists = []
            try:
                arr = track.get("artists") if isinstance(track.get("artists"), list) else []
                for a in arr:
                    if isinstance(a, dict):
                        n = str(a.get("name") or "").strip()
                        if n:
                            artists.append({"name": n})
                    else:
                        n = str(a or "").strip()
                        if n:
                            artists.append({"name": n})
            except Exception:
                artists = []
            album_name = ""
            album_images = []
            try:
                albums = track.get("albums") if isinstance(track.get("albums"), list) else []
                if albums:
                    a0 = albums[0] if isinstance(albums[0], dict) else {}
                    album_name = str(a0.get("title") or "").strip()
                    cu = self._ymusic_cover_url(a0.get("coverUri") or a0.get("cover_uri") or "")
                    if cu:
                        album_images = [{"url": cu, "width": 400, "height": 400}]
            except Exception:
                album_images = []
            if not album_images:
                try:
                    cu2 = self._ymusic_cover_url(track.get("coverUri") or track.get("cover_uri") or "")
                    if cu2:
                        album_images = [{"url": cu2, "width": 400, "height": 400}]
                except Exception:
                    pass
            duration_ms = 0
            try:
                duration_ms = int(track.get("durationMs") or track.get("duration_ms") or 0)
            except Exception:
                duration_ms = 0
            track_id = ""
            try:
                tid = track.get("id")
                aid = track.get("albumId") or track.get("album_id")
                if tid is not None and aid is not None:
                    track_id = f"{tid}:{aid}"
                elif tid is not None:
                    track_id = str(tid)
            except Exception:
                track_id = ""
            return {
                "id": track_id,
                "name": title,
                "artists": artists,
                "album": {"name": album_name, "images": album_images},
                "external_urls": {"spotify": None},
                "duration_ms": max(0, int(duration_ms or 0))
            }
        except Exception:
            return None

    def _get_ymusic_current_track(self):
        try:
            token = str(self.get_setting("ymusic_api_token", "") or "").strip()
        except Exception:
            token = ""
        if not token:
            return None

        def _build_track_from_panel_data(data):
            try:
                if not isinstance(data, dict):
                    return None
                if not bool(data.get("has_session")):
                    return None
                title = str(data.get("title") or "").strip()
                artist_text = str(data.get("artist") or "").strip()
                if not title:
                    return None
                artists = []
                if artist_text:
                    for part in artist_text.split(","):
                        n = str(part or "").strip()
                        if n:
                            artists.append({"name": n})
                album_name = str(data.get("album") or "").strip()
                duration_ms = 0
                try:
                    duration_ms = int(data.get("duration_ms") or 0)
                except Exception:
                    duration_ms = 0
                position_ms = 0
                try:
                    position_ms = int(data.get("position_ms") or 0)
                except Exception:
                    position_ms = 0

                track_obj = data.get("track_obj") if isinstance(data.get("track_obj"), dict) else None
                if isinstance(track_obj, dict) and str(track_obj.get("name") or "").strip():
                    out = dict(track_obj)
                    out["source"] = "ymusic"
                    out["progress_ms"] = max(0, int(position_ms or 0))
                    return out

                cover_url = ""
                try:
                    cover_url = str(data.get("cover_url") or data.get("image_url") or "").strip()
                except Exception:
                    cover_url = ""
                if not cover_url and isinstance(track_obj, dict):
                    try:
                        alb = track_obj.get("album") if isinstance(track_obj.get("album"), dict) else {}
                        imgs = alb.get("images") if isinstance(alb.get("images"), list) else []
                        if imgs and isinstance(imgs[0], dict):
                            cover_url = str(imgs[0].get("url") or "").strip()
                    except Exception:
                        cover_url = ""

                tid = ""
                if isinstance(track_obj, dict):
                    try:
                        tid = str(track_obj.get("id") or "").strip().split(":")[0]
                    except Exception:
                        tid = ""
                link = f"https://music.yandex.ru/track/{tid}" if tid else None
                return {
                    "name": title,
                    "artists": artists,
                    "album": {"name": album_name, "images": ([{"url": cover_url}] if cover_url else [])},
                    "external_urls": {"spotify": link},
                    "duration_ms": max(0, int(duration_ms or 0)),
                    "source": "ymusic",
                    "progress_ms": max(0, int(position_ms or 0)),
                }
            except Exception:
                return None

        try:
            api_data = self._read_ymusic_api_now_playing(self)
        except Exception:
            api_data = None
        track = _build_track_from_panel_data(api_data)
        if isinstance(track, dict):
            try:
                self._nlog("[Nowfy][YMusic] current track via official api")
            except Exception:
                pass
            return track

        try:
            custom_data = self._read_ymusic_custom_api_now_playing(self)
        except Exception:
            custom_data = None
        track = _build_track_from_panel_data(custom_data)
        if isinstance(track, dict):
            try:
                self._nlog("[Nowfy][YMusic] current track via custom api fallback")
            except Exception:
                pass
            return track

        try:
            rotor_data = self._ymusic_read_from_rotor_status(token)
        except Exception:
            rotor_data = None
        track = _build_track_from_panel_data(rotor_data)
        if isinstance(track, dict):
            try:
                self._nlog("[Nowfy][YMusic] current track via rotor fallback")
            except Exception:
                pass
            return track

        try:
            session_data = self._read_ymusic_media_session(self)
        except Exception:
            session_data = None
        track = _build_track_from_panel_data(session_data)
        if isinstance(track, dict):
            try:
                self._nlog("[Nowfy][YMusic] current track via media session fallback")
            except Exception:
                pass
            return track
        return None

    def _read_ymusic_api_now_playing(self, plugin):
        out = {
            "has_session": False,
            "is_playing": False,
            "title": "",
            "artist": "",
            "album": "",
            "duration_ms": 0,
            "position_ms": 0,
            "player": "YMusic",
            "package_name": "com.yandex.music",
            "track_obj": None,
        }
        try:
            token = ""
            try:
                token = str(plugin.get_setting("ymusic_api_token", "") or "").strip()
            except Exception:
                token = ""
            if not token:
                return out
            device_header = {"X-Yandex-Music-Device": self._ymusic_device_header_value()}
            queues_payload = self._ymusic_api_get_json(
                token, "/queues", timeout=8, extra_headers=device_header
            )
            queues = []
            if isinstance(queues_payload, dict):
                raw_q = queues_payload.get("queues")
                if isinstance(raw_q, list):
                    queues = raw_q
            elif isinstance(queues_payload, list):
                queues = queues_payload
            if not queues:
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                rotor = self._ymusic_read_from_rotor_status(token)
                return rotor if isinstance(rotor, dict) else out
            queue_id = ""
            try:
                best = None
                best_mod = ""
                for q in queues:
                    if not isinstance(q, dict):
                        continue
                    qid = str(q.get("id") or "").strip()
                    if not qid:
                        continue
                    mod = str(q.get("modified") or "").strip()
                    if (best is None) or (mod > best_mod):
                        best = q
                        best_mod = mod
                if isinstance(best, dict):
                    queue_id = str(best.get("id") or "").strip()
            except Exception:
                queue_id = ""
            if not queue_id:
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                rotor = self._ymusic_read_from_rotor_status(token)
                return rotor if isinstance(rotor, dict) else out
            queue_payload = self._ymusic_api_get_json(
                token, f"/queues/{queue_id}", timeout=8, extra_headers=device_header
            )
            if not isinstance(queue_payload, dict):
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                return out
            tracks_arr = queue_payload.get("tracks") if isinstance(queue_payload.get("tracks"), list) else []
            if not tracks_arr:
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                return out
            player_state = queue_payload.get("playerState") if isinstance(queue_payload.get("playerState"), dict) else {}
            if not isinstance(player_state, dict):
                player_state = {}
            idx = 0
            try:
                idx = int(queue_payload.get("currentIndex") or queue_payload.get("current_index") or 0)
            except Exception:
                idx = 0
            if idx < 0:
                idx = 0
            if idx >= len(tracks_arr):
                idx = len(tracks_arr) - 1
            current_track_ref = queue_payload.get("currentTrack") if isinstance(queue_payload.get("currentTrack"), dict) else queue_payload.get("current_track")
            track_ref = None
            if isinstance(current_track_ref, dict):
                try:
                    cur_idx = int(
                        current_track_ref.get("index")
                        or current_track_ref.get("currentIndex")
                        or current_track_ref.get("trackIndex")
                        or idx
                    )
                    if 0 <= cur_idx < len(tracks_arr):
                        idx = cur_idx
                except Exception:
                    pass
            track_ref = tracks_arr[idx] if 0 <= idx < len(tracks_arr) else None
            if not isinstance(track_ref, dict):
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                rotor = self._ymusic_read_from_rotor_status(token)
                return rotor if isinstance(rotor, dict) else out
            tid = str(track_ref.get("id") or "").strip()
            if not tid and isinstance(current_track_ref, dict):
                try:
                    tid = str(
                        current_track_ref.get("id")
                        or current_track_ref.get("trackId")
                        or current_track_ref.get("track_id")
                        or ""
                    ).strip()
                except Exception:
                    tid = ""
            if not tid:
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                rotor = self._ymusic_read_from_rotor_status(token)
                return rotor if isinstance(rotor, dict) else out
            tracks_data = self._ymusic_api_post_json(
                token,
                "/tracks",
                data={"track-ids": tid, "with-positions": "true"},
                timeout=8,
                extra_headers=device_header,
            )
            track_obj_raw = None
            if isinstance(tracks_data, list) and tracks_data:
                if isinstance(tracks_data[0], dict):
                    track_obj_raw = tracks_data[0]
            elif isinstance(tracks_data, dict):
                if isinstance(tracks_data.get("track"), dict):
                    track_obj_raw = tracks_data.get("track")
            if not isinstance(track_obj_raw, dict):
                custom = self._read_ymusic_custom_api_now_playing(plugin)
                if isinstance(custom, dict) and custom.get("has_session") and str(custom.get("title") or "").strip():
                    return custom
                rotor = self._ymusic_read_from_rotor_status(token)
                return rotor if isinstance(rotor, dict) else out
            tobj = self._ymusic_extract_track_obj(track_obj_raw)
            if not isinstance(tobj, dict):
                return out
            pos_ms = 0
            dur_ms = 0
            is_playing = True
            try:
                pos_ms = int(
                    player_state.get("progressMs")
                    or player_state.get("positionMs")
                    or player_state.get("playedMs")
                    or player_state.get("position")
                    or 0
                )
            except Exception:
                pos_ms = 0
            try:
                state_raw = str(player_state.get("status") or player_state.get("state") or "").strip().lower()
                if state_raw in ("paused", "stopped", "stop", "idle"):
                    is_playing = False
            except Exception:
                pass
            try:
                dur_ms = int((tobj.get("duration_ms") or 0))
            except Exception:
                dur_ms = 0
            try:
                title = str(tobj.get("name") or "").strip()
                artists = tobj.get("artists") if isinstance(tobj.get("artists"), list) else []
                artist = ", ".join([str((a or {}).get("name") or "").strip() for a in artists if isinstance(a, dict)]).strip()
                album = str(((tobj.get("album") or {}).get("name") or "")).strip()
            except Exception:
                title, artist, album = "", "", ""
            out.update({
                "has_session": True,
                "is_playing": bool(is_playing),
                "title": title,
                "artist": artist,
                "album": album,
                "duration_ms": max(0, int(dur_ms or 0)),
                "position_ms": max(0, int(pos_ms or 0)),
                "track_obj": tobj,
            })
            return out
        except Exception:
            return out

    def _ymusic_read_from_rotor_status(self, token, cookie=""):
        out = {
            "has_session": False,
            "is_playing": False,
            "title": "",
            "artist": "",
            "album": "",
            "duration_ms": 0,
            "position_ms": 0,
            "player": "YMusic",
            "package_name": "com.yandex.music",
            "track_obj": None,
        }
        try:
            status = self._ymusic_api_get_json(token, "/rotor/account/status", cookie=cookie, timeout=8)
            if not isinstance(status, dict):
                return out
            track = None
            if isinstance(status.get("track"), dict):
                track = status.get("track")
            if track is None:
                itm = status.get("item")
                if isinstance(itm, dict) and isinstance(itm.get("track"), dict):
                    track = itm.get("track")
            if not isinstance(track, dict):
                return out
            tobj = self._ymusic_extract_track_obj(track)
            if not isinstance(tobj, dict):
                return out
            pos_ms = 0
            is_playing = True
            st = status.get("playerState") if isinstance(status.get("playerState"), dict) else {}
            if isinstance(st, dict):
                try:
                    pos_ms = int(st.get("progressMs") or st.get("positionMs") or st.get("playedMs") or 0)
                except Exception:
                    pos_ms = 0
                try:
                    is_playing = str(st.get("status") or "").lower() not in ("paused", "stopped")
                except Exception:
                    is_playing = True
            title = str(tobj.get("name") or "").strip()
            artists = tobj.get("artists") if isinstance(tobj.get("artists"), list) else []
            artist = ", ".join([str((a or {}).get("name") or "").strip() for a in artists if isinstance(a, dict)]).strip()
            album = str(((tobj.get("album") or {}).get("name") or "")).strip()
            dur_ms = 0
            try:
                dur_ms = int(tobj.get("duration_ms") or 0)
            except Exception:
                dur_ms = 0
            out.update({
                "has_session": True,
                "is_playing": bool(is_playing),
                "title": title,
                "artist": artist,
                "album": album,
                "duration_ms": max(0, int(dur_ms or 0)),
                "position_ms": max(0, int(pos_ms or 0)),
                "track_obj": tobj,
            })
            return out
        except Exception:
            return out

    def _ymusic_save_bitmap_png(self, bmp):
        fos = None
        try:
            if bmp is None:
                return ""
            base = ApplicationLoader.getFilesDirFixed()
            if hasattr(base, "getAbsolutePath"):
                base = base.getAbsolutePath()
            out_dir = os.path.join(str(base), "nowfy", "ymusic")
            try:
                os.makedirs(out_dir, exist_ok=True)
            except Exception:
                pass
            out_path = os.path.join(out_dir, "now_playing.png")
            fos = FileOutputStream(out_path)
            fmt = jclass("android.graphics.Bitmap$CompressFormat").PNG
            ok = bool(bmp.compress(fmt, 100, fos))
            try:
                fos.flush()
            except Exception:
                pass
            if ok and os.path.isfile(out_path):
                return out_path
        except Exception:
            return ""
        finally:
            try:
                if fos is not None:
                    fos.close()
            except Exception:
                pass
        return ""

    def _read_ymusic_media_session(self, plugin):
        payload = {
            "has_session": False,
            "is_playing": False,
            "title": "",
            "artist": "",
            "album": "",
            "duration_ms": 0,
            "position_ms": 0,
            "player": "YMusic",
            "package_name": "com.yandex.music",
            "cover_bitmap": None,
            "cover_path": "",
        }
        try:
            ctx = ApplicationLoader.applicationContext
            if not ctx:
                self._ymusic_diag("no application context")
                return payload
            msm = ctx.getSystemService("media_session")
            if msm is None:
                self._ymusic_diag("media_session service unavailable")
                return payload
            listener_comp = self._ymusic_get_notification_listener_component(ctx)
            try:
                if listener_comp is not None:
                    controllers = msm.getActiveSessions(listener_comp)
                else:
                    controllers = msm.getActiveSessions(None)
            except Exception as e:
                em = str(e or "")
                if "SecurityException" in em or "permission" in em.lower():
                    if listener_comp is None:
                        self._ymusic_diag("getActiveSessions blocked globally (no enabled notification-listener component for this app)", cooldown_sec=60)
                    else:
                        self._ymusic_diag("getActiveSessions blocked globally (notification access or media control permission missing)", cooldown_sec=60)
                else:
                    self._ymusic_diag(f"getActiveSessions exception: {em[:120]}", cooldown_sec=60)
                return payload
            if controllers is None:
                self._ymusic_diag("active sessions returned null")
                return payload
            try:
                total = int(controllers.size())
            except Exception:
                total = 0
            if total <= 0:
                self._ymusic_diag("no active sessions detected")
                return payload
            accepted_pkgs = {
                "com.yandex.music",
                "com.google.android.apps.youtube.music",
                "com.google.android.youtube.music",
                "com.spotify.music",
                "app.revanced.android.apps.youtube.music",
            }
            seen_pkgs = []
            fallback_ctl = None
            fallback_state = None
            fallback_meta = None
            for i in range(total):
                try:
                    ctl = controllers.get(i)
                except Exception:
                    ctl = None
                if ctl is None:
                    continue
                try:
                    pkg = str(ctl.getPackageName() or "").strip()
                except Exception:
                    pkg = ""
                state_obj = None
                meta_obj = None
                try:
                    state_obj = ctl.getPlaybackState()
                except Exception:
                    state_obj = None
                try:
                    meta_obj = ctl.getMetadata()
                except Exception:
                    meta_obj = None
                st = 0
                pos_ms = 0
                try:
                    st = int(state_obj.getState()) if state_obj is not None else 0
                except Exception:
                    st = 0
                try:
                    pos_ms = int(state_obj.getPosition()) if state_obj is not None else 0
                except Exception:
                    pos_ms = 0
                is_playing = st in (3, 6, 8)
                try:
                    if pkg:
                        seen_pkgs.append(pkg)
                except Exception:
                    pass
                if (fallback_ctl is None) and bool(is_playing) and (meta_obj is not None):
                    try:
                        t0 = str(meta_obj.getString("android.media.metadata.TITLE") or "").strip()
                    except Exception:
                        t0 = ""
                    if not t0:
                        try:
                            t0 = str(meta_obj.getString("android.media.metadata.DISPLAY_TITLE") or "").strip()
                        except Exception:
                            t0 = ""
                    if t0:
                        fallback_ctl = ctl
                        fallback_state = state_obj
                        fallback_meta = meta_obj
                if pkg not in accepted_pkgs:
                    continue
                title = ""
                artist = ""
                album = ""
                dur_ms = 0
                art_bmp = None
                if meta_obj is not None:
                    try:
                        title = str(meta_obj.getString("android.media.metadata.TITLE") or "").strip()
                    except Exception:
                        title = ""
                    if not title:
                        try:
                            title = str(meta_obj.getString("android.media.metadata.DISPLAY_TITLE") or "").strip()
                        except Exception:
                            title = ""
                    try:
                        artist = str(meta_obj.getString("android.media.metadata.ARTIST") or "").strip()
                    except Exception:
                        artist = ""
                    try:
                        album = str(meta_obj.getString("android.media.metadata.ALBUM") or "").strip()
                    except Exception:
                        album = ""
                    try:
                        dur_ms = int(meta_obj.getLong("android.media.metadata.DURATION") or 0)
                    except Exception:
                        dur_ms = 0
                    try:
                        art_bmp = meta_obj.getBitmap("android.media.metadata.ALBUM_ART")
                    except Exception:
                        art_bmp = None
                    if art_bmp is None:
                        try:
                            art_bmp = meta_obj.getBitmap("android.media.metadata.ART")
                        except Exception:
                            art_bmp = None
                payload = {
                    "has_session": True,
                    "is_playing": bool(is_playing),
                    "title": title,
                    "artist": artist,
                    "album": album,
                    "duration_ms": max(0, int(dur_ms or 0)),
                    "position_ms": max(0, int(pos_ms or 0)),
                    "player": "YMusic",
                    "package_name": pkg,
                    "cover_bitmap": art_bmp,
                    "cover_path": self._ymusic_save_bitmap_png(art_bmp) if art_bmp is not None else "",
                }
                try:
                    self._nlog(f"[Nowfy][YMusic] matched package={pkg} state={st}")
                except Exception:
                    pass
                return payload
            if fallback_ctl is not None:
                try:
                    pkg = str(fallback_ctl.getPackageName() or "").strip()
                except Exception:
                    pkg = ""
                state_obj = fallback_state
                meta_obj = fallback_meta
                st = 0
                pos_ms = 0
                try:
                    st = int(state_obj.getState()) if state_obj is not None else 0
                except Exception:
                    st = 0
                try:
                    pos_ms = int(state_obj.getPosition()) if state_obj is not None else 0
                except Exception:
                    pos_ms = 0
                is_playing = st in (3, 6, 8)
                title = ""
                artist = ""
                album = ""
                dur_ms = 0
                art_bmp = None
                try:
                    title = str(meta_obj.getString("android.media.metadata.TITLE") or "").strip()
                except Exception:
                    title = ""
                if not title:
                    try:
                        title = str(meta_obj.getString("android.media.metadata.DISPLAY_TITLE") or "").strip()
                    except Exception:
                        title = ""
                try:
                    artist = str(meta_obj.getString("android.media.metadata.ARTIST") or "").strip()
                except Exception:
                    artist = ""
                if not artist:
                    try:
                        artist = str(meta_obj.getString("android.media.metadata.DISPLAY_SUBTITLE") or "").strip()
                    except Exception:
                        artist = ""
                try:
                    album = str(meta_obj.getString("android.media.metadata.ALBUM") or "").strip()
                except Exception:
                    album = ""
                if not album:
                    try:
                        album = str(meta_obj.getString("android.media.metadata.DISPLAY_DESCRIPTION") or "").strip()
                    except Exception:
                        album = ""
                try:
                    dur_ms = int(meta_obj.getLong("android.media.metadata.DURATION") or 0)
                except Exception:
                    dur_ms = 0
                try:
                    art_bmp = meta_obj.getBitmap("android.media.metadata.ALBUM_ART")
                except Exception:
                    art_bmp = None
                if art_bmp is None:
                    try:
                        art_bmp = meta_obj.getBitmap("android.media.metadata.ART")
                    except Exception:
                        art_bmp = None
                payload = {
                    "has_session": True,
                    "is_playing": bool(is_playing),
                    "title": title,
                    "artist": artist,
                    "album": album,
                    "duration_ms": max(0, int(dur_ms or 0)),
                    "position_ms": max(0, int(pos_ms or 0)),
                    "player": "YMusic",
                    "package_name": pkg,
                    "cover_bitmap": art_bmp,
                    "cover_path": self._ymusic_save_bitmap_png(art_bmp) if art_bmp is not None else "",
                }
                try:
                    self._nlog(f"[Nowfy][YMusic] fallback package={pkg} state={st}")
                except Exception:
                    pass
                return payload
            try:
                if seen_pkgs:
                    uniq = []
                    for p in seen_pkgs:
                        if p not in uniq:
                            uniq.append(p)
                    self._nlog(f"[Nowfy][YMusic] sessions={','.join(uniq[:6])}")
                else:
                    self._nlog("[Nowfy][YMusic] sessions=none")
            except Exception:
                pass
            self._ymusic_diag("no compatible playing session matched")
        except Exception:
            self._ymusic_diag("unexpected exception while reading media session", cooldown_sec=60)
            return payload
        return payload

    def get_ymusic_now_playing_panel_data(self, plugin):
        try:
            enabled = False
            if plugin is not None:
                tk = str(plugin.get_setting("ymusic_api_token", "") or "").strip()
                enabled = bool(tk)
        except Exception:
            enabled = False
        data = {}
        if enabled:
            try:
                data = self._read_ymusic_api_now_playing(plugin) or {}
            except Exception:
                data = {}
        if not isinstance(data, dict):
            data = {}
        if not data:
            data = {
                "enabled": bool(enabled),
                "has_session": False,
                "is_playing": False,
                "title": "",
                "artist": "",
                "album": "",
                "position_ms": 0,
                "duration_ms": 0,
                "cover_path": "",
                "cover_bitmap": None,
                "track_obj": None,
            }
        try:
            data["enabled"] = bool(enabled)
            data["elapsed_label"] = self._ymusic_format_ms(data.get("position_ms", 0))
            data["duration_label"] = self._ymusic_format_ms(data.get("duration_ms", 0))
        except Exception:
            pass
        return data

    def inject_ymusic_profile_custom(self, plugin, activity, items):
        try:
            if plugin is None or activity is None or items is None:
                return
            in_ymusic_subfragment = False
            try:
                cb = get_private_field(activity, "createSubFragmentCallback")
                cbn = str(getattr(cb, "__name__", "") or "")
                in_ymusic_subfragment = (cbn == "create_ymusic_credentials_subfragment")
            except Exception:
                in_ymusic_subfragment = False
            if not in_ymusic_subfragment:
                try:
                    for i in range(items.size()):
                        k = str(plugin._get_uitem_setting_key(items.get(i)) or "")
                        if k == "ymusic_api_token":
                            in_ymusic_subfragment = True
                            break
                except Exception:
                    pass
            if not in_ymusic_subfragment:
                return
            try:
                plugin._ymusic_settings_activity = activity
            except Exception:
                pass
            remove_indices = []
            anchor = -1
            for i in range(items.size()):
                try:
                    it = items.get(i)
                    marker = str(getattr(it, "object2", "") or "")
                    if marker in ("__ymusic_now_playing_custom__", "__ymusic_now_playing_shadow__"):
                        remove_indices.append(i)
                        continue
                    key = str(plugin._get_uitem_setting_key(it) or "")
                    if key == "ymusic_api_token":
                        anchor = i
                except Exception:
                    pass
            for idx_rm in reversed(remove_indices):
                try:
                    items.remove(idx_rm)
                except Exception:
                    pass
            if anchor < 0:
                anchor = max(0, items.size() - 1)
            ctx = activity.getContext() if activity else None
            if not ctx:
                return
            def _lt(key, fallback):
                try:
                    idx = int(plugin.get_setting("plugin_lang", 0) or 0)
                except Exception:
                    idx = 0
                try:
                    codes = ["en", "pt", "ru"]
                    lang = codes[idx] if 0 <= idx < len(codes) else "en"
                except Exception:
                    lang = "en"
                try:
                    entry = TRANSLATIONS.get(str(key), {})
                    if isinstance(entry, dict):
                        val = str(entry.get(lang) or "").strip()
                        if val:
                            return val
                        val_en = str(entry.get("en") or "").strip()
                        if val_en:
                            return val_en
                except Exception:
                    pass
                return str(fallback)
            np_wrap = LinearLayout(ctx)
            np_wrap.setOrientation(LinearLayout.VERTICAL)
            try:
                np_wrap.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(12), AndroidUtilities.dp(14), AndroidUtilities.dp(12))
            except Exception:
                pass
            try:
                np_bg = GradientDrawable()
                np_bg.setCornerRadius(AndroidUtilities.dp(14))
                np_bg.setColor(0x142A3A52)
                np_bg.setStroke(AndroidUtilities.dp(1), 0x446FA8DC)
                np_wrap.setBackground(np_bg)
            except Exception:
                pass
            np_title = TextView(ctx)
            np_title.setText(_lt("ymusic_now_playing_title", "Now Playing"))
            np_title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            try:
                np_title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                np_title.setTextColor(0xFFFFFFFF)
            np_wrap.addView(np_title)
            np_content = LinearLayout(ctx)
            np_content.setOrientation(LinearLayout.HORIZONTAL)
            np_content.setGravity(Gravity.CENTER_VERTICAL)
            try:
                lp_nc = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
                lp_nc.topMargin = AndroidUtilities.dp(10)
                np_wrap.addView(np_content, lp_nc)
            except Exception:
                np_wrap.addView(np_content)
            np_cover = ImageView(ctx)
            try:
                np_cover.setScaleType(ImageView.ScaleType.CENTER_CROP)
            except Exception:
                pass
            try:
                cbg = GradientDrawable()
                cbg.setCornerRadius(AndroidUtilities.dp(10))
                cbg.setColor(0x223D4F6B)
                np_cover.setBackground(cbg)
                np_cover.setClipToOutline(True)
            except Exception:
                pass
            try:
                np_content.addView(np_cover, LinearLayout.LayoutParams(AndroidUtilities.dp(72), AndroidUtilities.dp(72)))
            except Exception:
                np_content.addView(np_cover)
            np_text_col = LinearLayout(ctx)
            np_text_col.setOrientation(LinearLayout.VERTICAL)
            try:
                lp_tc = LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1.0)
                lp_tc.leftMargin = AndroidUtilities.dp(12)
                np_content.addView(np_text_col, lp_tc)
            except Exception:
                np_content.addView(np_text_col)
            np_track = TextView(ctx)
            np_track.setText(_lt("ymusic_now_playing_placeholder_title", "Nothing playing right now"))
            np_track.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
            try:
                np_track.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                np_track.setTextColor(0xFFFFFFFF)
            np_text_col.addView(np_track)
            np_artist = TextView(ctx)
            np_artist.setText(_lt("ymusic_now_playing_placeholder_sub", "Play something on Yandex Music to show live status."))
            np_artist.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            try:
                np_artist.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception:
                np_artist.setTextColor(0xFFD2DCEB)
            np_text_col.addView(np_artist)
            np_time = TextView(ctx)
            np_time.setText("0:00 • 0:00")
            np_time.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            try:
                np_time.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                np_time.setTextColor(0xFFFFFFFF)
            np_text_col.addView(np_time)
            np_item = UItem.asCustom(np_wrap)
            try:
                np_item.object2 = "__ymusic_now_playing_custom__"
            except Exception:
                pass
            items.add(min(anchor + 1, items.size()), np_item)
            try:
                shadow = UItem.asShadow()
                shadow.object2 = "__ymusic_now_playing_shadow__"
                items.add(min(anchor + 2, items.size()), shadow)
            except Exception:
                pass
            render_state = {"cover_path": ""}
            def _apply_payload(payload):
                try:
                    p = payload if isinstance(payload, dict) else {}
                    enabled = bool(p.get("enabled", False))
                    has_session = bool(p.get("has_session", False))
                    is_playing = bool(p.get("is_playing", False))
                    if (not enabled) or (not has_session) or (not is_playing):
                        try:
                            np_wrap.setVisibility(View.GONE)
                        except Exception:
                            pass
                        return
                    try:
                        np_wrap.setVisibility(View.VISIBLE)
                    except Exception:
                        pass
                    title_txt = str(p.get("title") or "").strip()
                    artist_txt = str(p.get("artist") or "").strip()
                    album_txt = str(p.get("album") or "").strip()
                    elapsed_txt = str(p.get("elapsed_label") or "0:00").strip()
                    duration_txt = str(p.get("duration_label") or "0:00").strip()
                    np_track.setText(title_txt or _lt("ymusic_now_playing_placeholder_title", "Nothing playing right now"))
                    if album_txt:
                        np_artist.setText(f"{artist_txt or '-'} • {album_txt}")
                    else:
                        np_artist.setText(artist_txt or "-")
                    np_time.setText(f"{elapsed_txt} • {duration_txt}")
                    bmp = p.get("cover_bitmap")
                    if bmp is not None:
                        np_cover.setImageBitmap(bmp)
                        render_state["cover_path"] = str(p.get("cover_path") or "")
                    else:
                        cpath = str(p.get("cover_path") or "").strip()
                        if cpath and cpath != render_state.get("cover_path") and os.path.isfile(cpath):
                            try:
                                bb = BitmapFactory.decodeFile(cpath)
                                if bb:
                                    np_cover.setImageBitmap(bb)
                                    render_state["cover_path"] = cpath
                            except Exception:
                                pass
                except Exception:
                    pass
            def _fetch_and_apply():
                try:
                    data = self.get_ymusic_now_playing_panel_data(plugin)
                except Exception:
                    try:
                        _tk = str(plugin.get_setting("ymusic_api_token", "") or "").strip()
                        _enabled = bool(_tk)
                    except Exception:
                        _enabled = False
                    data = {"enabled": _enabled, "has_session": False, "is_playing": False}
                run_on_ui_thread(lambda d=data: _apply_payload(d))
            seq = int(time.time() * 1000)
            try:
                plugin._ymusic_np_seq = seq
            except Exception:
                pass
            def _worker():
                i = 0
                while i < 300:
                    try:
                        if int(getattr(plugin, "_ymusic_np_seq", 0) or 0) != seq:
                            break
                    except Exception:
                        pass
                    _fetch_and_apply()
                    try:
                        time.sleep(4)
                    except Exception:
                        pass
                    i += 1
            threading.Thread(target=_worker, daemon=True).start()
        except Exception:
            pass
