def _core_lang():
    try:
        c = str(LocaleController.getString("LanguageName", R.string.LanguageName) or "").strip().lower()
        if ("portuguese" in c) or ("português" in c) or ("pt-br" in c) or ("pt" == c):
            return "pt"
        if ("russian" in c) or ("русский" in c) or ("ru" == c):
            return "ru"
    except Exception:
        pass
    return "en"


def core_tr(key):
    try:
        lang = _universal_plugin_lang()
        rtbl = TRANSLATIONS.get(key) or {}
        if isinstance(rtbl, dict):
            val = rtbl.get(lang) or rtbl.get("en")
            if val:
                return str(val)
        tbl = CORE_SETTINGS_I18N.get(key) or {}
        return str(tbl.get(lang) or tbl.get("en") or key)
    except Exception:
        return str(key)
        pass


class NowfyCore(BasePlugin):
    instance = None

    def __init__(self, host_plugin=None):
        super().__init__()
        global _NOWFY_HOST_PLUGIN, _NOWFY_CORE_RUNTIME
        self.host = host_plugin
        self.api = _NowfyCoreApi()
        if host_plugin is not None:
            try:
                _NOWFY_HOST_PLUGIN = host_plugin
            except Exception:
                pass
        try:
            _NOWFY_CORE_RUNTIME = self
        except Exception:
            pass
        try:
            NowfyCore.instance = self
        except Exception:
            pass
        try:
            self._runtime_bootstrapped = False
        except Exception:
            pass

    def _ensure_runtime_bootstrap(self):
        try:
            if bool(getattr(self, "_runtime_bootstrapped", False)):
                return True
            self._runtime_bootstrapped = True
            self._release_notice_cache = {"ts": 0, "data": None}
            self._release_notice_busy = False
            if not hasattr(self, "_core_remote_dir"):
                self._core_remote_dir = None
            try:
                self._core_remote_dir = File(ApplicationLoader.getFilesDirFixed(), "nowfycore_remote")
                if self._core_remote_dir and not self._core_remote_dir.exists():
                    self._core_remote_dir.mkdirs()
            except Exception:
                self._core_remote_dir = None
            try:
                if not bool(self.get_setting("release_notice_state_migration_v2", False)):
                    self.set_setting("release_notice_state", "")
                    self.set_setting("release_notice_card_counter", 0)
                    self.set_setting("release_notice_state_migration_v2", True)
            except Exception:
                pass
            try:
                threading.Thread(target=self._refresh_remote_translations_pack, daemon=True).start()
            except Exception:
                pass
            try:
                threading.Thread(target=self._refresh_release_notice_cache, daemon=True).start()
            except Exception:
                pass
            try:
                threading.Thread(target=self._maybe_schedule_release_notice_popup, daemon=True).start()
            except Exception:
                pass
            return True
        except Exception:
            return False

    def get_setting(self, key, default_value=None):
        try:
            if self.host is not None and hasattr(self.host, "get_setting"):
                return self.host.get_setting(key, default_value)
        except Exception:
            pass
        try:
            return super().get_setting(key, default_value)
        except Exception:
            return default_value

    def set_setting(self, key, value):
        ok = False
        try:
            if self.host is not None and hasattr(self.host, "set_setting"):
                self.host.set_setting(key, value)
                ok = True
        except Exception:
            pass
        try:
            super().set_setting(key, value)
            ok = True
        except Exception:
            pass
        return ok

    def _addon_plugin_id(self, addon_key):
        try:
            key = str(addon_key or "").strip()
            if key == "addon_nowcast_enabled":
                return "nowfy_nowcast"
            return ""
        except Exception:
            return ""

    def _is_addon_installed(self, addon_key):
        try:
            pid = self._addon_plugin_id(addon_key)
            if not pid:
                return False
            return bool(self._is_plugin_file_present(pid))
        except Exception:
            return False

    def _addon_status_suffix(self, addon_key):
        try:
            pid = self._addon_plugin_id(addon_key)
            if not pid:
                return ""
            installed = bool(self._is_plugin_file_present(pid))
            enabled = bool(self._engine_is_plugin_enabled(pid))
            if installed and enabled:
                return " (Addon installed)"
            if installed and (not enabled):
                return " (Addon installed, disabled)"
            return " (Addon not installed)"
        except Exception:
            return ""

    def _get_core_lang_index(self):
        try:
            return max(0, min(2, int(self.get_setting("plugin_lang", 0) or 0)))
        except Exception:
            return 0

    def _on_change_core_lang(self, value):
        try:
            idx = max(0, min(2, int(value)))
        except Exception:
            idx = 0
        try:
            self.set_setting("plugin_lang", idx)
        except Exception:
            pass
        try:
            global _NOWFY_LANG_OVERRIDE
            _NOWFY_LANG_OVERRIDE = _lang_from_index(idx, "en")
        except Exception:
            pass

    def on_plugin_load(self):
        NowfyCore.instance = self
        self.api = _NowfyCoreApi()
        self._engine_install_busy = False
        self._engine_install_lock = threading.Lock()
        self._nowfy_install_busy = False
        self._nowfy_install_lock = threading.Lock()
        nowfy_file_present = False
        nowfy_enabled_now = False
        try:
            nowfy_file_present = bool(self._is_plugin_file_present("nowfy"))
        except Exception:
            nowfy_file_present = False
        try:
            nowfy_enabled_now = bool(self._engine_is_plugin_enabled("nowfy"))
        except Exception:
            nowfy_enabled_now = False
        try:
            prev_core_ver = str(self.get_setting("nowfy_auto_enable_core_ver", "") or "")
        except Exception:
            prev_core_ver = ""
        try:
            if (prev_core_ver != str(__version__)) or (not nowfy_file_present) or (not nowfy_enabled_now):
                self.set_setting("nowfy_auto_enable_core_ver", str(__version__))
                self.set_setting("nowfy_auto_enable_pending", True)
        except Exception:
            pass
        try:
            muted = bool(self.get_setting("disable_logs", False))
            _set_log_muted(muted)
            _set_print_muted(muted)
            _apply_log_wrapper(True)
            _apply_print_wrapper(True)
        except Exception:
            pass
        try:
            global _NOWFY_LANG_OVERRIDE
            _NOWFY_LANG_OVERRIDE = _lang_from_index(self._get_core_lang_index(), "en")
        except Exception:
            pass
        try:
            if not bool(self.get_setting("release_notice_state_migration_v2", False)):
                self.set_setting("release_notice_state", "")
                self.set_setting("release_notice_card_counter", 0)
                self.set_setting("release_notice_state_migration_v2", True)
        except Exception:
            pass
        self._release_notice_cache = {"ts": 0, "data": None}
        self._release_notice_busy = False
        self._core_remote_dir = None
        try:
            self._core_remote_dir = File(ApplicationLoader.getFilesDirFixed(), "nowfycore_remote")
            if self._core_remote_dir and not self._core_remote_dir.exists():
                self._core_remote_dir.mkdirs()
        except Exception:
            self._core_remote_dir = None
        try:
            threading.Thread(target=self._refresh_remote_translations_pack, daemon=True).start()
        except Exception:
            pass
        try:
            threading.Thread(target=self._refresh_release_notice_cache, daemon=True).start()
        except Exception:
            pass
        try:
            threading.Thread(target=self._maybe_schedule_release_notice_popup, daemon=True).start()
        except Exception:
            pass
        try:
            if bool(self.get_setting("nowfy_auto_install_enabled", False)):
                threading.Thread(target=self._ensure_nowfy_installed, daemon=True).start()
        except Exception:
            pass
        try:
            def _late_nowfy_retry():
                try:
                    time.sleep(14)
                    if not bool(self.get_setting("nowfy_auto_install_enabled", False)):
                        return
                    installed = bool(self._get_installed_plugin_version("nowfy")) and bool(self._is_plugin_file_present("nowfy"))
                    if not installed:
                        self._ensure_nowfy_installed()
                except Exception:
                    pass
            threading.Thread(target=_late_nowfy_retry, daemon=True).start()
        except Exception:
            pass
        try:
            self._ensure_runtime_bootstrap()
        except Exception:
            pass

    def on_plugin_unload(self):
        self.api = None
        NowfyCore.instance = None

    def _get_release_notice_url(self):
        try:
            v = str(self.get_setting("release_notice_json_url", "") or "").strip()
            if v:
                return v
        except Exception:
            pass
        try:
            rv = str(self._core_pack_get_value("release_notice_url", "") or "").strip()
            if rv:
                return rv
        except Exception:
            pass
        return f"{self._get_corepack_base_url()}/nowfy_release_notice.json"

    def _parse_version_tuple(self, value):
        try:
            s = str(value or "").strip().lower()
            if s.startswith("v"):
                s = s[1:]
            parts = [p for p in re.split(r"[^0-9]+", s) if p != ""]
            nums = [int(x) for x in parts[:4]]
            while len(nums) < 4:
                nums.append(0)
            return tuple(nums)
        except Exception:
            return (0, 0, 0, 0)

    def _get_nowfy_main_version(self):
        try:
            controller = PluginsController.getInstance()
            p = controller.plugins.get("nowfy") if controller else None
            if p:
                v = str(p.getVersion() or "").strip()
                if v:
                    return v
        except Exception:
            pass
        try:
            v2 = str(self.get_setting("nowfy_last_version", "") or "").strip()
            if v2:
                return v2
        except Exception:
            pass
        try:
            v3 = str(self._get_installed_plugin_version("nowfy") or "").strip()
            if v3:
                return v3
        except Exception:
            pass
        return "0.0.0"

    def _refresh_release_notice_cache(self):
        try:
            if bool(getattr(self, "_release_notice_busy", False)):
                return None
            self._release_notice_busy = True
            data = self._core_remote_fetch_json(self._get_release_notice_url(), "nowfy_release_notice", timeout=8)
            if isinstance(data, dict):
                self._release_notice_cache = {"ts": int(time.time()), "data": data}
                try:
                    threading.Thread(target=self._maybe_schedule_release_notice_popup, daemon=True).start()
                except Exception:
                    pass
                return data
            return None
        except Exception:
            return None
        finally:
            self._release_notice_busy = False

    def _get_release_notice_cached(self):
        try:
            cache = getattr(self, "_release_notice_cache", None) or {}
            ts = int(cache.get("ts", 0) or 0)
            data = cache.get("data")
            if isinstance(data, dict) and (int(time.time()) - ts) < 600:
                return data
            cached_disk = self._core_remote_cache_read("nowfy_release_notice")
            if isinstance(cached_disk, dict):
                self._release_notice_cache = {"ts": int(time.time()), "data": cached_disk}
                data = cached_disk
            if not isinstance(data, dict):
                try:
                    threading.Thread(target=self._refresh_release_notice_cache, daemon=True).start()
                except Exception:
                    pass
                return None
            return data
        except Exception:
            return None

    def _is_release_notice_available(self):
        try:
            data = self._get_release_notice_cached() or self._refresh_release_notice_cache()
            if not isinstance(data, dict):
                return False
            upd, _note = self._extract_release_notice_entries(data)
            if not isinstance(upd, dict):
                return False
            remote_version = str(upd.get("version", "") or "").strip()
            if not remote_version:
                return False
            current = self._get_nowfy_main_version()
            return self._parse_version_tuple(remote_version) > self._parse_version_tuple(current)
        except Exception:
            return False

    def _get_release_notice_state(self):
        try:
            raw = str(self.get_setting("release_notice_state", "") or "").strip()
            if not raw:
                return {}
            obj = json.loads(raw)
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

    def _set_release_notice_state(self, state_obj):
        try:
            if not isinstance(state_obj, dict):
                state_obj = {}
            self.set_setting("release_notice_state", json.dumps(state_obj, ensure_ascii=False))
        except Exception:
            pass

    def _get_release_notice_card_counter(self):
        try:
            return int(self.get_setting("release_notice_card_counter", 0) or 0)
        except Exception:
            return 0

    def _set_release_notice_card_counter(self, value):
        try:
            self.set_setting("release_notice_card_counter", int(value))
        except Exception:
            pass

    def _bump_release_notice_card_counter(self):
        try:
            cur = self._get_release_notice_card_counter()
            self._set_release_notice_card_counter(cur + 1)
            try:
                threading.Thread(target=self._maybe_schedule_release_notice_popup, daemon=True).start()
            except Exception:
                pass
        except Exception:
            pass

    def _extract_release_notice_entries(self, payload):
        update_entry = None
        note_entry = None
        try:
            if not isinstance(payload, dict):
                return None, None
            if isinstance(payload.get("update"), dict):
                update_entry = dict(payload.get("update") or {})
            if isinstance(payload.get("note"), dict):
                note_entry = dict(payload.get("note") or {})
            if update_entry is None:
                if any(k in payload for k in ("version", "title", "description", "image", "button_text", "button_url")):
                    update_entry = dict(payload)
            if isinstance(update_entry, dict):
                if not str(update_entry.get("version", "") or "").strip():
                    update_entry["version"] = str(payload.get("version", "") or "").strip()
            if isinstance(note_entry, dict):
                nid = str(note_entry.get("note", "") or note_entry.get("id", "") or "").strip()
                if not nid:
                    nid = str(payload.get("note", "") or payload.get("note_id", "") or "").strip()
                    if nid:
                        note_entry["note"] = nid
            return update_entry, note_entry
        except Exception:
            return None, None

    def _release_note_index(self, note_id):
        try:
            s = str(note_id or "").strip().lower()
            if not s:
                return None
            m = re.search(r"(\d+)$", s)
            if not m:
                return None
            return int(m.group(1))
        except Exception:
            return None

    def _consume_release_notice_show(self):
        try:
            data = self._get_release_notice_cached()
            if not isinstance(data, dict):
                return False
            update_entry, note_entry = self._extract_release_notice_entries(data)
            st = self._get_release_notice_state()
            now_ts = int(time.time())
            if isinstance(note_entry, dict):
                note_id = str(note_entry.get("note", "") or note_entry.get("id", "") or "").strip()
                if note_id:
                    last_note_id = str(st.get("note_id", "") or "").strip()
                    if note_id != last_note_id:
                        cur_idx = self._release_note_index(note_id)
                        last_idx = self._release_note_index(last_note_id)
                        st["note_id"] = note_id
                        st["note_ts"] = now_ts
                        self._set_release_notice_state(st)
                        if not last_note_id:
                            if cur_idx is not None and cur_idx <= 1:
                                return None
                            return {"kind": "note", "entry": note_entry}
                        if cur_idx is not None and last_idx is not None and cur_idx <= last_idx:
                            return None
                        return {"kind": "note", "entry": note_entry}
            if isinstance(update_entry, dict):
                remote_version = str(update_entry.get("version", "") or "").strip()
                if remote_version:
                    current = self._get_nowfy_main_version()
                    if self._parse_version_tuple(remote_version) > self._parse_version_tuple(current):
                        uv = str(st.get("update_version", "") or "").strip()
                        shown = int(st.get("update_shown", 0) or 0)
                        bonus_shown = bool(st.get("update_bonus_shown", False))
                        last_show_counter = int(st.get("update_last_show_counter", 0) or 0)
                        card_counter = self._get_release_notice_card_counter()
                        if uv != remote_version:
                            shown = 0
                            bonus_shown = False
                            last_show_counter = card_counter
                        should_show = False
                        if shown < 3:
                            should_show = True
                            shown += 1
                            last_show_counter = card_counter
                        elif (not bonus_shown) and (card_counter - last_show_counter >= 30):
                            should_show = True
                            bonus_shown = True
                            last_show_counter = card_counter
                        if should_show:
                            st["update_version"] = remote_version
                            st["update_shown"] = shown
                            st["update_bonus_shown"] = bonus_shown
                            st["update_last_show_counter"] = last_show_counter
                            st["update_ts"] = now_ts
                            self._set_release_notice_state(st)
                            return {"kind": "update", "entry": update_entry}
            return None
        except Exception:
            return None

    def _maybe_schedule_release_notice_popup(self):
        try:
            if bool(getattr(self, "_release_notice_popup_running", False)):
                return False
        except Exception:
            pass
        self._release_notice_popup_running = True
        try:
            prev_state = self._get_release_notice_state()
            payload = self._consume_release_notice_show()
            if not payload:
                return False
            kind = str(payload.get("kind", "") or "")
            entry = payload.get("entry", {}) if isinstance(payload, dict) else {}
            try:
                delay = int(random.randint(6, 18)) if kind == "update" else int(random.randint(4, 10))
            except Exception:
                delay = 10 if kind == "update" else 6
            try:
                time.sleep(max(1, delay))
            except Exception:
                pass
            target_ctx = None
            for _ in range(60):
                try:
                    frag = get_last_fragment()
                    if frag:
                        act = frag.getParentActivity()
                        if act:
                            target_ctx = act
                            break
                except Exception:
                    pass
                try:
                    time.sleep(0.5)
                except Exception:
                    break
            if target_ctx is None:
                try:
                    self._set_release_notice_state(prev_state)
                except Exception:
                    pass
                return False
            run_on_ui_thread(lambda: self._show_release_notice_bottom_sheet(entry, kind=kind))
            return True
        except Exception:
            return False
        finally:
            self._release_notice_popup_running = False

    def _show_release_notice_bottom_sheet(self, entry=None, kind="update"):
        try:
            data = entry if isinstance(entry, dict) else None
            if data is None:
                payload = self._consume_release_notice_show()
                if not payload:
                    return
                kind = str(payload.get("kind", "update") or "update")
                data = payload.get("entry", {}) if isinstance(payload.get("entry", {}), dict) else {}
            fragment = get_last_fragment()
            if not fragment:
                return
            ctx = fragment.getParentActivity() if fragment.getParentActivity() else ApplicationLoader.applicationContext
            if not ctx:
                return
            title_default = "New update available" if kind != "note" else "Notice"
            title_text = str(data.get("title", title_default) or title_default)
            desc_text = str(data.get("description", "") or "")
            image_url = str(data.get("image", "") or "")
            button_default = "Update now" if kind != "note" else "Ok, got it"
            button_text = str(data.get("button_text", button_default) or button_default)
            button_url = str(data.get("button_url", "") or "")
            sheet = BottomSheet(ctx, True, fragment.getResourceProvider())
            sheet.fixNavigationBar()
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(18), AndroidUtilities.dp(20), AndroidUtilities.dp(18))
            root.setGravity(Gravity.CENTER_HORIZONTAL)
            img = ImageView(ctx)
            try:
                img.setScaleType(ImageView.ScaleType.CENTER_CROP)
            except Exception:
                pass
            try:
                shape = GradientDrawable()
                shape.setCornerRadius(float(AndroidUtilities.dp(16)))
                shape.setColor(0x14000000)
                img.setBackground(shape)
                try:
                    img.setClipToOutline(True)
                except Exception:
                    pass
            except Exception:
                pass
            root.addView(img, LinearLayout.LayoutParams(-1, AndroidUtilities.dp(148)))
            title = TextView(ctx)
            title.setText(title_text)
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            try:
                title.setTypeface(AndroidUtilities.bold())
            except Exception:
                pass
            try:
                title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
            except Exception:
                pass
            lp_t = LinearLayout.LayoutParams(-1, -2)
            lp_t.topMargin = AndroidUtilities.dp(12)
            root.addView(title, lp_t)
            desc = TextView(ctx)
            desc.setText(desc_text)
            desc.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            try:
                desc.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception:
                pass
            lp_d = LinearLayout.LayoutParams(-1, -2)
            lp_d.topMargin = AndroidUtilities.dp(6)
            root.addView(desc, lp_d)
            btn = TextView(ctx)
            btn.setText(button_text)
            btn.setGravity(Gravity.CENTER)
            btn.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
            try:
                btn.setTypeface(AndroidUtilities.bold())
            except Exception:
                pass
            try:
                btn.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText))
            except Exception:
                pass
            try:
                bbg = GradientDrawable()
                bbg.setCornerRadius(float(AndroidUtilities.dp(14)))
                try:
                    bbg.setColor(Theme.getColor(Theme.key_featuredStickers_addButton))
                except Exception:
                    bbg.setColor(0x332D87FF)
                btn.setBackground(bbg)
            except Exception:
                pass
            lp_b = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(46))
            lp_b.topMargin = AndroidUtilities.dp(14)
            root.addView(btn, lp_b)
            def _on_btn(_v):
                try:
                    raw_url = str(button_url or "").strip()
                    if raw_url:
                        if not raw_url.startswith("http://") and not raw_url.startswith("https://"):
                            raw_url = "https://" + raw_url
                        def _open():
                            try:
                                from org.telegram.messenger import Browser
                                app_ctx = ApplicationLoader.applicationContext or ctx
                                Browser.openUrl(app_ctx, raw_url)
                                return
                            except Exception:
                                pass
                            try:
                                intent = Intent(Intent.ACTION_VIEW, Uri.parse(raw_url))
                                intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                                app_ctx2 = ApplicationLoader.applicationContext or ctx
                                app_ctx2.startActivity(intent)
                            except Exception:
                                pass
                        run_on_ui_thread(_open)
                except Exception:
                    pass
                try:
                    sheet.dismiss()
                except Exception:
                    pass
            btn.setOnClickListener(OnClickListener(_on_btn))
            sheet.setCustomView(root)
            sheet.show()
            def _load():
                try:
                    if not image_url:
                        return
                    resp = requests.get(image_url, timeout=10)
                    if resp.status_code != 200 or not resp.content:
                        return
                    raw = bytes(resp.content)
                    jb = jarray(jbyte)(raw)
                    bmp = BitmapFactory.decodeByteArray(jb, 0, len(raw))
                    if bmp is None:
                        return
                    run_on_ui_thread(lambda: img.setImageBitmap(bmp))
                except Exception:
                    pass
            threading.Thread(target=_load, daemon=True).start()
        except Exception:
            pass

    def _get_coreupdates_url(self):
        try:
            v = str(self.get_setting("core_updates_json_url", "") or "").strip()
            if v:
                return v
        except Exception:
            pass
        try:
            rv = str(self._core_pack_get_value("coreupdates_url", "") or "").strip()
            if rv:
                return rv
        except Exception:
            pass
        return "https://coreupdates.meyankut.workers.dev/coreupdates.json"

    def _get_corepack_base_url(self):
        try:
            v = str(self.get_setting("core_pack_base_url", "") or "").strip()
            if v:
                return v.rstrip("/")
        except Exception:
            pass
        return "https://coreupdates.meyankut.workers.dev"

    def _get_engine_manifest_url(self):
        try:
            v = str(self.get_setting("engine_manifest_url", "") or "").strip()
            if v:
                return v
        except Exception:
            pass
        try:
            rv = str(self._core_pack_get_value("engine_manifest_url", "") or "").strip()
            if rv:
                return rv
        except Exception:
            pass
        return f"{self._get_corepack_base_url()}/nowfy_engine_manifest.json"

    def _get_nowfy_manifest_url(self):
        try:
            v = str(self.get_setting("nowfy_manifest_url", "") or "").strip()
            if v:
                return v
        except Exception:
            pass
        try:
            rv = str(self._core_pack_get_value("nowfy_manifest_url", "") or "").strip()
            if rv:
                return rv
        except Exception:
            pass
        return f"{self._get_corepack_base_url()}/nowfy_manifest.json"

    def _get_nowfy_plugin_url(self):
        try:
            v = str(self.get_setting("nowfy_plugin_url", "") or "").strip()
            if v:
                return v
        except Exception:
            pass
        try:
            rv = str(self._core_pack_get_value("nowfy_plugin_url", "") or "").strip()
            if rv:
                return rv
        except Exception:
            pass
        return f"{self._get_corepack_base_url()}/nowfy.plugin"

    def _get_installed_plugin_version(self, plugin_id):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return ""
            ctrl = PluginsController.getInstance()
            p = ctrl.plugins.get(pid) if ctrl else None
            if p:
                try:
                    path = ctrl.getPluginPath(pid) if ctrl else None
                    if path and (not os.path.isfile(str(path))):
                        return ""
                except Exception:
                    pass
                v = str(p.getVersion() or "").strip()
                if v:
                    return v
            try:
                plugins_dir = self._engine_plugins_dir()
                if plugins_dir:
                    fp = os.path.join(plugins_dir, f"{pid}.plugin")
                    if os.path.isfile(fp):
                        vv = self._read_plugin_version_from_file(fp)
                        if vv:
                            return str(vv)
            except Exception:
                pass
        except Exception:
            pass
        return ""

    def _is_plugin_file_present(self, plugin_id):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return False
            ctrl = PluginsController.getInstance()
            if not ctrl:
                return False
            path = ctrl.getPluginPath(pid)
            if path and os.path.isfile(str(path)):
                return True
            plugins_dir = self._engine_plugins_dir()
            if plugins_dir:
                fp = os.path.join(plugins_dir, f"{pid}.plugin")
                if os.path.isfile(fp):
                    return True
            return False
        except Exception:
            return False

    def _engine_get_plugin_file_path(self, plugin_id, must_exist=False):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return None
            ctrl = PluginsController.getInstance()
            try:
                if ctrl:
                    pth = ctrl.getPluginPath(pid)
                    if pth:
                        pth = str(pth)
                        if (not must_exist) or os.path.isfile(pth):
                            return pth
            except Exception:
                pass
            plugins_dir = self._engine_plugins_dir()
            if not plugins_dir:
                return None
            fp = os.path.join(plugins_dir, f"{pid}.plugin")
            if must_exist and (not os.path.isfile(fp)):
                return None
            return fp
        except Exception:
            return None

    def _fetch_engine_manifest(self):
        try:
            payload = self._core_remote_fetch_json(self._get_engine_manifest_url(), "nowfy_engine_manifest", timeout=10)
            if not isinstance(payload, dict):
                return None
            data = payload.get("engine") if isinstance(payload.get("engine"), dict) else payload
            if not isinstance(data, dict):
                return None
            plugin_id = str(data.get("plugin_id", "") or "nowfy_engine").strip() or "nowfy_engine"
            version = str(data.get("version", "") or "").strip()
            plugin_url = str(data.get("plugin_url", "") or data.get("url", "") or "").strip()
            sha256 = self._normalize_sha256(str(data.get("sha256", "") or ""))
            if not plugin_url.startswith("http://") and not plugin_url.startswith("https://"):
                return None
            if not version:
                version = "0.0.0"
            return {
                "plugin_id": plugin_id,
                "version": version,
                "plugin_url": plugin_url,
                "sha256": sha256,
            }
        except Exception:
            return None

    def _fetch_nowfy_manifest(self):
        try:
            payload = self._core_remote_fetch_json(self._get_nowfy_manifest_url(), "nowfy_manifest", timeout=10)
            if not isinstance(payload, dict):
                return None
            data = payload.get("nowfy") if isinstance(payload.get("nowfy"), dict) else payload
            if not isinstance(data, dict):
                return None
            plugin_id = str(data.get("plugin_id", "") or "nowfy").strip() or "nowfy"
            version = str(data.get("version", "") or "").strip()
            plugin_url = str(data.get("plugin_url", "") or data.get("url", "") or "").strip()
            sha256 = self._normalize_sha256(str(data.get("sha256", "") or ""))
            if not plugin_url.startswith("http://") and not plugin_url.startswith("https://"):
                return None
            if not version:
                version = "0.0.0"
            return {
                "plugin_id": plugin_id,
                "version": version,
                "plugin_url": plugin_url,
                "sha256": sha256,
                "force": bool(data.get("force", False)),
            }
        except Exception:
            return None

    def _probe_remote_plugin_version(self, plugin_url, cache_key="nowfy_remote_version"):
        try:
            url = str(plugin_url or "").strip()
            if not url:
                return ""
            sep = "&" if "?" in url else "?"
            fetch_url = f"{url}{sep}_ver_bust={int(time.time())}"
            r = requests.get(
                fetch_url,
                timeout=12,
                headers={
                    "Cache-Control": "no-cache, no-store, must-revalidate",
                    "Pragma": "no-cache",
                    "Expires": "0",
                },
            )
            if r.status_code != 200 or not r.content:
                return ""
            txt = r.content.decode("utf-8", errors="replace")
            while txt.startswith("\ufeff"):
                txt = txt[1:]
            m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', txt)
            ver = str(m.group(1) or "").strip() if m else ""
            return ver
        except Exception:
            return ""

    def _read_plugin_version_from_file(self, file_path):
        try:
            if not file_path or (not os.path.isfile(str(file_path))):
                return ""
            with open(str(file_path), "rb") as f:
                raw = f.read()
            if not raw:
                return ""
            txt = raw.decode("utf-8", errors="replace")
            while txt.startswith("\ufeff"):
                txt = txt[1:]
            m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', txt)
            return str(m.group(1) or "").strip() if m else ""
        except Exception:
            return ""

    def _normalize_sha256(self, value):
        try:
            raw = str(value or "").strip().lower()
            if not raw:
                return ""
            m = re.search(r"([a-f0-9]{64})", raw)
            if not m:
                return ""
            return str(m.group(1) or "")
        except Exception:
            return ""

    def _file_sha256(self, file_path):
        try:
            h = hashlib.sha256()
            with open(file_path, "rb") as f:
                while True:
                    chunk = f.read(8192)
                    if not chunk:
                        break
                    h.update(chunk)
            return h.hexdigest().lower()
        except Exception:
            return ""

    def _engine_plugins_dir(self):
        try:
            p = os.path.join(str(ApplicationLoader.applicationContext.getFilesDir()), "plugins")
            if not os.path.isdir(p):
                os.makedirs(p, exist_ok=True)
            return p
        except Exception:
            return None

    def _engine_download_to_file(self, url, out_path):
        try:
            candidates = [str(url or "").strip()]
            try:
                u = candidates[0]
                if "/core/" in u:
                    candidates.append(u.replace("/core/", "/", 1))
            except Exception:
                pass
            for base_url in [c for c in candidates if c]:
                try:
                    sep = "&" if "?" in base_url else "?"
                    bust = int(time.time())
                    fetch_url = f"{base_url}{sep}_engine_bust={bust}"
                    resp = requests.get(
                        fetch_url,
                        timeout=25,
                        headers={
                            "Cache-Control": "no-cache, no-store, must-revalidate",
                            "Pragma": "no-cache",
                            "Expires": "0",
                        },
                    )
                    if resp.status_code != 200 or not resp.content:
                        continue
                    with open(out_path, "wb") as f:
                        f.write(resp.content)
                    if os.path.isfile(out_path) and os.path.getsize(out_path) > 0:
                        return True
                except Exception:
                    continue
            return False
        except Exception:
            return False

    def _engine_hash_ok(self, file_path, expected_sha256):
        try:
            if not expected_sha256:
                return True
            got = self._file_sha256(file_path)
            if not got:
                return False
            return got == str(expected_sha256 or "").lower()
        except Exception:
            return False

    def _engine_load_from_file(self, file_path):
        try:
            from com.exteragram.messenger.plugins import PluginsConstants
            CallbackClass = Utilities.Callback
            RunnableClass = jclass("java.lang.Runnable")
        except Exception:
            return False, "runtime_unavailable"
        done = {"ok": False, "error": ""}
        ev = threading.Event()
        class _Cb(dynamic_proxy(CallbackClass)):
            def run(self, error):
                try:
                    done["ok"] = not bool(error)
                    if error:
                        try:
                            done["error"] = str(error)
                        except Exception:
                            done["error"] = "load_failed"
                except Exception:
                    done["ok"] = False
                ev.set()
        class _Run(dynamic_proxy(RunnableClass)):
            def run(self):
                try:
                    PluginsController.engines.get(PluginsConstants.PYTHON).loadPluginFromFile(file_path, None, _Cb())
                except Exception:
                    try:
                        done["error"] = "queue_load_exception"
                    except Exception:
                        pass
                    try:
                        ev.set()
                    except Exception:
                        pass
        try:
            Utilities.pluginsQueue.postRunnable(_Run())
            ev.wait(20.0)
            return bool(done.get("ok", False)), str(done.get("error", "") or "")
        except Exception:
            return False, "queue_post_exception"

    def _engine_notify(self, ok, text):
        try:
            msg = str(text or "").strip()
            if not msg:
                return
            def _show():
                try:
                    fr = get_last_fragment()
                    if ok:
                        BulletinHelper.show_success(msg, fr) if fr else BulletinHelper.show_success(msg)
                    else:
                        BulletinHelper.show_info(msg, fr) if fr else BulletinHelper.show_info(msg)
                except Exception:
                    pass
            run_on_ui_thread(_show)
        except Exception:
            pass

    def _nowfy_notify(self, ok, text):
        try:
            if not bool(self.get_setting("nowfy_bootstrap_notice_enabled", False)):
                return
            msg = str(text or "").strip()
            if not msg:
                return
            def _show():
                try:
                    fr = get_last_fragment()
                    if ok:
                        BulletinHelper.show_success(msg, fr) if fr else BulletinHelper.show_success(msg)
                    else:
                        BulletinHelper.show_info(msg, fr) if fr else BulletinHelper.show_info(msg)
                except Exception:
                    pass
            run_on_ui_thread(_show)
        except Exception:
            pass

    def _engine_enable_plugin(self, plugin_id):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return False
            ctrl = PluginsController.getInstance()
            if not ctrl:
                return False
            try:
                p = ctrl.plugins.get(pid)
                if p and hasattr(p, "isEnabled") and bool(p.isEnabled()):
                    return True
            except Exception:
                pass
            try:
                ctrl.setPluginEnabled(pid, True, None)
            except Exception:
                pass
            try:
                ev = threading.Event()
                RunnableClass = jclass("java.lang.Runnable")
                class _Run(dynamic_proxy(RunnableClass)):
                    def run(self):
                        try:
                            try:
                                c2 = PluginsController.getInstance()
                                if c2:
                                    c2.setPluginEnabled(pid, True, None)
                                    try:
                                        p2q = c2.plugins.get(pid)
                                        if p2q and hasattr(p2q, "setEnabled"):
                                            p2q.setEnabled(True)
                                    except Exception:
                                        pass
                            except Exception:
                                pass
                        finally:
                            try:
                                ev.set()
                            except Exception:
                                pass
                try:
                    Utilities.pluginsQueue.postRunnable(_Run())
                    ev.wait(4.0)
                except Exception:
                    pass
            except Exception:
                pass
            try:
                p2 = ctrl.plugins.get(pid)
                if p2 and hasattr(p2, "isEnabled") and bool(p2.isEnabled()):
                    return True
            except Exception:
                pass
            try:
                if p2 and hasattr(p2, "setEnabled"):
                    p2.setEnabled(True)
            except Exception:
                pass
            try:
                p3 = ctrl.plugins.get(pid)
                return bool(p3 and hasattr(p3, "isEnabled") and p3.isEnabled())
            except Exception:
                return False
        except Exception:
            return False

    def _engine_is_plugin_enabled(self, plugin_id):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return False
            ctrl = PluginsController.getInstance()
            if not ctrl:
                return False
            p = ctrl.plugins.get(pid)
            return bool(p and hasattr(p, "isEnabled") and bool(p.isEnabled()))
        except Exception:
            return False

    def _engine_get_plugin_diag(self, plugin_id):
        out = {
            "registered": False,
            "enabled": False,
            "has_error": False,
            "error": "",
            "version": "",
        }
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return out
            ctrl = PluginsController.getInstance()
            if not ctrl:
                return out
            p = ctrl.plugins.get(pid)
            if not p:
                return out
            out["registered"] = True
            try:
                out["enabled"] = bool(hasattr(p, "isEnabled") and bool(p.isEnabled()))
            except Exception:
                out["enabled"] = False
            try:
                out["version"] = str(p.getVersion() or "").strip()
            except Exception:
                out["version"] = ""
            try:
                if hasattr(p, "hasError") and bool(p.hasError()):
                    out["has_error"] = True
                    try:
                        out["error"] = str(p.getError() or "").strip()
                    except Exception:
                        out["error"] = "plugin_error"
            except Exception:
                pass
            return out
        except Exception:
            return out

    def _engine_wait_enabled_state(self, plugin_id, attempts=6, sleep_sec=0.25):
        try:
            for _ in range(max(1, int(attempts))):
                if self._engine_is_plugin_enabled(plugin_id):
                    return True
                try:
                    time.sleep(float(sleep_sec))
                except Exception:
                    pass
            return self._engine_is_plugin_enabled(plugin_id)
        except Exception:
            return False

    def _engine_enable_with_retry(self, plugin_id, attempts=3, sleep_sec=0.7):
        try:
            if self._engine_enable_plugin(plugin_id):
                return True
            for _ in range(max(1, int(attempts))):
                time.sleep(float(sleep_sec))
                if self._engine_enable_plugin(plugin_id):
                    return True
            return False
        except Exception:
            return False

    def _engine_recover_and_enable(self, plugin_id):
        try:
            pid = str(plugin_id or "").strip()
            if not pid:
                return False
            path = self._engine_get_plugin_file_path(pid, must_exist=True)
            for _ in range(3):
                if path:
                    try:
                        self._engine_load_from_file(path)
                        time.sleep(0.55)
                    except Exception:
                        pass
                if self._engine_enable_with_retry(pid, attempts=25, sleep_sec=0.35):
                    if self._engine_wait_enabled_state(pid, attempts=10, sleep_sec=0.25):
                        return True
                try:
                    dg = self._engine_get_plugin_diag(pid)
                    if bool(dg.get("has_error", False)):
                        return False
                except Exception:
                    pass
            return bool(self._engine_wait_enabled_state(pid, attempts=10, sleep_sec=0.25))
        except Exception:
            return False

    def _ensure_engine_installed(self):
        try:
            if not bool(self.get_setting("engine_auto_install_enabled", False)):
                try:
                    self.set_setting("engine_last_status", "disabled")
                except Exception:
                    pass
                return False
            with self._engine_install_lock:
                if bool(self._engine_install_busy):
                    return False
                self._engine_install_busy = True
            manifest = self._fetch_engine_manifest()
            if not manifest:
                try:
                    self.set_setting("engine_last_status", "manifest_missing")
                    self.set_setting("engine_last_error", "manifest_missing")
                except Exception:
                    pass
                return False
            plugin_id = str(manifest.get("plugin_id", "nowfy_engine") or "nowfy_engine")
            remote_version = str(manifest.get("version", "0.0.0") or "0.0.0")
            plugin_url = str(manifest.get("plugin_url", "") or "")
            expected_sha = str(manifest.get("sha256", "") or "")
            force = bool(manifest.get("force", False))
            local_version = self._get_installed_plugin_version(plugin_id)
            if (not force) and self._parse_version_tuple(local_version) >= self._parse_version_tuple(remote_version):
                try:
                    self.set_setting("engine_last_status", "up_to_date")
                    self.set_setting("engine_last_version", local_version)
                    self.set_setting("engine_last_check_ts", str(int(time.time())))
                except Exception:
                    pass
                return True
            plugins_dir = self._engine_plugins_dir()
            if not plugins_dir:
                try:
                    self.set_setting("engine_last_status", "plugins_dir_error")
                    self.set_setting("engine_last_error", "plugins_dir_error")
                except Exception:
                    pass
                return False
            tmp_path = os.path.join(plugins_dir, f".tmp_{plugin_id}.plugin")
            if not self._engine_download_to_file(plugin_url, tmp_path):
                try:
                    self.set_setting("engine_last_status", "download_failed")
                    self.set_setting("engine_last_error", plugin_url)
                except Exception:
                    pass
                self._engine_notify(False, "Nowfy Engine download failed.")
                return False
            if not self._engine_hash_ok(tmp_path, expected_sha):
                got_sha = self._file_sha256(tmp_path)
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass
                try:
                    self.set_setting("engine_last_status", "hash_failed")
                    self.set_setting("engine_last_error", f"expected={expected_sha or '-'} got={got_sha or '-'}")
                except Exception:
                    pass
                self._engine_notify(False, "Nowfy Engine integrity check failed (manifest hash mismatch).")
                return False
            ok, err = self._engine_load_from_file(tmp_path)
            try:
                os.remove(tmp_path)
            except Exception:
                pass
            if ok:
                enabled_ok = self._engine_enable_with_retry(plugin_id)
                try:
                    self.set_setting("engine_last_version", remote_version)
                    self.set_setting("engine_last_check_ts", str(int(time.time())))
                    self.set_setting("engine_last_status", "installed_enabled" if enabled_ok else "installed_disabled")
                    self.set_setting("engine_last_error", "")
                except Exception:
                    pass
                if enabled_ok:
                    self._engine_notify(True, f"Nowfy Engine installed and enabled ({remote_version}).")
                else:
                    self._engine_notify(True, f"Nowfy Engine installed ({remote_version}). Enable it if needed.")
            else:
                try:
                    self.set_setting("engine_last_status", "install_failed")
                    self.set_setting("engine_last_error", str(err or "install_failed"))
                    self.set_setting("engine_last_check_ts", str(int(time.time())))
                except Exception:
                    pass
                self._engine_notify(False, "Nowfy Engine install failed.")
            return ok
        except Exception:
            try:
                self.set_setting("engine_last_status", "exception")
                self.set_setting("engine_last_error", traceback.format_exc()[:300])
            except Exception:
                pass
            return False
        finally:
            try:
                with self._engine_install_lock:
                    self._engine_install_busy = False
            except Exception:
                pass

    def _ensure_nowfy_installed(self):
        try:
            if not bool(self.get_setting("nowfy_auto_install_enabled", False)):
                try:
                    self.set_setting("nowfy_last_status", "disabled")
                except Exception:
                    pass
                return False
            with self._nowfy_install_lock:
                if bool(self._nowfy_install_busy):
                    return False
                self._nowfy_install_busy = True
            manifest = self._fetch_nowfy_manifest()
            manifest_missing = not bool(manifest)
            if not manifest:
                manifest = {
                    "plugin_id": "nowfy",
                    "version": "0.0.0",
                    "plugin_url": self._get_nowfy_plugin_url(),
                    "sha256": "",
                    "force": False,
                }
            plugin_id = str(manifest.get("plugin_id", "nowfy") or "nowfy")
            remote_version = str(manifest.get("version", "0.0.0") or "0.0.0")
            plugin_url = str(manifest.get("plugin_url", "") or "")
            expected_sha = str(manifest.get("sha256", "") or "")
            force = bool(manifest.get("force", False))
            try:
                auto_enable_pending = bool(self.get_setting("nowfy_auto_enable_pending", False))
            except Exception:
                auto_enable_pending = False
            allow_auto_enable_once = bool(auto_enable_pending)
            bootstrap_feedback = bool(auto_enable_pending)
            try:
                ctrl = PluginsController.getInstance()
                p_exist = ctrl.plugins.get(plugin_id) if ctrl else None
                if p_exist and hasattr(p_exist, "isEnabled") and bool(p_exist.isEnabled()):
                    already_enabled = True
                else:
                    already_enabled = False
            except Exception:
                already_enabled = False
            local_version = self._get_installed_plugin_version(plugin_id)
            local_file_ok = self._is_plugin_file_present(plugin_id)
            is_fresh_install_flow = not bool(local_file_ok)
            if is_fresh_install_flow:
                allow_auto_enable_once = True
                bootstrap_feedback = True
                try:
                    self.set_setting("nowfy_auto_enable_pending", True)
                except Exception:
                    pass
            try:
                probed_version = self._probe_remote_plugin_version(plugin_url, cache_key="nowfy_remote_version")
                if probed_version:
                    remote_version = probed_version
                    if manifest_missing:
                        force = False
            except Exception:
                pass
            if local_version and local_file_ok and (not force) and self._parse_version_tuple(local_version) >= self._parse_version_tuple(remote_version):
                plugin_registered = False
                try:
                    ctrl2 = PluginsController.getInstance()
                    pp = ctrl2.plugins.get(plugin_id) if ctrl2 else None
                    plugin_registered = bool(pp)
                except Exception:
                    plugin_registered = False
                if not plugin_registered:
                    local_path = self._engine_get_plugin_file_path(plugin_id, must_exist=True)
                    if local_path:
                        rec_ok, rec_err = self._engine_load_from_file(local_path)
                        if rec_ok:
                            plugin_registered = True
                            try:
                                time.sleep(0.35)
                            except Exception:
                                pass
                        else:
                            try:
                                pass
                            except Exception:
                                pass
                            local_version = ""
                            local_file_ok = False
                    else:
                        local_version = ""
                        local_file_ok = False
                if local_version and local_file_ok:
                    enabled_ok = bool(already_enabled or self._engine_is_plugin_enabled(plugin_id))
                    prev_status = ""
                    try:
                        prev_status = str(self.get_setting("nowfy_last_status", "") or "")
                    except Exception:
                        prev_status = ""
                    if (not enabled_ok) and allow_auto_enable_once:
                        enabled_ok = self._engine_enable_with_retry(plugin_id, attempts=20, sleep_sec=0.8)
                        if enabled_ok:
                            try:
                                self.set_setting("nowfy_auto_enable_pending", False)
                            except Exception:
                                pass
                    try:
                        self.set_setting("nowfy_last_status", "up_to_date_enabled" if enabled_ok else "up_to_date_disabled")
                        self.set_setting("nowfy_last_version", local_version)
                        self.set_setting("nowfy_last_check_ts", str(int(time.time())))
                    except Exception:
                        pass
                    enabled_ok = bool(self._engine_wait_enabled_state(plugin_id, attempts=5, sleep_sec=0.2))
                    if enabled_ok:
                        if bootstrap_feedback:
                            self._nowfy_notify(True, core_tr("nowfy_bootstrap_initialized"))
                        return True
                    if prev_status != "up_to_date_disabled":
                        self._nowfy_notify(False, "Nowfy is installed but disabled.")
                    return False
            plugins_dir = self._engine_plugins_dir()
            if not plugins_dir:
                try:
                    self.set_setting("nowfy_last_status", "plugins_dir_error")
                    self.set_setting("nowfy_last_error", "plugins_dir_error")
                except Exception:
                    pass
                self._nowfy_notify(False, "Nowfy install failed.")
                return False
            tmp_path = os.path.join(plugins_dir, f".tmp_{plugin_id}.plugin")
            final_path = os.path.join(plugins_dir, f"{plugin_id}.plugin")
            dl_url = plugin_url
            try:
                sep_dl = "&" if "?" in dl_url else "?"
                dl_url = f"{dl_url}{sep_dl}_dl_bust={int(time.time())}"
            except Exception:
                dl_url = plugin_url
            if not self._engine_download_to_file(dl_url, tmp_path):
                try:
                    self.set_setting("nowfy_last_status", "download_failed")
                    self.set_setting("nowfy_last_error", dl_url)
                except Exception:
                    pass
                self._nowfy_notify(False, "Nowfy download failed.")
                return False
            if not self._engine_hash_ok(tmp_path, expected_sha):
                try:
                    got_sha = self._file_sha256(tmp_path)
                    os.remove(tmp_path)
                except Exception:
                    got_sha = ""
                try:
                    self.set_setting("nowfy_last_status", "hash_failed")
                    self.set_setting("nowfy_last_error", f"expected={expected_sha or '-'} got={got_sha or '-'}")
                except Exception:
                    pass
                self._nowfy_notify(False, "Nowfy integrity check failed.")
                return False
            try:
                os.replace(tmp_path, final_path)
            except Exception:
                try:
                    with open(tmp_path, "rb") as rf:
                        raw = rf.read()
                    with open(final_path, "wb") as wf:
                        wf.write(raw)
                    os.remove(tmp_path)
                except Exception:
                    try:
                        os.remove(tmp_path)
                    except Exception:
                        pass
                    try:
                        self.set_setting("nowfy_last_status", "persist_failed")
                        self.set_setting("nowfy_last_error", final_path)
                    except Exception:
                        pass
                    self._nowfy_notify(False, "Nowfy install failed (persist).")
                    return False
            ok, err = self._engine_load_from_file(final_path)
            installed_file_version = self._read_plugin_version_from_file(final_path)
            try:
                if not ok:
                    pass
            except Exception:
                pass
            if ok:
                enabled_ok = bool(already_enabled or self._engine_is_plugin_enabled(plugin_id))
                if not enabled_ok:
                    enabled_ok = self._engine_recover_and_enable(plugin_id)
                    if enabled_ok:
                        try:
                            self.set_setting("nowfy_auto_enable_pending", False)
                        except Exception:
                            pass
                file_ok_after = self._is_plugin_file_present(plugin_id)
                enabled_ok = bool(self._engine_wait_enabled_state(plugin_id, attempts=8, sleep_sec=0.25))
                final_version = str(installed_file_version or self._get_installed_plugin_version(plugin_id) or remote_version or "").strip() or remote_version
                if not local_file_ok:
                    try:
                        self.set_setting(self._get_nowfy_welcome_seen_key(), False)
                    except Exception:
                        pass
                try:
                    self.set_setting("nowfy_last_version", final_version)
                    self.set_setting("nowfy_last_check_ts", str(int(time.time())))
                    self.set_setting("nowfy_last_status", "installed_enabled" if (enabled_ok and file_ok_after) else "installed_disabled")
                    self.set_setting("nowfy_last_error", "")
                except Exception:
                    pass
                if enabled_ok and file_ok_after:
                    self._nowfy_notify(True, core_tr("nowfy_bootstrap_initialized"))
                else:
                    dg = self._engine_get_plugin_diag(plugin_id)
                    reason = ""
                    try:
                        if not bool(dg.get("registered", False)):
                            reason = "not registered in controller"
                        elif bool(dg.get("has_error", False)):
                            ee = str(dg.get("error", "") or "").strip()
                            reason = f"plugin error{(': ' + ee) if ee else ''}"
                        else:
                            reason = "enable attempt failed"
                    except Exception:
                        reason = "enable attempt failed"
                    try:
                        self.set_setting("nowfy_last_error", str(reason or "disabled"))
                    except Exception:
                        pass
                    self._nowfy_notify(False, f"Nowfy installed ({final_version}) but disabled. {reason}")
                return bool(enabled_ok and file_ok_after)
            try:
                self.set_setting("nowfy_last_status", "install_failed")
                self.set_setting("nowfy_last_error", str(err or "install_failed"))
                self.set_setting("nowfy_last_check_ts", str(int(time.time())))
            except Exception:
                pass
            self._nowfy_notify(False, "Nowfy install failed.")
            return False
        except Exception:
            try:
                self.set_setting("nowfy_last_status", "exception")
                self.set_setting("nowfy_last_error", traceback.format_exc()[:300])
            except Exception:
                pass
            self._nowfy_notify(False, "Nowfy install exception.")
            return False
        finally:
            try:
                with self._nowfy_install_lock:
                    self._nowfy_install_busy = False
            except Exception:
                pass

    def _core_remote_cache_path(self, key):
        try:
            base = self._core_remote_dir
            if base is None:
                base = File(ApplicationLoader.getFilesDirFixed(), "nowfycore_remote")
                if not base.exists():
                    base.mkdirs()
                self._core_remote_dir = base
            safe = re.sub(r"[^a-zA-Z0-9_.-]", "_", str(key or "data"))
            return File(base, f"{safe}.json").getAbsolutePath()
        except Exception:
            return None

    def _core_remote_cache_write(self, key, payload_obj):
        try:
            p = self._core_remote_cache_path(key)
            if not p:
                return
            with open(p, "w", encoding="utf-8") as f:
                json.dump(payload_obj, f, ensure_ascii=False)
        except Exception:
            pass

    def _core_remote_cache_read(self, key):
        try:
            p = self._core_remote_cache_path(key)
            if not p or not os.path.isfile(p):
                return None
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None

    def _core_remote_fetch_json(self, url, cache_key, timeout=8):
        try:
            sep = "&" if "?" in url else "?"
            bust = int(time.time())
            fetch_url = f"{url}{sep}_nowfy_bust={bust}"
            resp = requests.get(
                fetch_url,
                timeout=timeout,
                headers={
                    "Cache-Control": "no-cache, no-store, must-revalidate",
                    "Pragma": "no-cache",
                    "Expires": "0",
                },
            )
            if resp.status_code == 200 and resp.content:
                data = None
                try:
                    data = resp.json()
                except Exception:
                    raw_text = resp.content.decode("utf-8", errors="replace")
                    while raw_text.startswith("\ufeff"):
                        raw_text = raw_text[1:]
                    data = json.loads(raw_text)
                if data is not None:
                    self._core_remote_cache_write(cache_key, data)
                    return data
        except Exception:
            pass
        return self._core_remote_cache_read(cache_key)

    def _core_pack_get_value(self, key, default=None):
        try:
            base = self._get_corepack_base_url()
            if not base:
                return default
            cfg = self._core_remote_fetch_json(f"{base}/config.json", "corepack_config", timeout=8)
            if isinstance(cfg, dict):
                return cfg.get(key, default)
        except Exception:
            pass
        return default

    def _refresh_remote_translations_pack(self):
        try:
            base = self._get_corepack_base_url()
            if not base:
                return False
            candidates = [
                (f"{base}/nowfycore_translations.pack.json", "corepack_translations_root"),
                (f"{base}/core/nowfycore_translations.pack.json", "corepack_translations_core_folder"),
                (f"{base}/translations.json", "corepack_translations"),
                (f"{base}/corepack/translations.json", "corepack_translations_nested"),
            ]
            payload = None
            for url, ck in candidates:
                payload = self._core_remote_fetch_json(url, ck, timeout=4)
                if isinstance(payload, dict) and payload:
                    break
            data = None
            if isinstance(payload, dict):
                if isinstance(payload.get("translations"), dict):
                    data = payload.get("translations")
                else:
                    data = payload
            if not isinstance(data, dict) or not data:
                return False
            TRANSLATIONS.clear()
            TRANSLATIONS.update(data)
            try:
                self._core_remote_cache_write("nowfycore_translations.remote.cache", data)
            except Exception:
                pass
            try:
                self._prefetch_core_static_assets()
            except Exception:
                pass
            return True
        except Exception:
            return False

    def _prefetch_core_static_assets(self):
        try:
            import os
            from hook_utils import find_class
            BitmapFactory = find_class("android.graphics.BitmapFactory")
            base = str(self._get_corepack_base_url() or "https://coreupdates.meyankut.workers.dev").rstrip("/")
            assets = [
                ("extended_icon.png", "nowfy_home_extended_icon.png"),
                ("cards_icon.png", "nowfy_home_cards_icon.png"),
                ("support.png", "nowfy_home_support_icon.png"),
            ]
            cache_dir = None
            try:
                if hasattr(self, "_di_cache_dir"):
                    cache_dir = self._di_cache_dir()
            except Exception:
                cache_dir = None
            if not cache_dir:
                cache_dir = ApplicationLoader.getFilesDirFixed()
            try:
                os.makedirs(str(cache_dir), exist_ok=True)
            except Exception:
                pass
            any_ok = False
            for remote_name, local_name in assets:
                try:
                    local_path = os.path.join(str(cache_dir), local_name)
                except Exception:
                    local_path = None
                try:
                    if local_path and os.path.exists(local_path) and os.path.getsize(local_path) > 64:
                        any_ok = True
                        continue
                except Exception:
                    pass
                url = f"{base}/{remote_name}"
                data = None
                try:
                    if hasattr(self, "_get_cached_image_enhanced"):
                        data = self._get_cached_image_enhanced(url, cache_key=f"core_asset_{remote_name}")
                except Exception:
                    data = None
                if not data:
                    try:
                        resp = requests.get(url, headers={"Cache-Control": "no-cache"}, timeout=(5, 10))
                        if resp.status_code == 200 and resp.content:
                            data = resp.content
                    except Exception:
                        data = None
                if not data:
                    continue
                try:
                    if BitmapFactory:
                        bmp = BitmapFactory.decodeByteArray(data, 0, len(data))
                        if not bmp:
                            continue
                except Exception:
                    pass
                try:
                    if local_path:
                        with open(local_path, "wb") as f:
                            f.write(data)
                        any_ok = True
                except Exception:
                    pass
            return any_ok
        except Exception:
            return False

