    def _get_nowfy_welcome_display_name(self, plugin):
        try:
            uc = get_user_config()
            mc = get_messages_controller()
            if uc and mc:
                user = mc.getUser(uc.getClientUserId())
                if user:
                    name = str(getattr(user, "first_name", None) or getattr(user, "username", None) or "").strip()
                    if name:
                        return name
        except Exception:
            pass
        try:
            if plugin:
                name = str(plugin.get_setting("exteragram_username", "") or "").strip()
                if name:
                    return name.lstrip("@")
        except Exception:
            pass
        return "User"

